class MockDatabase extends EventTarget {
  private users: User[] = [];
  private menu: MenuItem[] = [];
  private orders: Order[] = [];
  private slots: PickupSlot[] = [];
  private currentUser: User | null = null;

  constructor() {
    super();
    this.loadData();
  }

  private loadData() {
    // Simulate persistent storage
    const storedMenu = localStorage.getItem('qb_menu');
    const storedUsers = localStorage.getItem('qb_users');
    const storedOrders = localStorage.getItem('qb_orders');

    this.menu = storedMenu ? JSON.parse(storedMenu) : INITIAL_MENU;
    this.users = storedUsers ? JSON.parse(storedUsers) : INITIAL_USERS;
    this.orders = storedOrders ? JSON.parse(storedOrders) : [];

    // Generate slots for the day
    this.generateSlots();
  }

  private saveData() {
    localStorage.setItem('qb_menu', JSON.stringify(this.menu));
    localStorage.setItem('qb_users', JSON.stringify(this.users));
    localStorage.setItem('qb_orders', JSON.stringify(this.orders));
    this.dispatchEvent(new Event('change'));
  }

  private generateSlots() {
    const slots: PickupSlot[] = [];
    let hour = 9; // 9 AM
    for (let i = 0; i < 10; i++) {
      const time = `${hour}:00 - ${hour}:30`;
      slots.push({
        id: `slot-${i}`,
        time,
        capacity: 5,
        booked: 0,
        available: true
      });
      hour++;
    }
    this.slots = slots;
  }

  // Auth Methods
  async login(email: string): Promise<User> {
    const user = this.users.find(u => u.email === email);
    if (!user) throw new Error('User not found');
    this.currentUser = user;
    localStorage.setItem('qb_current_user', JSON.stringify(user));
    return user;
  }

  logout() {
    this.currentUser = null;
    localStorage.removeItem('qb_current_user');
    window.location.reload();
  }

  getCurrentUser(): User | null {
    if (this.currentUser) return this.currentUser;
    const stored = localStorage.getItem('qb_current_user');
    if (stored) {
      this.currentUser = JSON.parse(stored);
      return this.currentUser;
    }
    return null;
  }

  // Menu Methods
  getMenu() {
    return [...this.menu];
  }

  addMenuItem(item: Omit<MenuItem, 'id'>) {
    const newItem = { ...item, id: Math.random().toString(36).substr(2, 9) };
    this.menu.push(newItem);
    this.saveData();
  }

  deleteMenuItem(id: string) {
    this.menu = this.menu.filter(item => item.id !== id);
    this.saveData();
  }

  // Order Methods
  getOrders() {
    return [...this.orders];
  }

  getOrdersForUser(userId: string) {
    return this.orders.filter(o => o.userId === userId).sort((a, b) => b.createdAt - a.createdAt);
  }

  createOrder(items: CartItem[], totalAmount: number, pickupSlotId: string): Order {
    if (!this.currentUser) throw new Error('Must be logged in');

    // Update slot capacity
    const slotIndex = this.slots.findIndex(s => s.id === pickupSlotId);
    if (slotIndex >= 0) {
        if (this.slots[slotIndex].booked >= this.slots[slotIndex].capacity) {
            throw new Error('Slot full');
        }
        this.slots[slotIndex].booked += 1;
        if (this.slots[slotIndex].booked >= this.slots[slotIndex].capacity) {
            this.slots[slotIndex].available = false;
        }
    }

    const newOrder: Order = {
      id: `ORD-${Math.floor(Math.random() * 10000)}`,
      userId: this.currentUser.id,
      items,
      totalAmount,
      status: OrderStatus.CONFIRMED,
      createdAt: Date.now(),
      pickupTime: this.slots.find(s => s.id === pickupSlotId)?.time || 'Unknown',
      pickupSlotId
    };

    this.orders.unshift(newOrder); // Add to top
    this.saveData();
    return newOrder;
  }

  updateOrderStatus(orderId: string, status: OrderStatus) {
    const order = this.orders.find(o => o.id === orderId);
    if (order) {
      order.status = status;
      this.saveData();
    }
  }

  // Slots
  getSlots() {
    return [...this.slots];
  }

  // Admin Stats
  getStats() {
    return {
      totalOrders: this.orders.length,
      totalRevenue: this.orders.reduce((acc, o) => acc + o.totalAmount, 0),
      totalUsers: this.users.length,
    };
  }
}

export const db = new MockDatabase();

import { GoogleGenAI } from "@google/genai";
import { MenuItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getMealSuggestion = async (preference: string, menu: MenuItem[]) => {
  try {
    const menuString = JSON.stringify(menu.map(m => ({ name: m.name, desc: m.description, category: m.category, isVeg: m.isVeg, price: m.price })));

    const prompt = `
      You are a food expert at Quickbite Canteen.
      Here is our current menu: ${menuString}

      User Preference: "${preference}"

      Task: Select the single best item from the menu that matches the preference.
      Return ONLY a valid JSON object in this format (do not use markdown code blocks):
      {
        "suggestedItemName": "Exact Name from Menu",
        "reason": "A short, appetizing explanation of why this fits."
      }
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json'
      }
    });

    return JSON.parse(response.text || '{}');
  } catch (error) {
    console.error("AI Suggestion Error:", error);
    throw error;
  }
};

export const chatWithSupport = async (message: string, history: {role: string, content: string}[]) => {
  try {
    const systemInstruction = `
      You are Quickbite's friendly AI support assistant.
      Your Role: Help students with ordering food, pickup slots, payments, and finding menu items on the Quickbite app.
      Rules:
      1. ONLY answer questions related to the Quickbite app/canteen.
      2. If asked about homework, math, or general knowledge, politely refuse and say you are only here for food.
      3. Be concise and cheerful.
      4. If users ask about order status, tell them to check the 'Orders' page.
    `;

    // Convert simple history to Gemini format if needed, but here we just append context.
    // For simplicity in this demo, we'll just send the message with system instruction context.

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: message,
      config: {
        systemInstruction: systemInstruction,
      }
    });

    return response.text;
  } catch (error) {
    console.error("Chatbot Error:", error);
    return "I'm having trouble connecting to the kitchen right now. Please try again!";
  }
};

import React, { useEffect, useState } from 'react';
import { HashRouter, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { User, UserRole } from './types';
import { db } from './services/mockDatabase';
import AuthPage from './pages/Auth';
import CustomerMenu from './pages/Customer/Menu';
import CustomerCart from './pages/Customer/Cart';
