import AdminDashboard from './pages/Admin/Dashboard';
import Chatbot from './components/Chatbot';
import { ShoppingBag, User as UserIcon, LogOut, LayoutDashboard, Coffee } from 'lucide-react';

const Navbar: React.FC<{ user: User | null; onLogout: () => void }> = ({ user, onLogout }) => {
  const location = useLocation();
  const isCustomer = user?.role === UserRole.CUSTOMER;
  const isAdmin = user?.role === UserRole.ADMIN || user?.role === UserRole.SPECIALIZED_ADMIN;

  if (!user) return null;

  return (
    <nav className="sticky top-0 z-50 bg-gray-900 border-b border-gray-800 shadow-md">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          <div className="flex items-center">
            <Coffee className="h-8 w-8 text-orange-500" />
            <span className="ml-2 text-xl font-bold text-white tracking-tight">Quickbite</span>
          </div>

          <div className="flex items-center space-x-4">
            {isCustomer && (
              <>
                <NavLink to="/menu" active={location.pathname === '/menu'}>Menu</NavLink>
                <NavLink to="/orders" active={location.pathname === '/orders'}>Orders</NavLink>
                <NavLink to="/cart" active={location.pathname === '/cart'}>
                  <ShoppingBag className="w-5 h-5" />
                </NavLink>
              </>
            )}
            {isAdmin && (
              <NavLink to="/admin" active={location.pathname.startsWith('/admin')}>Dashboard</NavLink>
            )}

            <div className="flex items-center space-x-2 pl-4 border-l border-gray-700 ml-4">
              <div className="flex flex-col items-end">
                <span className="text-sm font-medium text-gray-200">{user.name}</span>
                <span className="text-xs text-gray-400 capitalize">{user.role.toLowerCase().replace('_', ' ')}</span>
              </div>
              <button 
                onClick={onLogout}
                className="p-2 rounded-full hover:bg-gray-800 text-gray-400 hover:text-red-400 transition-colors"
              >
                <LogOut className="w-5 h-5" />
              </button>
            </div>
          </div>
        </div>
      </div>
    </nav>
  );
};

const NavLink: React.FC<{ to: string; active: boolean; children: React.ReactNode }> = ({ to, active, children }) => (
  <a 
    href={`#${to}`} 
    className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${
      active ? 'bg-orange-500/10 text-orange-500' : 'text-gray-300 hover:text-white hover:bg-gray-800'
    }`}
  >
    {children}
  </a>
);

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const currentUser = db.getCurrentUser();
    setUser(currentUser);
    setLoading(false);

    const handleStorageChange = () => {
       // Listen for auth changes if needed
    };
    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  const handleLogout = () => {
    db.logout();
    setUser(null);
  };

  if (loading) return <div className="min-h-screen bg-gray-950 flex items-center justify-center text-white">Loading Quickbite...</div>;

  return (
    <HashRouter>
      <div className="min-h-screen bg-gray-950 text-gray-100 font-sans selection:bg-orange-500/30">
        <Navbar user={user} onLogout={handleLogout} />

        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          <Routes>
            <Route path="/auth" element={!user ? <AuthPage onLogin={setUser} /> : <Navigate to={user.role === UserRole.CUSTOMER ? "/menu" : "/admin"} />} />

            {/* Customer Routes */}
            <Route path="/menu" element={user?.role === UserRole.CUSTOMER ? <CustomerMenu /> : <Navigate to="/auth" />} />
            <Route path="/cart" element={user?.role === UserRole.CUSTOMER ? <CustomerCart /> : <Navigate to="/auth" />} />
            <Route path="/orders" element={user?.role === UserRole.CUSTOMER ? <CustomerOrders /> : <Navigate to="/auth" />} />

            {/* Admin Routes */}
            <Route path="/admin" element={
              (user?.role === UserRole.ADMIN || user?.role === UserRole.SPECIALIZED_ADMIN) 
              ? <AdminDashboard user={user} /> 
              : <Navigate to="/auth" />
            } />

            <Route path="*" element={<Navigate to={user ? (user.role === UserRole.CUSTOMER ? "/menu" : "/admin") : "/auth"} />} />
          </Routes>
        </main>

        {user?.role === UserRole.CUSTOMER && <Chatbot />}
      </div>
    </HashRouter>
  );
}

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { MessageCircle, X, Send, Bot } from 'lucide-react';
import { chatWithSupport } from '../services/geminiService';

interface Message {
  id: string;
  sender: 'user' | 'bot';
  text: string;
}

const Chatbot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', sender: 'bot', text: 'Hi! I can help with orders, pickup slots, or payment issues. How can I assist you today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg: Message = { id: Date.now().toString(), sender: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const botResponse = await chatWithSupport(input, []);

    setIsTyping(false);
    setMessages(prev => [...prev, { id: (Date.now() + 1).toString(), sender: 'bot', text: botResponse || "Sorry, I'm offline." }]);
  };

  return (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col items-end">
      {isOpen && (
        <div className="mb-4 w-80 sm:w-96 h-[500px] bg-gray-900 border border-gray-700 rounded-2xl shadow-2xl flex flex-col overflow-hidden animate-in fade-in slide-in-from-bottom-10 duration-300">
          {/* Header */}
          <div className="p-4 bg-gradient-to-r from-orange-600 to-red-600 flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <div className="bg-white/20 p-1.5 rounded-full">
                <Bot className="w-5 h-5 text-white" />
              </div>
              <div>
                <h3 className="text-white font-semibold text-sm">Quickbite Support</h3>
                <p className="text-orange-100 text-xs">Always here to help</p>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="text-white/80 hover:text-white">
              <X className="w-5 h-5" />
            </button>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-900">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] px-4 py-2.5 rounded-2xl text-sm leading-relaxed ${
                  msg.sender === 'user' 
                    ? 'bg-orange-600 text-white rounded-tr-none' 
                    : 'bg-gray-800 text-gray-200 rounded-tl-none border border-gray-700'
                }`}>
                  {msg.text}
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-gray-800 px-4 py-3 rounded-2xl rounded-tl-none border border-gray-700 flex space-x-1">
                  <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                  <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                  <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                </div>
              </div>
            )}
          </div>

          {/* Input */}
          <div className="p-3 bg-gray-900 border-t border-gray-800">
            <div className="flex items-center space-x-2 bg-gray-800 rounded-full px-4 py-2 border border-gray-700 focus-within:border-orange-500 transition-colors">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Ask about orders..." 
                className="flex-1 bg-transparent border-none focus:ring-0 text-sm text-white placeholder-gray-500"
              />
              <button 
                onClick={handleSend}
                disabled={!input.trim()}
                className="text-orange-500 hover:text-orange-400 disabled:opacity-50 p-1"
              >
                <Send className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      )}

      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`p-4 rounded-full shadow-lg transition-all duration-300 transform hover:scale-110 ${
          isOpen ? 'bg-gray-700 text-white rotate-90' : 'bg-gradient-to-r from-orange-500 to-red-600 text-white'
        }`}
      >
        {isOpen ? <X className="w-6 h-6" /> : <MessageCircle className="w-6 h-6" />}
      </button>
    </div>
  );
};

export default Chatbot;

