import React, { useState, useEffect } from 'react';
import { db } from '../../services/mockDatabase';
import { MenuItem, FoodCategory, CartItem } from '../../types';
import { Plus, Sparkles, Filter, X } from 'lucide-react';
import { getMealSuggestion } from '../../services/geminiService';

const MenuPage: React.FC = () => {
  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<FoodCategory | 'All'>('All');
  const [aiModalOpen, setAiModalOpen] = useState(false);
  const [preference, setPreference] = useState('');
  const [suggestion, setSuggestion] = useState<{name: string, reason: string} | null>(null);
  const [aiLoading, setAiLoading] = useState(false);

  useEffect(() => {
    setMenu(db.getMenu());
  }, []);

  const addToCart = (item: MenuItem) => {
    const cart: CartItem[] = JSON.parse(localStorage.getItem('qb_cart') || '[]');
    const existing = cart.find(i => i.id === item.id);
    if (existing) {
      existing.quantity += 1;
    } else {
      cart.push({ ...item, quantity: 1 });
    }
    localStorage.setItem('qb_cart', JSON.stringify(cart));
    // Trigger storage event for realtime updates in nav badge (optional but nice)
    window.dispatchEvent(new Event('storage'));

    // Simple toast
    const toast = document.createElement('div');
    toast.className = 'fixed bottom-24 left-1/2 -translate-x-1/2 bg-green-600 text-white px-4 py-2 rounded-full shadow-lg text-sm z-50 animate-in fade-in slide-in-from-bottom-5';
    toast.innerText = `Added ${item.name} to cart`;
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 2000);
  };

  const handleAiSuggest = async () => {
    if (!preference.trim()) return;
    setAiLoading(true);
    setSuggestion(null);
    try {
      const result = await getMealSuggestion(preference, menu);
      if (result.suggestedItemName) {
        setSuggestion({
          name: result.suggestedItemName,
          reason: result.reason
        });
      }
    } catch (e) {
      console.error(e);
    } finally {
      setAiLoading(false);
    }
  };

  const filteredMenu = selectedCategory === 'All' 
    ? menu 
    : menu.filter(m => m.category === selectedCategory);

  return (
    <div className="space-y-8 pb-20">
      {/* Header & AI Trigger */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white">Our Menu</h1>
          <p className="text-gray-400 mt-1">Freshly prepared food for students.</p>
        </div>
        <button 
          onClick={() => setAiModalOpen(true)}
          className="group flex items-center justify-center space-x-2 bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-500 hover:to-indigo-500 text-white px-5 py-3 rounded-xl transition-all shadow-lg shadow-purple-900/20"
        >
          <Sparkles className="w-5 h-5 group-hover:rotate-12 transition-transform" />
          <span className="font-medium">AI Meal Suggester</span>
        </button>
      </div>

      {/* Category Filter */}
      <div className="flex overflow-x-auto space-x-2 pb-2 no-scrollbar">
        {['All', ...Object.values(FoodCategory)].map(cat => (
          <button
            key={cat}
            onClick={() => setSelectedCategory(cat as any)}
            className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-colors border ${
              selectedCategory === cat 
                ? 'bg-orange-500 border-orange-500 text-white' 
                : 'bg-gray-900 border-gray-700 text-gray-300 hover:border-gray-500'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* Menu Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredMenu.map(item => (
          <div key={item.id} className="bg-gray-900 border border-gray-800 rounded-2xl overflow-hidden hover:border-gray-700 transition-colors group">
            <div className="relative h-48 overflow-hidden">
              <img 
                src={item.image} 
                alt={item.name} 
                className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" 
              />
              <div className="absolute top-3 right-3">
                <span className={`px-2 py-1 rounded text-xs font-bold ${item.isVeg ? 'bg-green-900/80 text-green-400 border border-green-700' : 'bg-red-900/80 text-red-400 border border-red-700'}`}>
                  {item.isVeg ? 'VEG' : 'NON-VEG'}
                </span>
              </div>
            </div>
            <div className="p-5">
              <div className="flex justify-between items-start mb-2">
                <h3 className="text-lg font-semibold text-white">{item.name}</h3>
                <span className="text-orange-400 font-bold">₹{item.price}</span>
              </div>
              <p className="text-gray-400 text-sm mb-4 line-clamp-2">{item.description}</p>
              <button 
                onClick={() => addToCart(item)}
                className="w-full flex items-center justify-center space-x-2 bg-gray-800 hover:bg-orange-600 text-white py-2.5 rounded-lg transition-colors border border-gray-700 hover:border-orange-500"
              >
                <Plus className="w-4 h-4" />
                <span>Add to Cart</span>
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* AI Modal */}
      {aiModalOpen && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-gray-900 border border-gray-700 w-full max-w-lg rounded-2xl shadow-2xl overflow-hidden">
            <div className="p-6">
              <div className="flex justify-between items-center mb-6">
                <div className="flex items-center space-x-2 text-purple-400">
                  <Sparkles className="w-5 h-5" />
                  <h2 className="text-xl font-bold text-white">What are you craving?</h2>
                </div>
                <button onClick={() => setAiModalOpen(false)} className="text-gray-400 hover:text-white">
                  <X className="w-6 h-6" />
                </button>
              </div>

              <div className="space-y-4">
                <textarea
                  value={preference}
                  onChange={(e) => setPreference(e.target.value)}
                  placeholder='e.g., "I want something spicy and filling for lunch, but vegetarian."'
                  className="w-full bg-gray-800 border border-gray-700 rounded-xl p-4 text-white focus:ring-2 focus:ring-purple-500 outline-none resize-none h-32"
                />

                <button
                  onClick={handleAiSuggest}
                  disabled={aiLoading || !preference}
                  className="w-full bg-purple-600 hover:bg-purple-500 disabled:bg-gray-800 disabled:text-gray-500 text-white font-semibold py-3 rounded-xl transition-colors flex items-center justify-center"
                >
                  {aiLoading ? 'Analyzing Menu...' : 'Find My Meal'}
                </button>
              </div>

              {suggestion && (
                <div className="mt-6 bg-gray-800/50 border border-purple-500/30 rounded-xl p-4 animate-in fade-in slide-in-from-bottom-4">
                  <p className="text-purple-300 text-xs font-bold uppercase tracking-wide mb-1">AI Suggestion</p>
                  <h3 className="text-lg font-bold text-white mb-2">{suggestion.name}</h3>
                  <p className="text-gray-300 text-sm italic">"{suggestion.reason}"</p>

                  <div className="mt-4 flex justify-end">
                    <button 
                      onClick={() => {
                        const item = menu.find(m => m.name === suggestion.name);
                        if (item) {
                          addToCart(item);
                          setAiModalOpen(false);
                        }
                      }}
                      className="text-sm bg-white text-purple-900 font-bold px-4 py-2 rounded-lg hover:bg-gray-200 transition-colors"
                    >
                      Add This to Cart
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MenuPage;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { db } from '../../services/mockDatabase';
import { CartItem, PickupSlot } from '../../types';
import { Trash2, Plus, Minus, CreditCard, Clock, ChevronRight } from 'lucide-react';

const CartPage: React.FC = () => {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [slots, setSlots] = useState<PickupSlot[]>([]);
  const [selectedSlot, setSelectedSlot] = useState<string | null>(null);
  const [paying, setPaying] = useState(false);
  const [error, setError] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    const load = () => {
      const stored = localStorage.getItem('qb_cart');
      if (stored) setCart(JSON.parse(stored));
      setSlots(db.getSlots());
    };
    load();
    window.addEventListener('storage', load);
    return () => window.removeEventListener('storage', load);
  }, []);

  const updateQty = (id: string, delta: number) => {
    const newCart = cart.map(item => {
      if (item.id === id) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    });
    setCart(newCart);
    localStorage.setItem('qb_cart', JSON.stringify(newCart));
  };

  const remove = (id: string) => {
    const newCart = cart.filter(item => item.id !== id);
    setCart(newCart);
    localStorage.setItem('qb_cart', JSON.stringify(newCart));
  };

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const handlePayment = async () => {
    if (!selectedSlot) return setError('Please select a pickup time.');
    setPaying(true);
    setError('');

    try {
      // Simulate Razorpay opening and processing
      await new Promise(resolve => setTimeout(resolve, 2000));

      // Randomly fail payment for simulation realism (1 in 10 chance)
      if (Math.random() > 0.95) throw new Error('Payment Failed: Bank declined transaction.');

      db.createOrder(cart, total, selectedSlot);
      localStorage.removeItem('qb_cart');
      setCart([]);
      navigate('/orders');
    } catch (err: any) {
      setError(err.message || 'Payment failed');
    } finally {
      setPaying(false);
    }
  };

  if (cart.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] text-center">
        <div className="bg-gray-900 p-6 rounded-full mb-4">
          <CreditCard className="w-10 h-10 text-gray-600" />
        </div>
        <h2 className="text-xl font-bold text-white mb-2">Your cart is empty</h2>
        <p className="text-gray-400 mb-6">Looks like you haven't added anything yet.</p>
        <button onClick={() => navigate('/menu')} className="bg-orange-600 text-white px-6 py-2 rounded-lg hover:bg-orange-500 transition-colors">
          Browse Menu
        </button>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      {/* Cart Items */}
      <div className="lg:col-span-2 space-y-6">
        <h1 className="text-2xl font-bold text-white mb-6">Your Cart ({cart.length} items)</h1>

        <div className="space-y-4">
          {cart.map(item => (
            <div key={item.id} className="bg-gray-900 border border-gray-800 p-4 rounded-xl flex items-center justify-between">
              <div className="flex items-center space-x-4">
                <img src={item.image} alt={item.name} className="w-16 h-16 rounded-lg object-cover bg-gray-800" />
                <div>
                  <h3 className="font-semibold text-white">{item.name}</h3>
                  <p className="text-sm text-gray-400">₹{item.price}</p>
                </div>
              </div>

              <div className="flex items-center space-x-6">
                <div className="flex items-center bg-gray-800 rounded-lg p-1">
                  <button onClick={() => updateQty(item.id, -1)} className="p-1 hover:bg-gray-700 rounded text-gray-400 hover:text-white">
                    <Minus className="w-4 h-4" />
                  </button>
                  <span className="w-8 text-center text-sm font-medium">{item.quantity}</span>
                  <button onClick={() => updateQty(item.id, 1)} className="p-1 hover:bg-gray-700 rounded text-gray-400 hover:text-white">
                    <Plus className="w-4 h-4" />
                  </button>
                </div>
                <button onClick={() => remove(item.id)} className="text-gray-500 hover:text-red-500 transition-colors">
                  <Trash2 className="w-5 h-5" />
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Checkout Sidebar */}
      <div className="lg:col-span-1">
        <div className="bg-gray-900 border border-gray-800 rounded-2xl p-6 sticky top-24">
          <h2 className="text-xl font-bold text-white mb-6">Checkout</h2>

          <div className="mb-8">
            <h3 className="text-sm font-medium text-gray-400 mb-3 flex items-center">
              <Clock className="w-4 h-4 mr-2" /> Select Pickup Time
            </h3>
            <div className="grid grid-cols-2 gap-2">
              {slots.filter(s => s.available).slice(0, 6).map(slot => (
                <button
                  key={slot.id}
                  onClick={() => setSelectedSlot(slot.id)}
                  disabled={!slot.available}
                  className={`p-2 rounded-lg text-xs font-medium border transition-all ${
                    selectedSlot === slot.id 
                      ? 'bg-orange-500/20 border-orange-500 text-orange-500' 
                      : 'bg-gray-800 border-gray-700 text-gray-300 hover:border-gray-500'
                  }`}
                >
                  {slot.time}
                </button>
              ))}
            </div>
          </div>

          <div className="border-t border-gray-800 pt-4 mb-6">
            <div className="flex justify-between text-gray-400 mb-2">
              <span>Subtotal</span>
              <span>₹{total}</span>
            </div>
            <div className="flex justify-between text-gray-400 mb-2">
              <span>Tax (5%)</span>
              <span>₹{Math.round(total * 0.05)}</span>
            </div>
            <div className="flex justify-between text-xl font-bold text-white mt-4">
              <span>Total</span>
              <span>₹{Math.round(total * 1.05)}</span>
            </div>
          </div>

          {error && (
            <div className="mb-4 p-3 bg-red-900/30 border border-red-900/50 text-red-200 text-sm rounded-lg">
              {error}
            </div>
          )}

          <button
            onClick={handlePayment}
            disabled={paying}
            className="w-full bg-green-600 hover:bg-green-500 text-white py-3 rounded-xl font-semibold shadow-lg shadow-green-900/20 flex items-center justify-center transition-all disabled:opacity-50"
          >
            {paying ? (
              <span className="flex items-center">
                <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin mr-2"></span>
                Processing...
              </span>
            ) : (
              <span className="flex items-center">
                Pay Securely <ChevronRight className="w-4 h-4 ml-1" />
              </span>
            )}
          </button>

          <p className="text-center text-xs text-gray-500 mt-4">
            Simulated Payment via Razorpay. Secure Mock.
          </p>
        </div>
      </div>
    </div>
  );
};

export default CartPage;

import React, { useEffect, useState } from 'react';
import { db } from '../../services/mockDatabase';
import { Order, OrderStatus } from '../../types';
import { CheckCircle, Clock, Package, Loader2 } from 'lucide-react';

const OrdersPage: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>([]);

  const fetchOrders = () => {
    const user = db.getCurrentUser();
    if (user) {
      setOrders(db.getOrdersForUser(user.id));
    }
  };

  useEffect(() => {
    fetchOrders();
    // Subscribe to DB changes for real-time updates
    const handleDbChange = () => fetchOrders();
    db.addEventListener('change', handleDbChange);
    return () => db.removeEventListener('change', handleDbChange);
  }, []);

  const getStatusColor = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.CONFIRMED: return 'text-blue-400 bg-blue-400/10 border-blue-400/20';
      case OrderStatus.PREPARING: return 'text-orange-400 bg-orange-400/10 border-orange-400/20';
      case OrderStatus.READY: return 'text-green-400 bg-green-400/10 border-green-400/20';
      case OrderStatus.COMPLETED: return 'text-gray-400 bg-gray-400/10 border-gray-400/20';
    }
  };

  const getStatusIcon = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.CONFIRMED: return <CheckCircle className="w-4 h-4 mr-1.5" />;
      case OrderStatus.PREPARING: return <Loader2 className="w-4 h-4 mr-1.5 animate-spin" />;
      case OrderStatus.READY: return <Package className="w-4 h-4 mr-1.5" />;
      default: return <Clock className="w-4 h-4 mr-1.5" />;
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      <h1 className="text-2xl font-bold text-white mb-8">My Orders</h1>

      {orders.length === 0 && (
        <div className="text-center py-12 bg-gray-900 rounded-2xl border border-gray-800">
          <p className="text-gray-400">No past orders found.</p>
        </div>
      )}

      {orders.map(order => (
        <div key={order.id} className="bg-gray-900 border border-gray-800 rounded-2xl overflow-hidden shadow-lg">
          <div className="p-6 border-b border-gray-800 flex flex-col sm:flex-row justify-between sm:items-center gap-4">
            <div>
              <p className="text-sm text-gray-400 mb-1">Order #{order.id}</p>
              <div className="flex items-center text-sm font-medium text-white">
                <Clock className="w-4 h-4 mr-2 text-gray-500" />
                Pickup: {order.pickupTime}
              </div>
            </div>

            <div className={`px-4 py-2 rounded-full border flex items-center text-sm font-medium ${getStatusColor(order.status)}`}>
              {getStatusIcon(order.status)}
              {order.status}
            </div>
          </div>

          <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-8">
            <div className="md:col-span-2 space-y-3">
              <h3 className="text-sm font-medium text-gray-400 uppercase tracking-wide">Items</h3>
              <ul className="space-y-3">
                {order.items.map((item, idx) => (
                  <li key={idx} className="flex justify-between items-center text-sm">
                    <span className="text-gray-200">
                      <span className="font-bold text-orange-500">{item.quantity}x</span> {item.name}
                    </span>
                    <span className="text-gray-400">₹{item.price * item.quantity}</span>
                  </li>
                ))}
              </ul>
              <div className="pt-4 border-t border-gray-800 flex justify-between font-bold text-white">
                <span>Total Paid</span>
                <span>₹{Math.round(order.totalAmount * 1.05)}</span>
              </div>
            </div>

            <div className="flex flex-col items-center justify-center p-4 bg-white rounded-xl">
               {/* Use a simple QR code API for visual simulation */}
               <img 
                src={`https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${order.id}`}
                alt="Order QR Code"
                className="w-32 h-32"
               />
               <p className="mt-2 text-xs text-gray-900 font-medium text-center">Scan at counter</p>
            </div>
          </div>

          {order.status === OrderStatus.READY && (
             <div className="bg-green-500/10 p-3 text-center text-green-400 text-sm font-medium border-t border-green-500/20">
               Your order is ready! Please show the QR code at the counter.
             </div>
          )}
        </div>
      ))}
    </div>
  );
};

