import React, { useEffect, useState } from 'react';
import { db } from '../../services/mockDatabase';
import { Order, OrderStatus } from '../../types';
import { CheckCircle, Clock, Package, Loader2, Hourglass, Utensils } from 'lucide-react';

const OrdersPage: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [now, setNow] = useState(Date.now());

  const fetchOrders = () => {
    const user = db.getCurrentUser();
    if (user) {
      setOrders(db.getOrdersForUser(user.id));
    }
  };

  useEffect(() => {
    fetchOrders();
    const handleDbChange = () => fetchOrders();
    db.addEventListener('change', handleDbChange);

    const timerInterval = setInterval(() => {
        setNow(Date.now());
    }, 1000);

    return () => {
        db.removeEventListener('change', handleDbChange);
        clearInterval(timerInterval);
    };
  }, []);

  const getStatusColor = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.CONFIRMED: return 'text-blue-600 bg-blue-50 border-blue-100';
      case OrderStatus.PREPARING: return 'text-orange-600 bg-orange-50 border-orange-100';
      case OrderStatus.READY: return 'text-green-600 bg-green-50 border-green-100';
      case OrderStatus.COMPLETED: return 'text-slate-500 bg-slate-50 border-slate-200';
    }
  };

  const getStatusIcon = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.CONFIRMED: return <CheckCircle className="w-4 h-4 mr-1.5" />;
      case OrderStatus.PREPARING: return <Utensils className="w-4 h-4 mr-1.5 animate-pulse" />;
      case OrderStatus.READY: return <Package className="w-4 h-4 mr-1.5" />;
      default: return <Clock className="w-4 h-4 mr-1.5" />;
    }
  };

  const calculateProgress = (order: Order) => {
      if (order.status === OrderStatus.READY || order.status === OrderStatus.COMPLETED) return 100;
      if (!order.targetTime) return 0;

      const totalDuration = order.targetTime - order.createdAt;
      const elapsed = now - order.createdAt;
      const percent = Math.min(100, Math.max(0, (elapsed / totalDuration) * 100));
      return percent;
  };

  const formatTimeRemaining = (order: Order) => {
      if (order.status === OrderStatus.READY || order.status === OrderStatus.COMPLETED) return "00:00";
      const remainingMs = Math.max(0, order.targetTime - now);
      const minutes = Math.floor(remainingMs / 60000);
      const seconds = Math.floor((remainingMs % 60000) / 1000);
      return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
  };

  return (
    <div className="max-w-3xl mx-auto space-y-6">
      <h1 className="text-2xl font-bold text-slate-800 mb-8">My Orders</h1>

      {orders.length === 0 && (
        <div className="text-center py-16 bg-white rounded-3xl border border-dashed border-slate-200">
          <p className="text-slate-400 font-medium">No past orders found.</p>
        </div>
      )}

      {orders.map(order => {
        const isActive = order.status === OrderStatus.CONFIRMED || order.status === OrderStatus.PREPARING;
        const progress = calculateProgress(order);

        return (
            <div key={order.id} className="bg-white border border-slate-100 rounded-3xl overflow-hidden shadow-xl shadow-slate-200/50 hover:shadow-2xl transition-shadow duration-300">
            <div className="p-6 border-b border-slate-50 flex flex-col sm:flex-row justify-between sm:items-center gap-4 bg-slate-50/50">
                <div>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-wide mb-1">Order #{order.id}</p>
                <div className="flex items-center text-sm font-bold text-slate-700">
                    <Clock className="w-4 h-4 mr-2 text-slate-400" />
                    Pickup at {order.pickupTime}
                </div>
                </div>

                <div className={`px-4 py-2 rounded-full border flex items-center text-sm font-bold ${getStatusColor(order.status)}`}>
                {getStatusIcon(order.status)}
                {order.status}
                </div>
            </div>

            {/* Live Progress Bar */}
            {isActive && (
                <div className="bg-white px-6 py-6 border-b border-slate-50">
                    <div className="flex justify-between items-end mb-3">
                        <span className="text-xs font-bold text-orange-500 uppercase tracking-wider flex items-center">
                            <Hourglass className="w-3 h-3 mr-1 animate-spin-slow" /> Estimated Time
                        </span>
                        <span className="text-2xl font-bold text-slate-800 font-mono tracking-tight">{formatTimeRemaining(order)}</span>
                    </div>
                    <div className="h-3 w-full bg-slate-100 rounded-full overflow-hidden shadow-inner">
                        <div 
                            className="h-full bg-gradient-to-r from-orange-400 to-pink-500 rounded-full transition-all duration-1000 ease-linear shadow-lg shadow-orange-500/30"
                            style={{ width: `${progress}%` }}
                        />
                    </div>
                    <p className="text-xs text-slate-400 mt-3 text-center font-medium">
                       {progress < 20 ? 'Order sent to kitchen...' : progress < 80 ? 'Chef is preparing your meal...' : 'Packing your delicious food...'}
                    </p>
                </div>
            )}

            <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-8">
                <div className="md:col-span-2 space-y-4">
                <ul className="space-y-4">
                    {order.items.map((item, idx) => (
                    <li key={idx} className="flex justify-between items-center">
                        <div className="flex items-center">
                           <span className="w-6 h-6 rounded bg-orange-100 text-orange-600 text-xs font-bold flex items-center justify-center mr-3">
                              {item.quantity}x
                           </span>
                           <span className="text-slate-700 font-medium">{item.name}</span>
                        </div>
                        <span className="text-slate-500 text-sm font-medium">₹{item.price * item.quantity}</span>
                    </li>
                    ))}
                </ul>
                <div className="pt-4 border-t border-slate-100 flex justify-between font-bold text-slate-800 text-lg">
                    <span>Total Paid</span>
                    <span>₹{Math.round(order.totalAmount * 1.05)}</span>
                </div>
                </div>

                <div className="flex flex-col items-center justify-center p-4 bg-slate-50 rounded-2xl border border-slate-100">
                <div className={`transition-all duration-500 ${order.status === OrderStatus.READY || order.status === OrderStatus.COMPLETED ? 'opacity-100 blur-0' : 'opacity-30 blur-sm'}`}>
                    <img 
                        src={`https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${order.id}`}
                        alt="Order QR Code"
                        className="w-28 h-28 mix-blend-multiply"
                    />
                </div>
                <p className="mt-3 text-[10px] text-slate-400 font-bold uppercase tracking-widest text-center">
                    {order.status === OrderStatus.READY || order.status === OrderStatus.COMPLETED 
                     ? 'Scan at counter' 
                     : 'Preparing QR...'
                    }
                </p>
                </div>
            </div>

            {order.status === OrderStatus.READY && (
                <div className="bg-green-500 text-white p-3 text-center text-sm font-bold animate-pulse">
                   Your order is ready! Pickup now!
                </div>
            )}
            </div>
        );
      })}
    </div>
  );
};

export default OrdersPage;

import React, { useState, useRef, useEffect } from 'react';
import { MessageCircle, X, Send, Bot, Sparkles } from 'lucide-react';
import { chatWithSupport } from '../services/geminiService';

interface Message {
  id: string;
  sender: 'user' | 'bot';
  text: string;
}

const Chatbot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', sender: 'bot', text: 'Hi! I can help with orders, pickup slots, or payment issues. How can I assist you today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg: Message = { id: Date.now().toString(), sender: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const botResponse = await chatWithSupport(input, []);

    setIsTyping(false);
    setMessages(prev => [...prev, { id: (Date.now() + 1).toString(), sender: 'bot', text: botResponse || "Sorry, I'm offline." }]);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[60] flex flex-col items-end">
      {isOpen && (
        <div className="mb-4 w-80 sm:w-96 h-[500px] bg-white border border-slate-200 rounded-3xl shadow-2xl flex flex-col overflow-hidden animate-in fade-in slide-in-from-bottom-10 duration-300">
          {/* Header */}
          <div className="p-4 bg-slate-900 flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <div className="bg-gradient-to-tr from-pink-500 to-orange-500 p-2 rounded-full shadow-lg">
                <Bot className="w-5 h-5 text-white" />
              </div>
              <div>
                <h3 className="text-white font-bold text-sm">Support AI</h3>
                <div className="flex items-center space-x-1">
                   <div className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse"></div>
                   <p className="text-slate-400 text-xs">Online</p>
                </div>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="text-slate-400 hover:text-white transition-colors bg-white/10 p-1.5 rounded-full">
              <X className="w-4 h-4" />
            </button>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-4 py-3 rounded-2xl text-sm leading-relaxed shadow-sm ${
                  msg.sender === 'user' 
                    ? 'bg-slate-900 text-white rounded-tr-sm' 
                    : 'bg-white text-slate-700 rounded-tl-sm border border-slate-200'
                }`}>
                  {msg.text}
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-white px-4 py-3 rounded-2xl rounded-tl-sm border border-slate-200 flex space-x-1 shadow-sm">
                  <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                  <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                  <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                </div>
              </div>
            )}
          </div>

          {/* Input */}
          <div className="p-3 bg-white border-t border-slate-100">
            <div className="flex items-center space-x-2 bg-slate-50 rounded-full px-4 py-2 border border-slate-200 focus-within:border-orange-300 focus-within:ring-2 focus-within:ring-orange-100 transition-all">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Ask anything..." 
                className="flex-1 bg-transparent border-none focus:ring-0 text-sm text-slate-800 placeholder-slate-400"
              />
              <button 
                onClick={handleSend}
                disabled={!input.trim()}
                className="text-orange-500 hover:text-orange-600 disabled:opacity-50 p-1.5 bg-white rounded-full shadow-sm hover:shadow-md transition-all"
              >
                <Send className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      )}

      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`p-4 rounded-full shadow-xl shadow-orange-500/20 transition-all duration-300 transform hover:scale-105 ${
          isOpen ? 'bg-slate-800 text-white rotate-90' : 'bg-gradient-to-r from-orange-500 to-pink-500 text-white'
        }`}
      >
        {isOpen ? <X className="w-6 h-6" /> : <MessageCircle className="w-6 h-6" />}
      </button>
    </div>
  );
};

export default Chatbot;

