interface AuthPageProps {
  onLogin: (user: User) => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ onLogin }) => {
  const [email, setEmail] = useState('customer@quickbite.com');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      await new Promise(resolve => setTimeout(resolve, 800));
      const user = await db.login(email);
      onLogin(user);
    } catch (err) {
      setError('Invalid credentials. Try customer@quickbite.com');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-[80vh] flex flex-col items-center justify-center p-4">
      <div className="w-full max-w-md bg-white p-10 rounded-3xl shadow-2xl shadow-pink-100 relative overflow-hidden border border-slate-100">

        <div className="relative z-10 text-center mb-10">
          <div className="mx-auto bg-gradient-to-tr from-pink-500 to-orange-500 w-20 h-20 rounded-full flex items-center justify-center mb-6 shadow-lg shadow-orange-500/20">
            <Heart className="w-10 h-10 text-white fill-current" />
          </div>
          <h1 className="text-3xl font-bold text-slate-900 mb-2 tracking-tight">Welcome Back</h1>
          <p className="text-slate-400">Sign in to Mood Bites</p>
        </div>

        <form onSubmit={handleLogin} className="space-y-6 relative z-10">
          <div>
            <label className="block text-xs font-bold text-slate-500 uppercase tracking-wide mb-2">Email Address</label>
            <input 
              type="email" 
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-4 text-slate-800 focus:ring-2 focus:ring-orange-200 focus:border-orange-400 outline-none transition-all font-medium"
              placeholder="name@example.com"
            />
          </div>

          {error && (
            <div className="p-4 bg-red-50 border border-red-100 text-red-500 text-sm rounded-xl font-medium">
              {error}
            </div>
          )}

          <button 
            type="submit" 
            disabled={loading}
            className="w-full bg-slate-900 hover:bg-black text-white font-bold py-4 px-6 rounded-xl transition-all transform hover:scale-[1.02] active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center shadow-lg shadow-slate-900/20"
          >
            {loading ? (
              <span className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
            ) : (
              <>
                Start Eating <ArrowRight className="ml-2 w-4 h-4" />
              </>
            )}
          </button>
        </form>

        <div className="mt-10 pt-8 border-t border-slate-100">
          <p className="text-[10px] text-center text-slate-400 uppercase font-bold tracking-widest mb-4">Quick Login</p>
          <div className="grid grid-cols-2 gap-3">
            <button 
              onClick={() => setEmail('customer@quickbite.com')}
              className="text-xs bg-slate-50 hover:bg-slate-100 text-slate-600 py-3 px-4 rounded-xl border border-slate-200 font-bold transition-colors"
            >
              Customer
            </button>
            <button 
              onClick={() => setEmail('admin@quickbite.com')}
              className="text-xs bg-slate-50 hover:bg-slate-100 text-slate-600 py-3 px-4 rounded-xl border border-slate-200 font-bold transition-colors"
            >
              Admin
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

