class MockDatabase extends EventTarget {
  private users: User[] = [];
  private menu: MenuItem[] = [];
  private orders: Order[] = [];
  private slots: PickupSlot[] = [];
  private currentUser: User | null = null;
  private simulationInterval: any;

  constructor() {
    super();
    this.loadData();
    this.startKitchenSimulation();
  }

  private loadData() {
    // Simulate persistent storage
    const storedMenu = localStorage.getItem('qb_menu');
    const storedUsers = localStorage.getItem('qb_users');
    const storedOrders = localStorage.getItem('qb_orders');

    this.menu = storedMenu ? JSON.parse(storedMenu) : INITIAL_MENU;
    this.users = storedUsers ? JSON.parse(storedUsers) : INITIAL_USERS;
    this.orders = storedOrders ? JSON.parse(storedOrders) : [];

    // Generate slots for the day
    this.generateSlots();
  }

  private saveData() {
    localStorage.setItem('qb_menu', JSON.stringify(this.menu));
    localStorage.setItem('qb_users', JSON.stringify(this.users));
    localStorage.setItem('qb_orders', JSON.stringify(this.orders));
    this.dispatchEvent(new Event('change'));
  }

  private generateSlots() {
    const slots: PickupSlot[] = [];
    let hour = 9; // 9 AM
    for (let i = 0; i < 10; i++) {
      const time = `${hour}:00 - ${hour}:30`;
      slots.push({
        id: `slot-${i}`,
        time,
        capacity: 5,
        booked: 0,
        available: true
      });
      hour++;
    }
    this.slots = slots;
  }

  private startKitchenSimulation() {
    // Check order status every second
    this.simulationInterval = setInterval(() => {
      const now = Date.now();
      let changed = false;

      this.orders.forEach(order => {
        // 1. Auto-transition from CONFIRMED to PREPARING after 10 seconds
        if (order.status === OrderStatus.CONFIRMED && now > order.createdAt + 10000) {
          order.status = OrderStatus.PREPARING;
          order.prepStartTime = now;
          // Assign random prep time between 8 and 15 minutes
          const prepMinutes = Math.floor(Math.random() * (15 - 8 + 1) + 8); 
          order.targetTime = now + (prepMinutes * 60 * 1000);
          changed = true;
        }

        // 2. Auto-transition from PREPARING to READY when timer hits 0
        if (order.status === OrderStatus.PREPARING && order.targetTime && now >= order.targetTime) {
          order.status = OrderStatus.READY;
          changed = true;
        }
      });

      if (changed) {
        this.saveData();
      }
    }, 1000);
  }

  // Auth Methods
  async login(email: string): Promise<User> {
    const user = this.users.find(u => u.email === email);
    if (!user) throw new Error('User not found');
    this.currentUser = user;
    localStorage.setItem('qb_current_user', JSON.stringify(user));
    return user;
  }

  logout() {
    this.currentUser = null;
    localStorage.removeItem('qb_current_user');
    window.location.reload();
  }

  getCurrentUser(): User | null {
    if (this.currentUser) return this.currentUser;
    const stored = localStorage.getItem('qb_current_user');
    if (stored) {
      this.currentUser = JSON.parse(stored);
      return this.currentUser;
    }
    return null;
  }

  // Menu Methods
  getMenu() {
    return [...this.menu];
  }

  addMenuItem(item: Omit<MenuItem, 'id'>) {
    const newItem = { ...item, id: Math.random().toString(36).substr(2, 9) };
    this.menu.push(newItem);
    this.saveData();
  }

  deleteMenuItem(id: string) {
    this.menu = this.menu.filter(item => item.id !== id);
    this.saveData();
  }

  // Order Methods
  getOrders() {
    return [...this.orders];
  }

  getOrdersForUser(userId: string) {
    return this.orders.filter(o => o.userId === userId).sort((a, b) => b.createdAt - a.createdAt);
  }

  createOrder(items: CartItem[], totalAmount: number, pickupSlotId: string): Order {
    if (!this.currentUser) throw new Error('Must be logged in');

    // Update slot capacity
    const slotIndex = this.slots.findIndex(s => s.id === pickupSlotId);
    if (slotIndex >= 0) {
        if (this.slots[slotIndex].booked >= this.slots[slotIndex].capacity) {
            throw new Error('Slot full');
        }
        this.slots[slotIndex].booked += 1;
        if (this.slots[slotIndex].booked >= this.slots[slotIndex].capacity) {
            this.slots[slotIndex].available = false;
        }
    }

    const newOrder: Order = {
      id: `ORD-${Math.floor(Math.random() * 10000)}`,
      userId: this.currentUser.id,
      items,
      totalAmount,
      status: OrderStatus.CONFIRMED,
      createdAt: Date.now(),
      // targetTime and prepStartTime undefined initially
      pickupTime: this.slots.find(s => s.id === pickupSlotId)?.time || 'Unknown',
      pickupSlotId
    };

    this.orders.unshift(newOrder); // Add to top
    this.saveData();
    return newOrder;
  }

  updateOrderStatus(orderId: string, status: OrderStatus) {
    const order = this.orders.find(o => o.id === orderId);
    if (order) {
      order.status = status;

      // If manually moving to PREPARING, ensure timer is set
      if (status === OrderStatus.PREPARING && !order.targetTime) {
          order.prepStartTime = Date.now();
          const prepMinutes = Math.floor(Math.random() * (15 - 8 + 1) + 8);
          order.targetTime = Date.now() + (prepMinutes * 60 * 1000);
      }

      this.saveData();
    }
  }

  // Slots
  getSlots() {
    return [...this.slots];
  }

  // Admin Stats
  getStats() {
    return {
      totalOrders: this.orders.length,
      totalRevenue: this.orders.reduce((acc, o) => acc + o.totalAmount, 0),
      totalUsers: this.users.length,
    };
  }
}

export const db = new MockDatabase();

import React, { useEffect, useState } from 'react';
import { db } from '../../services/mockDatabase';
import { Order, OrderStatus } from '../../types';
import { CheckCircle, Clock, Package, Loader2, Hourglass, Utensils, Flame } from 'lucide-react';

const OrdersPage: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [now, setNow] = useState(Date.now());

  const fetchOrders = () => {
    const user = db.getCurrentUser();
    if (user) {
      setOrders(db.getOrdersForUser(user.id));
    }
  };

  useEffect(() => {
    fetchOrders();
    const handleDbChange = () => fetchOrders();
    db.addEventListener('change', handleDbChange);

    const timerInterval = setInterval(() => {
        setNow(Date.now());
    }, 1000);

    return () => {
        db.removeEventListener('change', handleDbChange);
        clearInterval(timerInterval);
    };
  }, []);

  const getStatusColor = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.CONFIRMED: return 'text-blue-600 bg-blue-50 border-blue-100';
      case OrderStatus.PREPARING: return 'text-orange-600 bg-orange-50 border-orange-100';
      case OrderStatus.READY: return 'text-green-600 bg-green-50 border-green-100';
      case OrderStatus.COMPLETED: return 'text-slate-500 bg-slate-50 border-slate-200';
    }
  };

  const getStatusIcon = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.CONFIRMED: return <CheckCircle className="w-4 h-4 mr-1.5" />;
      case OrderStatus.PREPARING: return <Utensils className="w-4 h-4 mr-1.5 animate-pulse" />;
      case OrderStatus.READY: return <Package className="w-4 h-4 mr-1.5" />;
      default: return <Clock className="w-4 h-4 mr-1.5" />;
    }
  };

  const calculateProgress = (order: Order) => {
      if (order.status === OrderStatus.READY || order.status === OrderStatus.COMPLETED) return 100;
      if (order.status === OrderStatus.CONFIRMED) return 5; // Initial small progress
      if (!order.targetTime || !order.prepStartTime) return 0;

      const totalDuration = order.targetTime - order.prepStartTime;
      const elapsed = now - order.prepStartTime;
      const percent = Math.min(100, Math.max(0, (elapsed / totalDuration) * 100));
      return percent;
  };

  const getCountdown = (order: Order) => {
      if (order.status === OrderStatus.READY || order.status === OrderStatus.COMPLETED) return "00:00";
      if (!order.targetTime) return "--:--";

      const remainingMs = Math.max(0, order.targetTime - now);
      const minutes = Math.floor(remainingMs / 60000);
      const seconds = Math.floor((remainingMs % 60000) / 1000);
      return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
  };

  const isAlmostReady = (order: Order) => {
    if (!order.targetTime || order.status !== OrderStatus.PREPARING) return false;
    const remainingMs = order.targetTime - now;
    return remainingMs > 0 && remainingMs < 2 * 60 * 1000; // Less than 2 minutes
  };

  return (
    <div className="max-w-3xl mx-auto space-y-6">
      <h1 className="text-2xl font-bold text-slate-800 mb-8">My Orders</h1>

      {orders.length === 0 && (
        <div className="text-center py-16 bg-white rounded-3xl border border-dashed border-slate-200">
          <p className="text-slate-400 font-medium">No past orders found.</p>
        </div>
      )}

      {orders.map(order => {
        const isActive = order.status === OrderStatus.CONFIRMED || order.status === OrderStatus.PREPARING;
        const progress = calculateProgress(order);

        return (
            <div key={order.id} className="bg-white border border-slate-100 rounded-3xl overflow-hidden shadow-xl shadow-slate-200/50 hover:shadow-2xl transition-shadow duration-300">
            <div className="p-6 border-b border-slate-50 flex flex-col sm:flex-row justify-between sm:items-center gap-4 bg-slate-50/50">
                <div>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-wide mb-1">Order #{order.id}</p>
                <div className="flex items-center text-sm font-bold text-slate-700">
                    <Clock className="w-4 h-4 mr-2 text-slate-400" />
                    Pickup at {order.pickupTime}
                </div>
                </div>

                <div className={`px-4 py-2 rounded-full border flex items-center text-sm font-bold ${getStatusColor(order.status)}`}>
                {getStatusIcon(order.status)}
                {order.status}
                </div>
            </div>

            {/* Live Progress Bar Section */}
            {isActive && (
                <div className="bg-white px-6 py-6 border-b border-slate-50 relative overflow-hidden">
                    {/* Background pulsing effect for "Almost Ready" */}
                    {isAlmostReady(order) && (
                         <div className="absolute inset-0 bg-orange-50 animate-pulse pointer-events-none"></div>
                    )}

                    <div className="relative z-10">
                        <div className="flex justify-between items-end mb-3">
                            <span className="text-xs font-bold text-orange-500 uppercase tracking-wider flex items-center">
                                {order.status === OrderStatus.CONFIRMED ? (
                                    <>Order Confirmed</>
                                ) : (
                                    <>
                                        <Hourglass className="w-3 h-3 mr-1 animate-spin-slow" /> 
                                        {isAlmostReady(order) ? 'Almost Ready!' : 'Estimated Time'}
                                    </>
                                )}
                            </span>
                            <span className="text-2xl font-bold text-slate-800 font-mono tracking-tight">
                                {order.status === OrderStatus.CONFIRMED ? 'Waiting...' : getCountdown(order)}
                            </span>
                        </div>

                        <div className="h-4 w-full bg-slate-100 rounded-full overflow-hidden shadow-inner relative">
                            <div 
                                className={`h-full rounded-full transition-all duration-1000 ease-linear shadow-lg ${
                                    isAlmostReady(order) 
                                    ? 'bg-gradient-to-r from-red-500 to-orange-500 animate-pulse' 
                                    : 'bg-gradient-to-r from-orange-400 to-pink-500'
                                }`}
                                style={{ width: `${progress}%` }}
                            />
                            {/* Animated sheen effect */}
                            <div className="absolute top-0 left-0 bottom-0 right-0 bg-gradient-to-r from-transparent via-white/30 to-transparent -translate-x-full animate-[shimmer_2s_infinite]"></div>
                        </div>

                        <div className="flex justify-between items-center mt-3">
                             <p className="text-xs text-slate-400 font-medium">
                                {order.status === OrderStatus.CONFIRMED 
                                 ? 'Kitchen is reviewing your order...' 
                                 : isAlmostReady(order) 
                                   ? 'Putting final touches...' 
                                   : 'Chef is preparing your meal...'}
                             </p>
                             {isAlmostReady(order) && (
                                 <span className="flex items-center text-xs font-bold text-red-500 animate-bounce">
                                     <Flame className="w-3 h-3 mr-1" /> Hot & Fresh
                                 </span>
                             )}
                        </div>
                    </div>
                </div>
            )}

            <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-8">
                <div className="md:col-span-2 space-y-4">
                <ul className="space-y-4">
                    {order.items.map((item, idx) => (
                    <li key={idx} className="flex justify-between items-center">
                        <div className="flex items-center">
                           <span className="w-6 h-6 rounded bg-orange-100 text-orange-600 text-xs font-bold flex items-center justify-center mr-3">
                              {item.quantity}x
                           </span>
                           <span className="text-slate-700 font-medium">{item.name}</span>
                        </div>
                        <span className="text-slate-500 text-sm font-medium">₹{item.price * item.quantity}</span>
                    </li>
                    ))}
                </ul>
                <div className="pt-4 border-t border-slate-100 flex justify-between font-bold text-slate-800 text-lg">
                    <span>Total Paid</span>
                    <span>₹{Math.round(order.totalAmount * 1.05)}</span>
                </div>
                </div>

                <div className="flex flex-col items-center justify-center p-4 bg-slate-50 rounded-2xl border border-slate-100">
                <div className={`transition-all duration-500 ${order.status === OrderStatus.READY || order.status === OrderStatus.COMPLETED ? 'opacity-100 blur-0' : 'opacity-30 blur-sm'}`}>
                    <img 
                        src={`https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${order.id}`}
                        alt="Order QR Code"
                        className="w-28 h-28 mix-blend-multiply"
                    />
                </div>
                <p className="mt-3 text-[10px] text-slate-400 font-bold uppercase tracking-widest text-center">
                    {order.status === OrderStatus.READY || order.status === OrderStatus.COMPLETED 
                     ? 'Scan at counter' 
                     : 'Preparing QR...'
                    }
                </p>
                </div>
            </div>

            {order.status === OrderStatus.READY && (
                <div className="bg-green-500 text-white p-3 text-center text-sm font-bold animate-pulse">
                   Your order is ready! Pickup now!
                </div>
            )}
            </div>
        );
      })}
    </div>
  );
};

export default OrdersPage;

import React, { useEffect, useState } from 'react';
import { db } from '../../services/mockDatabase';
import { MenuItem, Order, OrderStatus, User, UserRole, FoodCategory } from '../../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid } from 'recharts';
import { Users, DollarSign, ShoppingBag, Edit, Trash, Plus, Search, Utensils, Clock, AlertCircle } from 'lucide-react';

interface AdminDashboardProps {
  user: User;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'orders' | 'menu' | 'users'>('dashboard');
  const [stats, setStats] = useState(db.getStats());
  const [orders, setOrders] = useState<Order[]>([]);
  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [users, setUsers] = useState<User[]>([]); 
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    const updateData = () => {
      setStats(db.getStats());
      setMenu(db.getMenu());

      let allOrders = db.getOrders();
      if (user.role === UserRole.SPECIALIZED_ADMIN && user.specialty) {
        allOrders = allOrders.filter(o => o.items.some(i => i.category === user.specialty));
      }
      setOrders(allOrders);
    };

    updateData();
    db.addEventListener('change', updateData);

    // Timer for live updates
    const interval = setInterval(() => setNow(Date.now()), 1000);

    return () => {
      db.removeEventListener('change', updateData);
      clearInterval(interval);
    };
  }, [user]);

  const updateStatus = (id: string, status: OrderStatus) => {
    db.updateOrderStatus(id, status);
  };

  const deleteMenuItem = (id: string) => {
    if (confirm('Delete this item?')) {
        db.deleteMenuItem(id);
    }
  };

  const handleAddMenu = () => {
      const name = prompt("Item Name:");
      if(!name) return;
      const price = Number(prompt("Price:"));
      db.addMenuItem({
          name,
          description: 'New yummy item',
          price: price || 100,
          category: FoodCategory.SNACKS,
          image: 'https://picsum.photos/400/300',
          isVeg: true
      });
