  const [discount, setDiscount] = useState(0);
  const [couponMsg, setCouponMsg] = useState({ text: '', isError: false });
  const [appliedCode, setAppliedCode] = useState<string | null>(null);

  const navigate = useNavigate();

  useEffect(() => {
    const load = () => {
      const stored = localStorage.getItem('qb_cart');
      if (stored) setCart(JSON.parse(stored));
      setSlots(db.getSlots());
    };
    load();
    window.addEventListener('storage', load);
    return () => window.removeEventListener('storage', load);
  }, []);

  const updateQty = (id: string, delta: number) => {
    const newCart = cart.map(item => {
      if (item.id === id) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    });
    setCart(newCart);
    localStorage.setItem('qb_cart', JSON.stringify(newCart));
    window.dispatchEvent(new Event('cart-updated'));

    // Reset coupon if cart changes (simple safeguard)
    if (appliedCode) {
      setAppliedCode(null);
      setDiscount(0);
      setCouponMsg({ text: 'Cart updated, please re-apply coupon.', isError: true });
    }
  };

  const remove = (id: string) => {
    const newCart = cart.filter(item => item.id !== id);
    setCart(newCart);
    localStorage.setItem('qb_cart', JSON.stringify(newCart));
    window.dispatchEvent(new Event('cart-updated'));

    // Reset coupon if cart changes
    if (appliedCode) {
      setAppliedCode(null);
      setDiscount(0);
      setCouponMsg({ text: '', isError: false });
    }
  };

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const tax = Math.round(subtotal * 0.05);
  const finalTotal = Math.max(0, subtotal + tax - discount);

  const applyCoupon = () => {
    if (!couponCode.trim()) return;

    const result = db.validateCoupon(couponCode, cart);

    if (result.valid) {
      setDiscount(result.discount);
      setAppliedCode(couponCode);
      setCouponMsg({ text: result.message, isError: false });
    } else {
      setDiscount(0);
      setAppliedCode(null);
      setCouponMsg({ text: result.message, isError: true });
    }
  };

  const removeCoupon = () => {
    setCouponCode('');
    setDiscount(0);
    setAppliedCode(null);
    setCouponMsg({ text: '', isError: false });
  };

  const handlePayment = async () => {
    if (!selectedSlot) return setError('Please select a pickup time.');
    setPaying(true);
    setError('');

    try {
      await new Promise(resolve => setTimeout(resolve, 2000));
      if (Math.random() > 0.95) throw new Error('Payment Failed: Bank declined transaction.');

      // Create order with discount
      db.createOrder(cart, finalTotal, selectedSlot, discount, appliedCode || undefined);

      localStorage.removeItem('qb_cart');
      setCart([]);
      window.dispatchEvent(new Event('cart-updated'));
      navigate('/orders');
    } catch (err: any) {
      setError(err.message || 'Payment failed');
    } finally {
      setPaying(false);
    }
  };

  if (cart.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] text-center">
        <div className="bg-white p-8 rounded-full shadow-lg mb-6">
          <ShoppingBag className="w-12 h-12 text-orange-200" />
        </div>
        <h2 className="text-2xl font-bold text-slate-800 mb-2">Your cart is empty</h2>
        <p className="text-slate-400 mb-8">Good food is waiting for you!</p>
        <button onClick={() => navigate('/menu')} className="bg-orange-500 text-white px-8 py-3 rounded-full font-bold shadow-lg shadow-orange-500/30 hover:bg-orange-600 transition-all">
          Explore Menu
        </button>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      <div className="lg:col-span-2 space-y-6">
        <h1 className="text-2xl font-bold text-slate-800 mb-6 flex items-center">
            Cart 
            <span className="ml-3 bg-orange-100 text-orange-600 text-sm px-3 py-1 rounded-full">{cart.length} items</span>
        </h1>

        <div className="space-y-4">
          {cart.map(item => (
            <div key={item.id} className="bg-white border border-slate-100 p-4 rounded-2xl flex items-center justify-between shadow-sm hover:shadow-md transition-shadow">
              <div className="flex items-center space-x-4">
                <img src={item.image} alt={item.name} className="w-20 h-20 rounded-xl object-cover" />
                <div>
                  <h3 className="font-bold text-slate-800">{item.name}</h3>
                  <p className="text-sm text-slate-500">₹{item.price}</p>
                </div>
              </div>

              <div className="flex items-center space-x-6">
                <div className="flex items-center bg-slate-50 rounded-xl p-1 border border-slate-100">
                  <button onClick={() => updateQty(item.id, -1)} className="p-2 hover:bg-white hover:shadow-sm rounded-lg text-slate-400 hover:text-slate-900 transition-all">
                    <Minus className="w-4 h-4" />
                  </button>
                  <span className="w-8 text-center text-sm font-bold text-slate-800">{item.quantity}</span>
                  <button onClick={() => updateQty(item.id, 1)} className="p-2 hover:bg-white hover:shadow-sm rounded-lg text-slate-400 hover:text-slate-900 transition-all">
                    <Plus className="w-4 h-4" />
                  </button>
                </div>
                <button onClick={() => remove(item.id)} className="text-slate-300 hover:text-red-500 transition-colors p-2">
                  <Trash2 className="w-5 h-5" />
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="lg:col-span-1">
        <div className="bg-white border border-slate-100 rounded-3xl p-6 sticky top-24 shadow-xl shadow-slate-200/50">
          <h2 className="text-xl font-bold text-slate-800 mb-6">Checkout</h2>

          <div className="mb-6">
            <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wide mb-3 flex items-center">
              <Clock className="w-4 h-4 mr-2" /> Select Pickup Time
            </h3>
            <div className="grid grid-cols-2 gap-2">
              {slots.filter(s => s.available).slice(0, 6).map(slot => (
                <button
                  key={slot.id}
                  onClick={() => setSelectedSlot(slot.id)}
                  disabled={!slot.available}
                  className={`p-3 rounded-xl text-xs font-bold border transition-all ${
                    selectedSlot === slot.id 
                      ? 'bg-orange-500 text-white border-orange-500 shadow-md shadow-orange-500/20' 
                      : 'bg-slate-50 border-transparent text-slate-600 hover:bg-slate-100'
                  }`}
                >
                  {slot.time}
                </button>
              ))}
            </div>
          </div>

          {/* Coupon Section */}
          <div className="mb-6">
             <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wide mb-3 flex items-center">
               <Tag className="w-4 h-4 mr-2" /> Offers & Coupons
             </h3>

             {!appliedCode ? (
               <div className="flex gap-2">
                  <input 
                    type="text" 
                    value={couponCode}
                    onChange={(e) => setCouponCode(e.target.value.toUpperCase())}
                    placeholder="Enter Coupon Code"
                    className="flex-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm font-bold text-slate-700 focus:outline-none focus:border-orange-300 uppercase"
                  />
                  <button 
                    onClick={applyCoupon}
                    className="bg-slate-800 text-white text-xs font-bold px-4 rounded-lg hover:bg-black transition-colors"
                  >
                    Apply
                  </button>
               </div>
             ) : (
                <div className="bg-green-50 border border-green-100 rounded-lg p-3 flex justify-between items-center">
                   <div>
                      <span className="block text-xs font-bold text-green-700">'{appliedCode}' Applied</span>
                      <span className="text-[10px] text-green-600">You saved ₹{discount}</span>
                   </div>
                   <button onClick={removeCoupon} className="text-slate-400 hover:text-red-500">
                      <X className="w-4 h-4" />
                   </button>
                </div>
             )}

             {couponMsg.text && !appliedCode && (
               <p className={`text-xs mt-2 font-medium ${couponMsg.isError ? 'text-red-500' : 'text-green-500'}`}>
                 {couponMsg.text}
               </p>
             )}
          </div>

          <div className="border-t border-slate-100 pt-6 mb-6 space-y-2">
            <div className="flex justify-between text-slate-500 text-sm">
              <span>Subtotal</span>
              <span>₹{subtotal}</span>
            </div>
            <div className="flex justify-between text-slate-500 text-sm">
              <span>Tax (5%)</span>
              <span>₹{tax}</span>
            </div>
            {discount > 0 && (
              <div className="flex justify-between text-green-600 text-sm font-bold">
                <span>Discount</span>
                <span>- ₹{discount}</span>
              </div>
            )}
            <div className="flex justify-between text-xl font-bold text-slate-900 mt-4 pt-4 border-t border-dashed border-slate-200">
              <span>Total</span>
              <span>₹{finalTotal}</span>
            </div>
          </div>

          {error && (
            <div className="mb-4 p-4 bg-red-50 border border-red-100 text-red-500 text-sm rounded-xl font-medium">
              {error}
            </div>
          )}

          <button
            onClick={handlePayment}
            disabled={paying}
            className="w-full bg-slate-900 hover:bg-black text-white py-4 rounded-xl font-bold shadow-lg flex items-center justify-center transition-all disabled:opacity-50"
          >
            {paying ? (
              <span className="flex items-center">
                <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin mr-2"></span>
                Processing...
              </span>
            ) : (
              <span className="flex items-center">
                Pay Securely <ChevronRight className="w-4 h-4 ml-1" />
              </span>
            )}
          </button>

          <div className="mt-4 flex items-center justify-center text-slate-400 text-xs bg-slate-50 py-2 rounded-lg">
             <CreditCard className="w-3 h-3 mr-2" />
             <span>Secure Simulated Payment</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CartPage;

import React, { useEffect, useState } from 'react';
import { db } from '../../services/mockDatabase';
import { MenuItem, Order, OrderStatus, User, UserRole, FoodCategory, Coupon, DiscountType } from '../../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid } from 'recharts';
import { Users, DollarSign, ShoppingBag, Edit, Trash, Plus, Search, Utensils, Clock, AlertCircle, Scan, CheckCircle, XCircle, Tag, Ticket } from 'lucide-react';

interface AdminDashboardProps {
  user: User;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'orders' | 'history' | 'menu' | 'users' | 'coupons'>('dashboard');
  const [stats, setStats] = useState(db.getStats());
  const [orders, setOrders] = useState<Order[]>([]);
  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [coupons, setCoupons] = useState<Coupon[]>([]);
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    const updateData = () => {
      setStats(db.getStats());
      setMenu(db.getMenu());
      setCoupons(db.getCoupons());

      let allOrders = db.getOrders();
      if (user.role === UserRole.SPECIALIZED_ADMIN && user.specialty) {
        allOrders = allOrders.filter(o => o.items.some(i => i.category === user.specialty));
      }
      setOrders(allOrders);
    };

    updateData();
    db.addEventListener('change', updateData);

    // Timer for live updates
    const interval = setInterval(() => setNow(Date.now()), 1000);

    return () => {
      db.removeEventListener('change', updateData);
      clearInterval(interval);
    };
  }, [user]);

  const updateStatus = (id: string, status: OrderStatus) => {
    db.updateOrderStatus(id, status);
  };

  const deleteMenuItem = (id: string) => {
    if (confirm('Delete this item?')) {
        db.deleteMenuItem(id);
    }
  };

  const deleteCoupon = (id: string) => {
    if (confirm('Delete this coupon?')) {
        db.deleteCoupon(id);
    }
  };

  const handleAddMenu = () => {
      const name = prompt("Item Name:");
      if(!name) return;
      const price = Number(prompt("Price:"));
      db.addMenuItem({
          name,
          description: 'New yummy item',
          price: price || 100,
          category: FoodCategory.SNACKS,
          image: 'https://picsum.photos/400/300',
          isVeg: true
      });
  };

  const handleAddCoupon = () => {
    const code = prompt("Enter Coupon Code (e.g. SAVE20):");
    if(!code) return;

    const typeStr = prompt("Discount Type (PERCENTAGE / FLAT):", "PERCENTAGE");
    const type = typeStr?.toUpperCase() === 'FLAT' ? DiscountType.FLAT : DiscountType.PERCENTAGE;

    const value = Number(prompt(type === DiscountType.PERCENTAGE ? "Enter Percentage (e.g. 20 for 20%):" : "Enter Flat Amount (e.g. 50 for ₹50 off):"));
    if(isNaN(value)) return;

    const categoryInput = prompt("Restrict to Category? (LUNCH, BREAKFAST, SNACKS, DRINKS) or leave empty for ALL:");
    const category = categoryInput ? (categoryInput.toUpperCase() as any) : 'ALL';

    const expiryDate = prompt("Expiry Date (YYYY-MM-DD):", "2025-12-31");
    if(!expiryDate) return;

    db.addCoupon({
      code: code.toUpperCase(),
      type,
      value,
      category,
      expiryDate
    });
  };

  const handleScanQR = () => {
      // Simulate scanning by asking for the Order ID
      const orderId = prompt("📷 SIMULATE QR SCANNER\n\nPoint camera at Customer's QR Code.\n(Or enter Order ID manually below):");

      if (!orderId) return;

      const order = orders.find(o => o.id === orderId.trim());

      if (!order) {
          alert("❌ INVALID QR CODE\n\nOrder not found in the system.");
          return;
      }

      if (order.status === OrderStatus.COMPLETED) {
          alert("⚠️ ALREADY USED\n\nThis order has already been picked up.");
          return;
      }

      if (order.status !== OrderStatus.READY) {
          alert(`⚠️ NOT READY\n\nThis order is currently '${order.status}'.\nIt must be 'Ready for Pickup' to complete.`);
          return;
      }

      // Valid case
      const confirmPickup = confirm(
          `✅ QR VERIFIED!\n\nOrder #${order.id}\nItems: ${order.items.length}\nTotal Paid: ₹${order.totalAmount}\n\nComplete pickup?`
      );

      if (confirmPickup) {
          updateStatus(order.id, OrderStatus.COMPLETED);
          alert("🎉 SUCCESS\n\nOrder marked as COMPLETED.");
      }
  };

  const getTimerDisplay = (order: Order) => {
    if (order.status !== OrderStatus.PREPARING || !order.targetTime) return null;
    const remainingMs = order.targetTime - now;
    if (remainingMs <= 0) return <span className="text-red-500 font-bold text-xs">Overdue</span>;

    const minutes = Math.floor(remainingMs / 60000);
    const seconds = Math.floor((remainingMs % 60000) / 1000);
    const isLate = remainingMs < 60000; // Less than 1 min

    return (
        <span className={`text-xs font-mono font-bold px-2 py-1 rounded ${isLate ? 'bg-red-100 text-red-600 animate-pulse' : 'bg-slate-100 text-slate-700'}`}>
            {minutes}:{seconds.toString().padStart(2, '0')}
        </span>
    );
  };

  return (
    <div className="space-y-8">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-slate-800">
            {user.role === UserRole.SPECIALIZED_ADMIN ? `${user.specialty} Kitchen` : 'Admin Dashboard'}
          </h1>
          <p className="text-slate-500">Overview of canteen operations.</p>
        </div>

        <div className="flex items-center gap-4">
            <button 
                onClick={handleScanQR}
                className="bg-slate-900 hover:bg-black text-white px-5 py-2.5 rounded-xl font-bold shadow-lg shadow-slate-900/20 flex items-center transition-all active:scale-95"
            >
                <Scan className="w-5 h-5 mr-2" />
                Scan QR Code
            </button>

            <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm overflow-x-auto">
            {[
                { id: 'dashboard', label: 'Overview' },
                { id: 'orders', label: 'Orders' },
                { id: 'history', label: 'History' },
                { id: 'menu', label: 'Menu' },
                { id: 'coupons', label: 'Coupons' },
                { id: 'users', label: 'Users' }
            ].map(tab => (
                <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all whitespace-nowrap ${
                    activeTab === tab.id ? 'bg-slate-900 text-white shadow-md' : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                }`}
                >
                {tab.label}
                </button>
            ))}
            </div>
        </div>
      </div>

      {activeTab === 'dashboard' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 animate-in fade-in slide-in-from-bottom-4">
          <div className="bg-white border border-slate-100 p-6 rounded-3xl shadow-sm">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-slate-400 text-xs font-bold uppercase tracking-wider">Total Revenue</h3>
              <div className="p-2 bg-green-50 rounded-full">
                <DollarSign className="text-green-600 w-5 h-5" />
              </div>
            </div>
            <p className="text-4xl font-bold text-slate-800">₹{stats.totalRevenue.toLocaleString()}</p>
          </div>
          <div className="bg-white border border-slate-100 p-6 rounded-3xl shadow-sm">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-slate-400 text-xs font-bold uppercase tracking-wider">Total Orders</h3>
              <div className="p-2 bg-blue-50 rounded-full">
                <ShoppingBag className="text-blue-600 w-5 h-5" />
              </div>
            </div>
            <p className="text-4xl font-bold text-slate-800">{stats.totalOrders}</p>
          </div>
          <div className="bg-white border border-slate-100 p-6 rounded-3xl shadow-sm">
             <h3 className="text-slate-400 text-xs font-bold uppercase tracking-wider mb-4">Activity</h3>
             <div className="h-24 w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={[
                        {name: '9am', val: 4}, {name: '10am', val: 7}, {name: '11am', val: 12}, 
                        {name: '12pm', val: 24}, {name: '1pm', val: 18}
                    ]}>
                        <Bar dataKey="val" fill="#fb923c" radius={[4, 4, 4, 4]} />
                    </BarChart>
                </ResponsiveContainer>
             </div>
          </div>
        </div>
      )}

      {activeTab === 'orders' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in">
          {['Confirmed', 'Preparing', 'Ready for Pickup'].map(status => (
            <div key={status} className="bg-slate-50 border border-slate-200 rounded-2xl p-4 flex flex-col h-full">
              <h3 className="font-bold text-slate-700 mb-4 pb-2 border-b border-slate-200 flex justify-between items-center">
                {status}
                <span className="bg-white text-slate-800 text-xs font-bold py-1 px-2.5 rounded-full border border-slate-200 shadow-sm">{orders.filter(o => o.status === status).length}</span>
              </h3>
              <div className="space-y-3 overflow-y-auto max-h-[600px] pr-2 custom-scrollbar">
                {orders.filter(o => o.status === status).map(order => (
                  <div key={order.id} className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow">
                    <div className="flex justify-between items-start mb-3">
                        <span className="text-xs font-bold text-slate-400">#{order.id}</span>
                        <div className="flex items-center space-x-2">
                             {order.status === OrderStatus.PREPARING && getTimerDisplay(order)}
                             <span className="text-xs font-bold text-slate-600 bg-slate-100 px-2 py-1 rounded">{order.pickupTime}</span>
                        </div>
                    </div>
                    <div className="space-y-2 mb-4">
                        {order.items.map((i, idx) => (
                            <div key={idx} className="text-sm text-slate-700 flex justify-between font-medium">
                                <span><span className="text-orange-500 mr-1">{i.quantity}x</span> {i.name}</span>
                            </div>
                        ))}
                    </div>
                    <div className="flex justify-between items-center mt-3 pt-3 border-t border-slate-50">
                        {status === 'Confirmed' && (
                            <button 
                                onClick={() => updateStatus(order.id, OrderStatus.PREPARING)}
                                className="w-full bg-blue-50 hover:bg-blue-100 text-blue-600 font-bold text-xs py-2.5 rounded-lg transition-colors border border-blue-100"
                            >
                                Start Cooking
                            </button>
                        )}
                        {status === 'Preparing' && (
                            <button 
                                onClick={() => updateStatus(order.id, OrderStatus.READY)}
                                className="w-full bg-orange-50 hover:bg-orange-100 text-orange-600 font-bold text-xs py-2.5 rounded-lg transition-colors border border-orange-100"
                            >
                                Mark Ready
                            </button>
                        )}
                        {status === 'Ready for Pickup' && (
                            <button 
                                onClick={() => updateStatus(order.id, OrderStatus.COMPLETED)}
                                className="w-full bg-green-50 hover:bg-green-100 text-green-600 font-bold text-xs py-2.5 rounded-lg transition-colors border border-green-100"
                            >
                                Complete Order
                            </button>
                        )}
                    </div>
                  </div>
                ))}
                {orders.filter(o => o.status === status).length === 0 && (
                    <div className="text-center text-slate-400 text-sm py-12 flex flex-col items-center">
                        <Utensils className="w-8 h-8 mb-2 opacity-20" />
                        No orders
                    </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {activeTab === 'history' && (
          <div className="bg-white border border-slate-200 rounded-3xl overflow-hidden shadow-sm animate-in fade-in">
             <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                <h3 className="font-bold text-slate-800 flex items-center">
                    <CheckCircle className="w-5 h-5 text-green-500 mr-2" />
                    Completed Orders
                </h3>
                <span className="bg-slate-200 text-slate-600 text-xs font-bold py-1 px-3 rounded-full">
                    {orders.filter(o => o.status === OrderStatus.COMPLETED).length} Total
                </span>
            </div>
            <table className="w-full text-left text-sm text-slate-600">
                <thead className="bg-slate-50 text-slate-400 uppercase text-xs font-bold tracking-wider">
                    <tr>
                        <th className="p-5">Order ID</th>
                        <th className="p-5">Items</th>
                        <th className="p-5">Total</th>
                        <th className="p-5">Status</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {orders.filter(o => o.status === OrderStatus.COMPLETED).map(order => (
                        <tr key={order.id} className="hover:bg-slate-50/80 transition-colors">
                            <td className="p-5 font-mono text-slate-500 font-bold">#{order.id}</td>
                            <td className="p-5">
                                <div className="space-y-1">
                                    {order.items.map((i, idx) => (
                                        <div key={idx} className="flex items-center text-xs">
                                            <span className="font-bold text-slate-700 mr-1">{i.quantity}x</span> {i.name}
                                        </div>
                                    ))}
