            </table>
          </div>
      )}

      {activeTab === 'menu' && (
        <div className="bg-white border border-slate-200 rounded-3xl overflow-hidden shadow-sm animate-in fade-in">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                <h3 className="font-bold text-slate-800">Menu Items</h3>
                <button onClick={handleAddMenu} className="bg-slate-900 hover:bg-black text-white text-sm font-bold px-4 py-2 rounded-lg flex items-center shadow-lg shadow-slate-900/10">
                    <Plus className="w-4 h-4 mr-2" /> Add Item
                </button>
            </div>
            <table className="w-full text-left text-sm text-slate-600">
                <thead className="bg-slate-50 text-slate-400 uppercase text-xs font-bold tracking-wider">
                    <tr>
                        <th className="p-5">Name</th>
                        <th className="p-5">Category</th>
                        <th className="p-5">Price</th>
                        <th className="p-5 text-right">Actions</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {menu.map(item => (
                        <tr key={item.id} className="hover:bg-slate-50/80 transition-colors">
                            <td className="p-5 font-bold text-slate-800 flex items-center">
                                <img src={item.image} className="w-10 h-10 rounded-lg object-cover mr-3 shadow-sm" alt="" />
                                {item.name}
                            </td>
                            <td className="p-5">
                                <span className="px-3 py-1 rounded-full bg-slate-100 border border-slate-200 text-xs font-bold text-slate-600">
                                    {item.category}
                                </span>
                            </td>
                            <td className="p-5 font-mono text-slate-700 font-bold">₹{item.price}</td>
                            <td className="p-5 text-right">
                                <button 
                                    onClick={() => deleteMenuItem(item.id)}
                                    className="text-red-400 hover:text-red-600 p-2 hover:bg-red-50 rounded-lg transition-colors"
                                >
                                    <Trash className="w-4 h-4" />
                                </button>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
      )}

      {activeTab === 'coupons' && (
         <div className="bg-white border border-slate-200 rounded-3xl overflow-hidden shadow-sm animate-in fade-in">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                <h3 className="font-bold text-slate-800 flex items-center">
                  <Ticket className="w-5 h-5 mr-2 text-orange-500" />
                  Active Coupons
                </h3>
                <button onClick={handleAddCoupon} className="bg-slate-900 hover:bg-black text-white text-sm font-bold px-4 py-2 rounded-lg flex items-center shadow-lg shadow-slate-900/10">
                    <Plus className="w-4 h-4 mr-2" /> Create Coupon
                </button>
            </div>
            <table className="w-full text-left text-sm text-slate-600">
                <thead className="bg-slate-50 text-slate-400 uppercase text-xs font-bold tracking-wider">
                    <tr>
                        <th className="p-5">Code</th>
                        <th className="p-5">Type</th>
                        <th className="p-5">Value</th>
                        <th className="p-5">Category</th>
                        <th className="p-5">Expires</th>
                        <th className="p-5 text-right">Actions</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {coupons.map(coupon => (
                        <tr key={coupon.id} className="hover:bg-slate-50/80 transition-colors">
                            <td className="p-5 font-bold text-slate-800">
                                <span className="bg-orange-100 text-orange-700 px-3 py-1 rounded-lg border border-orange-200 border-dashed tracking-wide font-mono">
                                  {coupon.code}
                                </span>
                            </td>
                            <td className="p-5">
                                <span className="text-xs font-bold text-slate-500">{coupon.type}</span>
                            </td>
                            <td className="p-5 font-bold text-slate-700">
                              {coupon.type === DiscountType.PERCENTAGE ? `${coupon.value}%` : `₹${coupon.value}`}
                            </td>
                            <td className="p-5">
                                <span className="px-2 py-1 rounded-md bg-slate-100 text-xs font-bold text-slate-600">
                                    {coupon.category}
                                </span>
                            </td>
                            <td className="p-5 text-slate-500 text-xs font-medium">{coupon.expiryDate}</td>
                            <td className="p-5 text-right">
                                <button 
                                    onClick={() => deleteCoupon(coupon.id)}
                                    className="text-red-400 hover:text-red-600 p-2 hover:bg-red-50 rounded-lg transition-colors"
                                >
                                    <Trash className="w-4 h-4" />
                                </button>
                            </td>
                        </tr>
                    ))}
                    {coupons.length === 0 && (
                        <tr>
                            <td colSpan={6} className="p-12 text-center text-slate-400">No active coupons.</td>
                        </tr>
                    )}
                </tbody>
            </table>
         </div>
      )}

      {activeTab === 'users' && (
          <div className="bg-white border border-slate-200 rounded-3xl p-12 text-center animate-in fade-in shadow-sm">
              <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4">
                 <Users className="w-8 h-8 text-slate-400" />
