      couponCode,
      status: OrderStatus.CONFIRMED,
      createdAt: Date.now(),
      pickupTime: '12:00 PM', // Hardcoded for simplified slot logic
      pickupSlotId
    };

    const { data, error } = await supabase.from('orders').insert([newOrder]).select().single();

    if (error) throw new Error('Failed to create order: ' + error.message);

    this.dispatchEvent(new Event('change'));
    return data as Order;
  }

  async updateOrderStatus(orderId: string, status: OrderStatus) {
    await supabase.from('orders').update({ status }).eq('id', orderId);
    // Realtime subscription will handle the UI update
  }

  // --- Slots & Coupons (Still Mocked for Simplicity) ---
  async getSlots(): Promise<PickupSlot[]> {
    // Return mock slots instantly
    const slots: PickupSlot[] = [];
    let hour = 9;
    for (let i = 0; i < 10; i++) {
      slots.push({ id: `slot-${i}`, time: `${hour}:00 - ${hour}:30`, capacity: 5, booked: 0, available: true });
      hour++;
    }
    return slots;
  }

  getCoupons(): Coupon[] { return INITIAL_COUPONS; }
  addCoupon(c: any) { /* No op */ }
  deleteCoupon(id: string) { /* No op */ }

  validateCoupon(code: string, cart: CartItem[]) {
      const coupon = INITIAL_COUPONS.find(c => c.code === code);
      if(!coupon) return { valid: false, discount: 0, message: 'Invalid' };
      // Simplified logic
