const supabase = createClient(SUPABASE_URL, SUPABASE_KEY);

// Mock data for things we haven't created tables for yet (Users, Coupons, Slots)
const INITIAL_USERS: User[] = [
  { id: 'u1', name: 'John Doe', email: 'customer@quickbite.com', role: UserRole.CUSTOMER },
  { id: 'u2', name: 'Admin User', email: 'admin@quickbite.com', role: UserRole.ADMIN },
];

const INITIAL_COUPONS: Coupon[] = [
  { id: 'c1', code: 'WELCOME50', type: DiscountType.FLAT, value: 50, category: 'ALL', expiryDate: '2025-12-31' },
];

class SupabaseService extends EventTarget {
  private currentUser: User | null = null;
  private realtimeSubscription: any = null;

  constructor() {
    super();
    // Restore session
    const stored = localStorage.getItem('qb_current_user');
    if (stored) this.currentUser = JSON.parse(stored);

    // Listen for realtime changes on orders
    this.setupRealtime();
  }

  setupRealtime() {
    this.realtimeSubscription = supabase
      .channel('public:orders')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
        // Dispatch event so UI updates automatically
        this.dispatchEvent(new Event('change'));
      })
      .subscribe();
  }

  // --- Auth (Simulated for simplicity, or use supabase.auth) ---
  async login(email: string): Promise<User> {
    const user = INITIAL_USERS.find(u => u.email === email);
    if (!user) throw new Error('User not found');

    this.currentUser = user;
    localStorage.setItem('qb_current_user', JSON.stringify(user));
    return user;
  }

  logout() {
    this.currentUser = null;
    localStorage.removeItem('qb_current_user');
    window.location.reload();
  }

  getCurrentUser(): User | null {
    return this.currentUser;
  }

  // --- Menu ---
  async getMenu(): Promise<MenuItem[]> {
    const { data, error } = await supabase.from('menu_items').select('*');
    if (error) {
      console.error('Error fetching menu:', error);
      return [];
    }
    return data as MenuItem[];
  }

  async addMenuItem(item: Omit<MenuItem, 'id'>) {
    const { error } = await supabase.from('menu_items').insert([item]);
    if (error) console.error(error);
    this.dispatchEvent(new Event('change'));
  }

  async deleteMenuItem(id: string) {
    await supabase.from('menu_items').delete().eq('id', id);
    this.dispatchEvent(new Event('change'));
  }

  // --- Orders ---
  async getOrders(): Promise<Order[]> {
    const { data, error } = await supabase.from('orders').select('*').order('createdAt', { ascending: false });
    if (error) return [];
    return data as Order[];
  }

  async getOrdersForUser(userId: string): Promise<Order[]> {
    const { data, error } = await supabase.from('orders').select('*').eq('userId', userId).order('createdAt', { ascending: false });
    if (error) return [];
    return data as Order[];
  }

  async createOrder(items: CartItem[], totalAmount: number, pickupSlotId: string, discountAmount: number = 0, couponCode?: string): Promise<Order> {
    if (!this.currentUser) throw new Error('Must be logged in');

    const newOrder = {
      id: `ORD-${Math.floor(Math.random() * 100000)}`,
      userId: this.currentUser.id,
      items: items, // Supabase handles JSONB automatically
      totalAmount,
      discountAmount,
      couponCode,
      status: OrderStatus.CONFIRMED,
      createdAt: Date.now(),
      pickupTime: '12:00 PM', // Hardcoded for simplified slot logic
      pickupSlotId,
      // Default nulls for optional fields if needed
    };

    const { data, error } = await supabase.from('orders').insert([newOrder]).select().single();

    if (error) throw new Error('Failed to create order: ' + error.message);

    this.dispatchEvent(new Event('change'));
    return data as Order;
  }

  async updateOrderStatus(orderId: string, status: OrderStatus) {
    await supabase.from('orders').update({ status }).eq('id', orderId);
    // Realtime subscription will handle the UI update
  }

  // --- Slots & Coupons (Still Mocked for Simplicity) ---
  async getSlots(): Promise<PickupSlot[]> {
    // Return mock slots instantly
    const slots: PickupSlot[] = [];
    let hour = 9;
    for (let i = 0; i < 10; i++) {
      slots.push({ id: `slot-${i}`, time: `${hour}:00 - ${hour}:30`, capacity: 5, booked: 0, available: true });
      hour++;
    }
    return slots;
  }

  getCoupons(): Coupon[] { return INITIAL_COUPONS; }
  addCoupon(c: any) { /* No op */ }
  deleteCoupon(id: string) { /* No op */ }

  validateCoupon(code: string, cart: CartItem[]) {
      const coupon = INITIAL_COUPONS.find(c => c.code === code);
      if(!coupon) return { valid: false, discount: 0, message: 'Invalid' };
      // Simplified logic
      return { valid: true, discount: coupon.value, message: 'Applied' };
  }

  // --- Analytics ---
  async getAnalytics() {
      const orders = await this.getOrders();

      const now = new Date();
      const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
      const startOfYesterday = startOfToday - 86400000;

      const todayOrders = orders.filter(o => o.createdAt >= startOfToday);
      const yesterdayOrders = orders.filter(o => o.createdAt >= startOfYesterday && o.createdAt < startOfToday);

      const todayRevenue = todayOrders.reduce((sum, o) => sum + Number(o.totalAmount), 0);
      const yesterdayRevenue = yesterdayOrders.reduce((sum, o) => sum + Number(o.totalAmount), 0);

      // Popular Item
      const itemCounts: Record<string, number> = {};
      orders.forEach(o => {
        o.items.forEach((i: any) => {
          itemCounts[i.name] = (itemCounts[i.name] || 0) + i.quantity;
        });
      });
      let popularItem = { name: 'None', count: 0 };
      Object.entries(itemCounts).forEach(([name, count]) => {
        if (count > popularItem.count) popularItem = { name, count };
      });

      // Simple category data
      const catCounts: Record<string, number> = {};
      orders.forEach(o => {
          o.items.forEach((i: any) => {
              if (i.category) catCounts[i.category] = (catCounts[i.category] || 0) + 1;
          });
      });
      const categoryData = Object.entries(catCounts).map(([name, value]) => ({ name, value }));

      // Simple revenue graph (last 7 days - placeholders for now, just current day populated)
      const revenueData = [
          { name: 'Mon', revenue: 0 }, { name: 'Tue', revenue: 0 }, { name: 'Wed', revenue: 0 },
          { name: 'Thu', revenue: 0 }, { name: 'Fri', revenue: 0 }, { name: 'Sat', revenue: 0 },
          { name: 'Sun', revenue: 0 }
      ];
      // A robust impl would map timestamps to days. For prototype, we leave this static or basic.

      return {
          todayRevenue,
          yesterdayRevenue,
          todayOrders: todayOrders.length,
          yesterdayOrders: yesterdayOrders.length,
          revenueData,
          categoryData,
          popularItem,
          peakTime: '12:00 PM' // Placeholder
      };
  }
}

export const db = new SupabaseService();

import React, { useEffect, useState } from 'react';
import { HashRouter, Routes, Route, Navigate, useLocation, Link } from 'react-router-dom';
