                                className="bg-orange-50 text-orange-600 hover:bg-orange-500 hover:text-white px-4 py-2 rounded-xl font-bold text-sm transition-all flex items-center"
                            >
                                <Plus className="w-4 h-4 mr-1" /> ADD
                            </button>
                        </div>
                    </div>
                </div>
            ))}
        </div>
      </div>
    </div>
  );
};

