    super();
    // 1. Restore session from LocalStorage first (for speed)
    const stored = localStorage.getItem('qb_current_user');
    if (stored) this.currentUser = JSON.parse(stored);

    // 2. Listen for Real Supabase Auth Changes
    // (This might still trigger if you use real auth features later)
    supabase.auth.onAuthStateChange(async (event, session) => {
      if (event === 'SIGNED_IN' && session?.user) {
        const appUser: User = {
          id: session.user.id,
          name: session.user.user_metadata.full_name || 'Foodie',
          email: session.user.email || '',
          role: session.user.email === 'admin@quickbite.com' ? UserRole.ADMIN : UserRole.CUSTOMER
        };
        this.updateSession(appUser);
      } else if (event === 'SIGNED_OUT') {
        this.currentUser = null;
        localStorage.removeItem('qb_current_user');
      }
    });

    // Listen for realtime changes on orders
    this.setupRealtime();
