        name: 'Alex (Google User)',
        email: 'alex.google@example.com',
        role: UserRole.CUSTOMER // Default to customer
    };

    this.updateSession(mockGoogleUser);
  }

  async login(email: string): Promise<User> {
    // Keep this for "Quick Login" (Demo Mode)
    const user = INITIAL_USERS.find(u => u.email === email);
    if (!user) throw new Error('User not found');

    this.currentUser = user;
    localStorage.setItem('qb_current_user', JSON.stringify(user));
    return user;
  }

  async logout() {
    await supabase.auth.signOut();
    this.currentUser = null;
    localStorage.removeItem('qb_current_user');
    window.location.reload();
  }

  getCurrentUser(): User | null {
    return this.currentUser;
  }

  // --- Menu ---
  async getMenu(): Promise<MenuItem[]> {
    const { data, error } = await supabase.from('menu_items').select('*');
    if (error) {
      console.error('Error fetching menu:', error);
      return [];
    }
    return data as MenuItem[];
  }

  async addMenuItem(item: Omit<MenuItem, 'id'>) {
    const { error } = await supabase.from('menu_items').insert([item]);
    if (error) console.error(error);
    this.dispatchEvent(new Event('change'));
  }

  async deleteMenuItem(id: string) {
    await supabase.from('menu_items').delete().eq('id', id);
    this.dispatchEvent(new Event('change'));
  }

  // --- Orders ---
  async getOrders(): Promise<Order[]> {
    const { data, error } = await supabase.from('orders').select('*').order('createdAt', { ascending: false });
    if (error) return [];
    return data as Order[];
  }

  async getOrdersForUser(userId: string): Promise<Order[]> {
    const { data, error } = await supabase.from('orders').select('*').eq('userId', userId).order('createdAt', { ascending: false });
    if (error) return [];
    return data as Order[];
  }

  async createOrder(items: CartItem[], totalAmount: number, pickupSlotId: string, discountAmount: number = 0, couponCode?: string): Promise<Order> {
