const Navbar: React.FC<{ user: User | null; onLogout: () => void }> = ({ user, onLogout }) => {
  const location = useLocation();
  const isCustomer = user?.role === UserRole.CUSTOMER;
  const isAdmin = user?.role === UserRole.ADMIN || user?.role === UserRole.SPECIALIZED_ADMIN;
  const [cartCount, setCartCount] = useState(0);

  useEffect(() => {
    const updateCount = () => {
      const cart = JSON.parse(localStorage.getItem('qb_cart') || '[]');
      setCartCount(cart.reduce((acc: number, item: any) => acc + item.quantity, 0));
    };
    updateCount();
    window.addEventListener('storage', updateCount);
    // Custom event listener for immediate updates
    window.addEventListener('cart-updated', updateCount);
    return () => {
      window.removeEventListener('storage', updateCount);
      window.removeEventListener('cart-updated', updateCount);
    };
  }, []);

  if (!user) return null;

  return (
    <nav className="sticky top-0 z-50 bg-white/80 backdrop-blur-md border-b border-slate-100 shadow-sm">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          <div className="flex items-center">
            <div className="relative">
              <h1 className="text-2xl font-bold bg-gradient-to-r from-pink-500 to-orange-500 bg-clip-text text-transparent tracking-tight">
                Mood<span className="font-script text-slate-700">Bites</span>
              </h1>
              <Heart className="w-3 h-3 text-pink-500 absolute -top-1 -right-2 fill-current animate-pulse" />
            </div>
          </div>

          <div className="flex items-center space-x-6">
            {isCustomer && (
              <>
                <div className="hidden md:flex space-x-6">
                  <NavLink to="/menu" active={location.pathname === '/menu'}>Comfort Zone</NavLink>
                  <NavLink to="/orders" active={location.pathname === '/orders'}>My Orders</NavLink>
                </div>
                <div className="relative">
                  <NavLink to="/cart" active={location.pathname === '/cart'}>
                    <ShoppingBag className={`w-6 h-6 ${location.pathname === '/cart' ? 'text-orange-500' : 'text-slate-600'}`} />
                  </NavLink>
                  {cartCount > 0 && (
                    <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] font-bold w-4 h-4 flex items-center justify-center rounded-full shadow-sm">
                      {cartCount}
                    </span>
                  )}
                </div>
              </>
            )}
            {isAdmin && (
              <NavLink to="/admin" active={location.pathname.startsWith('/admin')}>Dashboard</NavLink>
            )}

            <div className="flex items-center space-x-2 pl-4 border-l border-slate-200">
              <button 
                onClick={onLogout}
                className="p-2 rounded-full hover:bg-slate-100 text-slate-400 hover:text-red-500 transition-colors"
                title="Sign Out"
              >
                <LogOut className="w-5 h-5" />
              </button>
            </div>
          </div>
        </div>
      </div>
    </nav>
  );
};

const NavLink: React.FC<{ to: string; active: boolean; children: React.ReactNode }> = ({ to, active, children }) => (
  <Link 
    to={to} 
    className={`text-sm font-semibold transition-colors ${
      active ? 'text-orange-500' : 'text-slate-500 hover:text-slate-900'
    }`}
  >
    {children}
  </Link>
);

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const checkUser = () => {
        const currentUser = db.getCurrentUser();
        setUser(currentUser);
        setLoading(false);
    };

    checkUser();

    // Listen for auth changes from the service instead of relying on reloading
    db.addEventListener('session-updated', checkUser);

    return () => {
        db.removeEventListener('session-updated', checkUser);
    };
  }, []);

  const handleLogout = () => {
    db.logout();
    // No need to setUser(null) here manually because the event listener will catch it
  };

  if (loading) return <div className="min-h-screen bg-slate-50 flex items-center justify-center text-orange-500">Loading Mood Bites...</div>;

  return (
    <HashRouter>
      <div className="min-h-screen bg-slate-50 text-slate-800 font-sans selection:bg-pink-100 selection:text-pink-600">
        <Navbar user={user} onLogout={handleLogout} />

        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <Routes>
            <Route path="/auth" element={!user ? <AuthPage onLogin={setUser} /> : <Navigate to={user.role === UserRole.CUSTOMER ? "/menu" : "/admin"} />} />

            {/* Customer Routes */}
            <Route path="/menu" element={user?.role === UserRole.CUSTOMER ? <CustomerMenu /> : <Navigate to="/auth" />} />
            <Route path="/cart" element={user?.role === UserRole.CUSTOMER ? <CustomerCart /> : <Navigate to="/auth" />} />
            <Route path="/orders" element={user?.role === UserRole.CUSTOMER ? <CustomerOrders /> : <Navigate to="/auth" />} />

            {/* Admin Routes */}
            <Route path="/admin" element={
              (user?.role === UserRole.ADMIN || user?.role === UserRole.SPECIALIZED_ADMIN) 
              ? <AdminDashboard user={user} /> 
              : <Navigate to="/auth" />
            } />

            <Route path="*" element={<Navigate to={user ? (user.role === UserRole.CUSTOMER ? "/menu" : "/admin") : "/auth"} />} />
          </Routes>
        </main>

        {user?.role === UserRole.CUSTOMER && <Chatbot />}
      </div>
    </HashRouter>
  );
}

export default App;

