  useEffect(() => {
    loadCart();

    // Listen for storage events (cross-tab)
    window.addEventListener('storage', loadCart);
    // Listen for internal app events (same-tab)
    window.addEventListener('cart-updated', loadCart);

    return () => {
      window.removeEventListener('storage', loadCart);
      window.removeEventListener('cart-updated', loadCart);
    };
  }, []);

  const updateQty = (id: string, delta: number) => {
    const newCart = cart.map(item => {
      if (item.id === id) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    });
    setCart(newCart);
    localStorage.setItem('qb_cart', JSON.stringify(newCart));
    window.dispatchEvent(new Event('cart-updated'));

    // Reset coupon if cart changes
    if (appliedCode) {
      setAppliedCode(null);
      setDiscount(0);
      setCouponMsg({ text: 'Cart modified, please re-apply coupon.', isError: true });
    }
  };

  const remove = (id: string) => {
    const newCart = cart.filter(item => item.id !== id);
    setCart(newCart);
    localStorage.setItem('qb_cart', JSON.stringify(newCart));
    window.dispatchEvent(new Event('cart-updated'));

    // Reset coupon
    if (appliedCode) {
      setAppliedCode(null);
      setDiscount(0);
      setCouponMsg({ text: '', isError: false });
    }
  };

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const tax = Math.round(subtotal * 0.05);
  // Ensure total doesn't drop below 0
  const finalTotal = Math.max(0, subtotal + tax - discount);

  const applyCoupon = () => {
    if (!couponCode.trim()) return;

    const result = db.validateCoupon(couponCode, cart);

    if (result.valid) {
      setDiscount(result.discount);
      setAppliedCode(couponCode);
      setCouponMsg({ text: result.message, isError: false });
    } else {
      setDiscount(0);
      setAppliedCode(null);
      setCouponMsg({ text: result.message, isError: true });
    }
  };

  const removeCoupon = () => {
    setCouponCode('');
    setDiscount(0);
    setAppliedCode(null);
    setCouponMsg({ text: '', isError: false });
  };

  const handlePayment = async () => {
    if (!selectedSlot) {
        setError('Please select a pickup time slot.');
        return;
    }

    setPaying(true);
    setError('');

    try {
      // Refresh user session just in case
      const user = db.getCurrentUser();
      if (!user) {
          throw new Error("Session expired. Please login again.");
      }

      // Simulate network delay
      await new Promise(resolve => setTimeout(resolve, 1500));

      // Create order (Async)
      await db.createOrder(cart, finalTotal, selectedSlot, discount, appliedCode || undefined);

      // Clear cart
      localStorage.removeItem('qb_cart');
      setCart([]);
      window.dispatchEvent(new Event('cart-updated'));

      navigate('/orders');
    } catch (err: any) {
      setError(err.message || 'Payment processing failed');
    } finally {
      setPaying(false);
    }
  };

  if (cart.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] text-center animate-in fade-in zoom-in duration-300">
        <div className="bg-orange-50 p-8 rounded-full shadow-lg mb-6 border border-orange-100">
          <ShoppingBag className="w-16 h-16 text-orange-400" />
        </div>
        <h2 className="text-3xl font-bold text-slate-800 mb-3">Your cart is empty</h2>
        <p className="text-slate-500 mb-8 max-w-md">Looks like you haven't added anything yet. Our kitchen is ready to whip up something delicious!</p>
        <button 
            onClick={() => navigate('/menu')} 
            className="bg-slate-900 text-white px-8 py-4 rounded-xl font-bold shadow-xl shadow-slate-900/20 hover:bg-black hover:scale-105 transition-all flex items-center"
        >
          Browse Menu <ChevronRight className="w-4 h-4 ml-2" />
        </button>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 pb-20">
      <div className="lg:col-span-2 space-y-6">

        {/* Kitchen Status Alert */}
        {kitchenLoad.level !== 'Low' && (
          <div className={`rounded-2xl p-4 flex items-start space-x-3 border shadow-sm animate-in fade-in slide-in-from-top-2 ${
            kitchenLoad.level === 'High' 
              ? 'bg-red-50 border-red-100 text-red-800' 
              : 'bg-orange-50 border-orange-100 text-orange-800'
          }`}>
             <div className={`p-2 rounded-full ${kitchenLoad.level === 'High' ? 'bg-red-100' : 'bg-orange-100'}`}>
                {kitchenLoad.level === 'High' ? <Flame className="w-5 h-5 animate-pulse" /> : <Clock className="w-5 h-5" />}
             </div>
             <div>
               <h3 className="font-bold text-sm">Kitchen is Busy</h3>
               <p className="text-xs opacity-90 mt-0.5">
                 High order volume right now. Slight delay expected (~{kitchenLoad.extraDelay} mins extra).
               </p>
             </div>
          </div>
        )}

        <h1 className="text-2xl font-bold text-slate-800 mb-6 flex items-center">
            Your Order 
            <span className="ml-3 bg-orange-100 text-orange-600 text-sm font-bold px-3 py-1 rounded-full">{cart.length} items</span>
        </h1>

        <div className="space-y-4">
          {cart.map(item => (
            <div key={item.id} className="bg-white border border-slate-100 p-4 rounded-2xl flex flex-col sm:flex-row items-center justify-between shadow-sm hover:shadow-md transition-shadow gap-4">
              <div className="flex items-center space-x-4 w-full sm:w-auto">
                <img src={item.image} alt={item.name} className="w-20 h-20 rounded-xl object-cover shadow-sm" />
                <div>
                  <h3 className="font-bold text-slate-800 text-lg">{item.name}</h3>
                  <p className="text-sm text-slate-500 font-medium">₹{item.price}</p>
                </div>
              </div>

              <div className="flex items-center justify-between w-full sm:w-auto sm:space-x-6">
                <div className="flex items-center bg-slate-50 rounded-xl p-1 border border-slate-200">
                  <button onClick={() => updateQty(item.id, -1)} className="p-2 hover:bg-white hover:shadow-sm rounded-lg text-slate-400 hover:text-slate-900 transition-all">
                    <Minus className="w-4 h-4" />
                  </button>
                  <span className="w-10 text-center text-sm font-bold text-slate-800">{item.quantity}</span>
                  <button onClick={() => updateQty(item.id, 1)} className="p-2 hover:bg-white hover:shadow-sm rounded-lg text-slate-400 hover:text-slate-900 transition-all">
                    <Plus className="w-4 h-4" />
                  </button>
                </div>
                <div className="flex items-center sm:block">
                     <span className="font-bold text-slate-800 mr-4 sm:hidden">₹{item.price * item.quantity}</span>
                    <button onClick={() => remove(item.id)} className="text-slate-300 hover:text-red-500 transition-colors p-2 bg-slate-50 rounded-lg hover:bg-red-50">
                    <Trash2 className="w-5 h-5" />
                    </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="lg:col-span-1">
        <div className="bg-white border border-slate-100 rounded-3xl p-6 sticky top-24 shadow-xl shadow-slate-200/50">
          <h2 className="text-xl font-bold text-slate-800 mb-6">Payment Details</h2>

          <div className="mb-6">
            <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wide mb-3 flex items-center">
              <Clock className="w-4 h-4 mr-2" /> Select Pickup Time
            </h3>
            <div className="grid grid-cols-2 gap-2 max-h-48 overflow-y-auto pr-1 custom-scrollbar">
              {slots.filter(s => s.available).map(slot => (
                <button
                  key={slot.id}
                  onClick={() => {
                      setSelectedSlot(slot.id);
                      setError('');
                  }}
                  className={`p-3 rounded-xl text-xs font-bold border transition-all ${
                    selectedSlot === slot.id 
                      ? 'bg-orange-500 text-white border-orange-500 shadow-md shadow-orange-500/20' 
                      : 'bg-slate-50 border-transparent text-slate-600 hover:bg-slate-100 hover:border-slate-200'
                  }`}
                >
                  {slot.time}
                </button>
              ))}
              {slots.filter(s => s.available).length === 0 && (
                  <div className="col-span-2 text-center text-xs text-red-500 font-bold p-2 bg-red-50 rounded-lg border border-red-100">
                      No slots available.
                  </div>
              )}
            </div>
          </div>

          {/* Coupon Code Section */}
          <div className="mb-6">
            <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wide mb-3 flex items-center">
              <Tag className="w-4 h-4 mr-2" /> Apply Coupon
            </h3>
            {!appliedCode ? (
              <div className="flex space-x-2">
                <input 
                  type="text" 
                  value={couponCode}
                  onChange={(e) => setCouponCode(e.target.value.toUpperCase())}
                  placeholder="CODE"
                  className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm font-bold uppercase placeholder-slate-400 focus:outline-none focus:border-orange-400"
                />
                <button 
                  onClick={applyCoupon}
                  className="bg-slate-900 text-white px-4 py-2 rounded-xl text-sm font-bold hover:bg-black transition-colors"
                >
                  Apply
                </button>
              </div>
            ) : (
              <div className="flex justify-between items-center bg-green-50 border border-green-200 rounded-xl px-4 py-3">
                <div className="flex items-center">
                  <Tag className="w-4 h-4 text-green-600 mr-2" />
                  <span className="font-bold text-green-700 text-sm tracking-wide">{appliedCode}</span>
                </div>
                <button onClick={removeCoupon} className="text-green-400 hover:text-green-600">
                  <X className="w-4 h-4" />
                </button>
              </div>
            )}
            {couponMsg.text && (
               <p className={`text-xs font-bold mt-2 ${couponMsg.isError ? 'text-red-500' : 'text-green-500'}`}>
                 {couponMsg.text}
               </p>
            )}
          </div>

          <div className="space-y-3 mb-6 pt-6 border-t border-slate-100">
            <div className="flex justify-between text-slate-500 text-sm">
              <span>Subtotal</span>
              <span>₹{subtotal}</span>
            </div>
            <div className="flex justify-between text-slate-500 text-sm">
              <span>Tax (5%)</span>
              <span>₹{tax}</span>
            </div>
            {discount > 0 && (
              <div className="flex justify-between text-green-600 text-sm font-bold">
                <span>Discount</span>
                <span>-₹{discount}</span>
              </div>
            )}
            <div className="flex justify-between text-slate-800 text-xl font-bold pt-2">
              <span>Total</span>
              <span>₹{finalTotal}</span>
            </div>
          </div>

          {error && (
            <div className="mb-4 p-3 bg-red-50 border border-red-100 rounded-xl flex items-center text-red-600 text-sm font-bold">
              <AlertTriangle className="w-4 h-4 mr-2" />
              {error}
            </div>
          )}

          <button
            onClick={handlePayment}
            disabled={paying}
            className="w-full bg-slate-900 hover:bg-black text-white py-4 rounded-xl font-bold shadow-lg shadow-slate-900/20 flex items-center justify-center transition-all disabled:opacity-70 disabled:cursor-not-allowed active:scale-[0.98]"
          >
            {paying ? (
              <span className="flex items-center">
                <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin mr-2"></span>
                Processing...
              </span>
            ) : (
              <span className="flex items-center">
                Pay Securely <ChevronRight className="w-4 h-4 ml-1" />
              </span>
            )}
          </button>

          <div className="mt-4 flex items-center justify-center text-slate-400 text-[10px] font-semibold bg-slate-50 py-2 rounded-lg border border-slate-100">
             <CreditCard className="w-3 h-3 mr-2" />
             <span>SECURE ENCRYPTED PAYMENT (SIMULATED)</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CartPage;

import React, { useEffect, useState } from 'react';
import { db } from '../../services/supabaseService';
import { MenuItem, Order, OrderStatus, User, UserRole, FoodCategory, Coupon, DiscountType } from '../../types';
import { AreaChart, Area, PieChart, Pie, Cell, Legend, ResponsiveContainer, XAxis, YAxis, CartesianGrid, Tooltip } from 'recharts';
import { Users, DollarSign, ShoppingBag, Edit, Trash, Plus, Search, Utensils, Clock, AlertCircle, Scan, CheckCircle, XCircle, Tag, Ticket, TrendingUp, TrendingDown, Award, Flame, Zap } from 'lucide-react';

interface AdminDashboardProps {
  user: User;
}

const COLORS = ['#f97316', '#ef4444', '#3b82f6', '#10b981'];

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'orders' | 'history' | 'menu' | 'users' | 'coupons'>('dashboard');

  // Initialize with empty/safe default values
  const [analytics, setAnalytics] = useState({
      todayRevenue: 0, yesterdayRevenue: 0, todayOrders: 0, yesterdayOrders: 0,
      revenueData: [] as any[], categoryData: [] as any[], popularItem: { name: 'Loading', count: 0 }, peakTime: '--',
      kitchenLoad: 'Low', activeOrders: 0
  });

  const [orders, setOrders] = useState<Order[]>([]);
  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [coupons, setCoupons] = useState<Coupon[]>([]);
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    const updateData = async () => {
      const stats = await db.getAnalytics();
      setAnalytics(stats);

      const menuData = await db.getMenu();
      setMenu(menuData);

      setCoupons(db.getCoupons()); // Coupons still mock in this implementation

      let allOrders = await db.getOrders();
      if (user.role === UserRole.SPECIALIZED_ADMIN && user.specialty) {
        allOrders = allOrders.filter(o => o.items.some(i => i.category === user.specialty));
      }
      setOrders(allOrders);
    };

    updateData();
    db.addEventListener('change', updateData);

    // Timer for live updates
    const interval = setInterval(() => setNow(Date.now()), 1000);

    return () => {
      db.removeEventListener('change', updateData);
      clearInterval(interval);
    };
  }, [user]);

  const updateStatus = async (id: string, status: OrderStatus) => {
    await db.updateOrderStatus(id, status);
  };

  const deleteMenuItem = async (id: string) => {
    if (confirm('Delete this item?')) {
        await db.deleteMenuItem(id);
    }
  };

  const deleteCoupon = (id: string) => {
    if (confirm('Delete this coupon?')) {
        db.deleteCoupon(id);
    }
  };

  const handleAddMenu = async () => {
      const name = prompt("Item Name:");
      if(!name) return;
      const price = Number(prompt("Price:"));
      await db.addMenuItem({
          name,
          description: 'New yummy item',
          price: price || 100,
          category: FoodCategory.SNACKS,
          image: 'https://picsum.photos/400/300',
          isVeg: true
      });
  };

  const handleAddCoupon = () => {
    const code = prompt("Enter Coupon Code (e.g. SAVE20):");
    if(!code) return;

    const typeStr = prompt("Discount Type (PERCENTAGE / FLAT):", "PERCENTAGE");
    const type = typeStr?.toUpperCase() === 'FLAT' ? DiscountType.FLAT : DiscountType.PERCENTAGE;

    const value = Number(prompt(type === DiscountType.PERCENTAGE ? "Enter Percentage (e.g. 20 for 20%):" : "Enter Flat Amount (e.g. 50 for ₹50 off):"));
    if(isNaN(value)) return;

    const categoryInput = prompt("Restrict to Category? (LUNCH, BREAKFAST, SNACKS, DRINKS) or leave empty for ALL:");
    const category = categoryInput ? (categoryInput.toUpperCase() as any) : 'ALL';

    const expiryDate = prompt("Expiry Date (YYYY-MM-DD):", "2025-12-31");
    if(!expiryDate) return;

    db.addCoupon({
      code: code.toUpperCase(),
      type,
      value,
      category,
      expiryDate
    });
  };

  const handleScanQR = () => {
      // Simulate scanning by asking for the Order ID
      const orderId = prompt("📷 SIMULATE QR SCANNER\n\nPoint camera at Customer's QR Code.\n(Or enter Order ID manually below):");

      if (!orderId) return;

      const order = orders.find(o => o.id === orderId.trim());

      if (!order) {
          alert("❌ INVALID QR CODE\n\nOrder not found in the system.");
          return;
      }

      if (order.status === OrderStatus.COMPLETED) {
          alert("⚠️ ALREADY USED\n\nThis order has already been picked up.");
          return;
      }

      if (order.status !== OrderStatus.READY) {
          alert(`⚠️ NOT READY\n\nThis order is currently '${order.status}'.\nIt must be 'Ready for Pickup' to complete.`);
          return;
      }

      // Valid case
      const confirmPickup = confirm(
          `✅ QR VERIFIED!\n\nOrder #${order.id}\nItems: ${order.items.length}\nTotal Paid: ₹${order.totalAmount}\n\nComplete pickup?`
      );

      if (confirmPickup) {
          updateStatus(order.id, OrderStatus.COMPLETED);
          alert("🎉 SUCCESS\n\nOrder marked as COMPLETED.");
      }
  };

  const getTimerDisplay = (order: Order) => {
    if (order.status !== OrderStatus.PREPARING || !order.targetTime) return null;
    const remainingMs = order.targetTime - now;
    if (remainingMs <= 0) return <span className="text-red-500 font-bold text-xs">Overdue</span>;

    const minutes = Math.floor(remainingMs / 60000);
    const seconds = Math.floor((remainingMs % 60000) / 1000);
    const isLate = remainingMs < 60000; // Less than 1 min

    return (
        <span className={`text-xs font-mono font-bold px-2 py-1 rounded ${isLate ? 'bg-red-100 text-red-600 animate-pulse' : 'bg-slate-100 text-slate-700'}`}>
            {minutes}:{seconds.toString().padStart(2, '0')}
        </span>
    );
  };

  const getTrend = (curr: number, prev: number) => {
    if (prev === 0) return { val: 100, isUp: true };
    const diff = ((curr - prev) / prev) * 100;
    return { val: Math.abs(diff).toFixed(1), isUp: diff >= 0 };
  };

  const revTrend = getTrend(analytics.todayRevenue, analytics.yesterdayRevenue);
  const ordTrend = getTrend(analytics.todayOrders, analytics.yesterdayOrders);


  return (
    <div className="space-y-8">
      {/* Header & Tabs */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-slate-800">
            {user.role === UserRole.SPECIALIZED_ADMIN ? `${user.specialty} Kitchen` : 'Admin Dashboard'}
          </h1>
          <p className="text-slate-500">Overview of canteen operations.</p>
        </div>

        <div className="flex items-center gap-4">
            <button 
                onClick={handleScanQR}
                className="bg-slate-900 hover:bg-black text-white px-5 py-2.5 rounded-xl font-bold shadow-lg shadow-slate-900/20 flex items-center transition-all active:scale-95"
            >
                <Scan className="w-5 h-5 mr-2" />
                Scan QR Code
            </button>

            <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm overflow-x-auto">
            {[
                { id: 'dashboard', label: 'Analytics' },
                { id: 'orders', label: 'Orders' },
                { id: 'history', label: 'History' },
                { id: 'menu', label: 'Menu' },
                { id: 'coupons', label: 'Coupons' },
                { id: 'users', label: 'Users' }
            ].map(tab => (
                <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all whitespace-nowrap ${
                    activeTab === tab.id ? 'bg-slate-900 text-white shadow-md' : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                }`}
                >
                {tab.label}
                </button>
            ))}
            </div>
        </div>
      </div>

      {activeTab === 'dashboard' && (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4">

          {/* Summary Cards */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="bg-white border border-slate-100 p-6 rounded-3xl shadow-sm">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-slate-400 text-xs font-bold uppercase tracking-wider">Today's Revenue</h3>
                <div className="p-2 bg-green-50 rounded-full">
                  <DollarSign className="text-green-600 w-5 h-5" />
                </div>
              </div>
              <p className="text-3xl font-bold text-slate-800">₹{analytics.todayRevenue.toLocaleString()}</p>
              <div className={`flex items-center mt-2 text-xs font-bold ${revTrend.isUp ? 'text-green-500' : 'text-red-500'}`}>
                {revTrend.isUp ? <TrendingUp className="w-3 h-3 mr-1" /> : <TrendingDown className="w-3 h-3 mr-1" />}
                {revTrend.val}% vs yesterday
              </div>
            </div>

            <div className="bg-white border border-slate-100 p-6 rounded-3xl shadow-sm">
               <div className="flex items-center justify-between mb-4">
                <h3 className="text-slate-400 text-xs font-bold uppercase tracking-wider">Most Ordered</h3>
                <div className="p-2 bg-orange-50 rounded-full">
                  <Award className="text-orange-600 w-5 h-5" />
                </div>
              </div>
              <p className="text-lg font-bold text-slate-800 line-clamp-1" title={analytics.popularItem.name}>{analytics.popularItem.name}</p>
              <p className="text-xs text-slate-500 mt-1 font-medium">{analytics.popularItem.count} sold all time</p>
            </div>

            {/* Kitchen Load Card */}
            <div className={`border p-6 rounded-3xl shadow-sm transition-colors ${analytics.kitchenLoad === 'High' ? 'bg-red-50 border-red-100' : analytics.kitchenLoad === 'Medium' ? 'bg-orange-50 border-orange-100' : 'bg-white border-slate-100'}`}>
               <div className="flex items-center justify-between mb-4">
                <h3 className={`text-xs font-bold uppercase tracking-wider ${analytics.kitchenLoad === 'High' ? 'text-red-400' : analytics.kitchenLoad === 'Medium' ? 'text-orange-400' : 'text-slate-400'}`}>Kitchen Load</h3>
                <div className={`p-2 rounded-full ${analytics.kitchenLoad === 'High' ? 'bg-red-200' : analytics.kitchenLoad === 'Medium' ? 'bg-orange-200' : 'bg-slate-50'}`}>
                  <Zap className={`w-5 h-5 ${analytics.kitchenLoad === 'High' ? 'text-red-600' : analytics.kitchenLoad === 'Medium' ? 'text-orange-600' : 'text-slate-400'}`} />
                </div>
              </div>
              <p className={`text-3xl font-bold ${analytics.kitchenLoad === 'High' ? 'text-red-800' : analytics.kitchenLoad === 'Medium' ? 'text-orange-800' : 'text-slate-800'}`}>{analytics.kitchenLoad}</p>
              <p className={`text-xs mt-1 font-bold ${analytics.kitchenLoad === 'High' ? 'text-red-600' : analytics.kitchenLoad === 'Medium' ? 'text-orange-600' : 'text-slate-500'}`}>
                 {analytics.activeOrders} Active Orders
              </p>
            </div>

            <div className="bg-white border border-slate-100 p-6 rounded-3xl shadow-sm">
               <div className="flex items-center justify-between mb-4">
                <h3 className="text-slate-400 text-xs font-bold uppercase tracking-wider">Peak Time</h3>
                <div className="p-2 bg-purple-50 rounded-full">
                  <Clock className="text-purple-600 w-5 h-5" />
                </div>
              </div>
              <p className="text-3xl font-bold text-slate-800">{analytics.peakTime}</p>
              <p className="text-xs text-slate-500 mt-1 font-medium">Busiest hour</p>
            </div>
