      { id: 'm2', name: 'Chicken Caesar Salad', description: 'Crisp romaine with grilled chicken.', price: 220, category: FoodCategory.LUNCH, image: 'https://images.unsplash.com/photo-1550304943-4f24f54ddde9?auto=format&fit=crop&w=400&q=80', isVeg: false },
      { id: 'm3', name: 'Masala Dosa', description: 'Crispy rice crepe with potato filling.', price: 120, category: FoodCategory.BREAKFAST, image: 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?auto=format&fit=crop&w=400&q=80', isVeg: true },
      { id: 'm4', name: 'Cold Coffee', description: 'Chilled rich coffee with ice cream.', price: 90, category: FoodCategory.DRINKS, image: 'https://images.unsplash.com/photo-1517701550927-30cf4ba1dba5?auto=format&fit=crop&w=400&q=80', isVeg: true },
      { id: 'm5', name: 'Loaded Nachos', description: 'Tortilla chips with cheese and salsa.', price: 180, category: FoodCategory.SNACKS, image: 'https://images.unsplash.com/photo-1513456852971-30cfa382025e?auto=format&fit=crop&w=400&q=80', isVeg: true },
