    return () => db.removeEventListener('change', fetchMenu);
  }, []);

  const addToCart = (item: MenuItem) => {
    const cart: CartItem[] = JSON.parse(localStorage.getItem('qb_cart') || '[]');
    const existing = cart.find(i => i.id === item.id);
    if (existing) {
      existing.quantity += 1;
    } else {
      cart.push({ ...item, quantity: 1 });
