                  <MoodEmoji mood="Cozy" icon="🧸" active={selectedMood === 'Cozy'} onClick={() => setSelectedMood('Cozy')} />
                  <MoodEmoji mood="Stressed" icon="😫" active={selectedMood === 'Stressed'} onClick={() => setSelectedMood('Stressed')} />
                  <MoodEmoji mood="Hungry" icon="🤤" active={selectedMood === 'Hungry'} onClick={() => setSelectedMood('Hungry')} />
                </div>

                <button
                  onClick={handleMoodSubmit}
                  disabled={!selectedMood || aiLoading}
                  className="w-full bg-orange-500 hover:bg-orange-600 disabled:opacity-50 text-white font-bold py-4 rounded-xl shadow-lg shadow-orange-500/30 transition-all flex items-center justify-center"
                >
                  {aiLoading ? (
                    <span className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
                  ) : (
                    'Secure Mood'
                  )}
                </button>
                <button 
                  onClick={() => setShowMoodModal(false)}
                  className="mt-4 text-sm text-slate-400 font-medium hover:text-slate-600"
                >
                  Maybe Later
                </button>
              </div>
            ) : (
              <div className="p-8 text-center bg-orange-50/50">
                 <div className="w-20 h-20 bg-white rounded-full mx-auto flex items-center justify-center shadow-md mb-4 text-4xl border-2 border-orange-100 animate-bounce">
                    👨‍🍳
                 </div>
                 <h3 className="text-lg font-bold text-slate-800 mb-2">Chef Byte Suggests:</h3>
                 <div className="bg-white p-5 rounded-2xl shadow-sm border border-orange-100 mb-6">
                    <h4 className="font-bold text-orange-600 text-xl mb-2">{suggestion.name}</h4>
