    const storedReviews = localStorage.getItem('qb_reviews');
    if (storedReviews) this.reviews = JSON.parse(storedReviews);

    // 2. Listen for Real Supabase Auth Changes
    supabase.auth.onAuthStateChange(async (event, session) => {
      if (event === 'SIGNED_IN' && session?.user) {
        const appUser: User = {
          id: session.user.id,
          name: session.user.user_metadata.full_name || session.user.email?.split('@')[0] || 'Foodie',
          email: session.user.email || '',
          role: session.user.email === 'admin@quickbite.com' ? UserRole.ADMIN : UserRole.CUSTOMER
        };

        const currentStored = localStorage.getItem('qb_current_user');
        const isDifferent = !currentStored || JSON.parse(currentStored).id !== appUser.id;

        if (isDifferent) {
            this.updateSession(appUser);
        }
      } else if (event === 'SIGNED_OUT') {
        if (this.currentUser) {
            this.currentUser = null;
            localStorage.removeItem('qb_current_user');
            this.dispatchEvent(new Event('session-updated'));
        }
      }
    });

    this.setupRealtime();
  }

