const COLORS = ['#f97316', '#ef4444', '#3b82f6', '#10b981'];

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'orders' | 'history' | 'menu' | 'users' | 'coupons'>('dashboard');

  // Analytics State
  const [analytics, setAnalytics] = useState({
      todayRevenue: 0, yesterdayRevenue: 0, todayOrders: 0, yesterdayOrders: 0,
      revenueData: [] as any[], categoryData: [] as any[], popularItem: { name: 'Loading', count: 0 }, peakTime: '--',
      kitchenLoad: 'Low', activeOrders: 0,
      lowestRated: [] as MenuItem[], mostReviewed: [] as MenuItem[]
  });

  const [orders, setOrders] = useState<Order[]>([]);
  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [coupons, setCoupons] = useState<Coupon[]>([]);
  const [now, setNow] = useState(Date.now());

  // Menu Modal State
  const [isMenuModalOpen, setIsMenuModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [menuForm, setMenuForm] = useState<Partial<MenuItem>>({
      name: '', price: 0, category: FoodCategory.LUNCH, description: '', image: '', isVeg: true
  });

  useEffect(() => {
    const updateData = async () => {
      const stats = await db.getAnalytics();
      setAnalytics(stats);

      const menuData = await db.getMenu();
      setMenu(menuData);

      setCoupons(db.getCoupons()); // Coupons still mock in this implementation

      let allOrders = await db.getOrders();
      if (user.role === UserRole.SPECIALIZED_ADMIN && user.specialty) {
        allOrders = allOrders.filter(o => o.items.some(i => i.category === user.specialty));
      }
      setOrders(allOrders);
    };

    updateData();
    db.addEventListener('change', updateData);

    // Timer for live updates
    const interval = setInterval(() => setNow(Date.now()), 1000);

    return () => {
      db.removeEventListener('change', updateData);
      clearInterval(interval);
    };
  }, [user]);

  const updateStatus = async (id: string, status: OrderStatus) => {
    await db.updateOrderStatus(id, status);
  };

  const deleteMenuItem = async (id: string) => {
    if (confirm('Delete this item? This cannot be undone.')) {
        await db.deleteMenuItem(id);
    }
  };

  const deleteCoupon = (id: string) => {
    if (confirm('Delete this coupon?')) {
        db.deleteCoupon(id);
    }
  };

  const handleOpenMenuModal = (item?: MenuItem) => {
      if (item) {
          setEditingItem(item);
          setMenuForm({ ...item });
      } else {
          setEditingItem(null);
          setMenuForm({
            name: '', 
            price: 100, 
            category: FoodCategory.LUNCH, 
            description: '', 
            image: 'https://picsum.photos/400/300', 
            isVeg: true
          });
      }
      setIsMenuModalOpen(true);
  };

  const handleMenuSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!menuForm.name || !menuForm.price) return;

      try {
          if (editingItem) {
              await db.updateMenuItem(editingItem.id, menuForm);
          } else {
              await db.addMenuItem(menuForm as any);
          }
          setIsMenuModalOpen(false);
      } catch (err) {
          alert('Failed to save item');
      }
  };

  const handleAddCoupon = () => {
    // ... existing prompt logic for coupons ...
    const code = prompt("Enter Coupon Code (e.g. SAVE20):");
    if(!code) return;

    const typeStr = prompt("Discount Type (PERCENTAGE / FLAT):", "PERCENTAGE");
    const type = typeStr?.toUpperCase() === 'FLAT' ? DiscountType.FLAT : DiscountType.PERCENTAGE;

    const value = Number(prompt(type === DiscountType.PERCENTAGE ? "Enter Percentage (e.g. 20 for 20%):" : "Enter Flat Amount (e.g. 50 for ₹50 off):"));
    if(isNaN(value)) return;

    const categoryInput = prompt("Restrict to Category? (LUNCH, BREAKFAST, SNACKS, DRINKS) or leave empty for ALL:");
    const category = categoryInput ? (categoryInput.toUpperCase() as any) : 'ALL';

    const expiryDate = prompt("Expiry Date (YYYY-MM-DD):", "2025-12-31");
    if(!expiryDate) return;

    db.addCoupon({ code: code.toUpperCase(), type, value, category, expiryDate });
  };

  const handleScanQR = () => {
      const orderId = prompt("📷 SIMULATE QR SCANNER\n\nPoint camera at Customer's QR Code.\n(Or enter Order ID manually below):");
      if (!orderId) return;
      const order = orders.find(o => o.id === orderId.trim());

      if (!order) { alert("❌ INVALID QR CODE\n\nOrder not found."); return; }
      if (order.status === OrderStatus.COMPLETED) { alert("⚠️ ALREADY USED\n\nOrder already picked up."); return; }
      if (order.status !== OrderStatus.READY) { alert(`⚠️ NOT READY\n\nOrder status: ${order.status}. Must be 'Ready'.`); return; }

      if (confirm(`✅ QR VERIFIED!\n\nOrder #${order.id}\nItems: ${order.items.length}\nTotal: ₹${order.totalAmount}\n\nComplete pickup?`)) {
          updateStatus(order.id, OrderStatus.COMPLETED);
          alert("🎉 SUCCESS\n\nOrder marked as COMPLETED.");
      }
  };

  const getTimerDisplay = (order: Order) => {
    if (order.status !== OrderStatus.PREPARING || !order.targetTime) return null;
    const remainingMs = order.targetTime - now;
    if (remainingMs <= 0) return <span className="text-red-500 font-bold text-xs">Overdue</span>;

    const minutes = Math.floor(remainingMs / 60000);
    const seconds = Math.floor((remainingMs % 60000) / 1000);
    return (
        <span className={`text-xs font-mono font-bold px-2 py-1 rounded ${remainingMs < 60000 ? 'bg-red-100 text-red-600 animate-pulse' : 'bg-slate-100 text-slate-700'}`}>
            {minutes}:{seconds.toString().padStart(2, '0')}
        </span>
    );
  };

  const getTrend = (curr: number, prev: number) => {
    if (prev === 0) return { val: 100, isUp: true };
    const diff = ((curr - prev) / prev) * 100;
    return { val: Math.abs(diff).toFixed(1), isUp: diff >= 0 };
  };

  const revTrend = getTrend(analytics.todayRevenue, analytics.yesterdayRevenue);


  return (
    <div className="space-y-8 relative">
      {/* Header & Tabs */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-slate-800">
            {user.role === UserRole.SPECIALIZED_ADMIN ? `${user.specialty} Kitchen` : 'Admin Dashboard'}
          </h1>
          <p className="text-slate-500">Overview of canteen operations.</p>
        </div>

        <div className="flex items-center gap-4">
            <button 
                onClick={handleScanQR}
                className="bg-slate-900 hover:bg-black text-white px-5 py-2.5 rounded-xl font-bold shadow-lg shadow-slate-900/20 flex items-center transition-all active:scale-95"
            >
                <Scan className="w-5 h-5 mr-2" />
                Scan QR Code
            </button>

            <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm overflow-x-auto">
            {[
                { id: 'dashboard', label: 'Analytics' },
                { id: 'orders', label: 'Orders' },
                { id: 'history', label: 'History' },
                { id: 'menu', label: 'Menu' },
                { id: 'coupons', label: 'Coupons' },
                { id: 'users', label: 'Users' }
            ].map(tab => (
                <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id as any)}
                className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all whitespace-nowrap ${
                    activeTab === tab.id ? 'bg-slate-900 text-white shadow-md' : 'text-slate-500 hover:text-slate-900 hover:bg-slate-50'
                }`}
                >
                {tab.label}
                </button>
            ))}
            </div>
        </div>
      </div>

      {activeTab === 'dashboard' && (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4">

          {/* Summary Cards */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="bg-white border border-slate-100 p-6 rounded-3xl shadow-sm">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-slate-400 text-xs font-bold uppercase tracking-wider">Today's Revenue</h3>
                <div className="p-2 bg-green-50 rounded-full">
                  <DollarSign className="text-green-600 w-5 h-5" />
                </div>
              </div>
              <p className="text-3xl font-bold text-slate-800">₹{analytics.todayRevenue.toLocaleString()}</p>
              <div className={`flex items-center mt-2 text-xs font-bold ${revTrend.isUp ? 'text-green-500' : 'text-red-500'}`}>
                {revTrend.isUp ? <TrendingUp className="w-3 h-3 mr-1" /> : <TrendingDown className="w-3 h-3 mr-1" />}
                {revTrend.val}% vs yesterday
              </div>
            </div>

            <div className="bg-white border border-slate-100 p-6 rounded-3xl shadow-sm">
               <div className="flex items-center justify-between mb-4">
                <h3 className="text-slate-400 text-xs font-bold uppercase tracking-wider">Most Ordered</h3>
                <div className="p-2 bg-orange-50 rounded-full">
                  <Award className="text-orange-600 w-5 h-5" />
                </div>
              </div>
              <p className="text-lg font-bold text-slate-800 line-clamp-1" title={analytics.popularItem.name}>{analytics.popularItem.name}</p>
              <p className="text-xs text-slate-500 mt-1 font-medium">{analytics.popularItem.count} sold all time</p>
            </div>

            {/* Kitchen Load Card */}
            <div className={`border p-6 rounded-3xl shadow-sm transition-colors ${analytics.kitchenLoad === 'High' ? 'bg-red-50 border-red-100' : analytics.kitchenLoad === 'Medium' ? 'bg-orange-50 border-orange-100' : 'bg-white border-slate-100'}`}>
               <div className="flex items-center justify-between mb-4">
                <h3 className={`text-xs font-bold uppercase tracking-wider ${analytics.kitchenLoad === 'High' ? 'text-red-400' : analytics.kitchenLoad === 'Medium' ? 'text-orange-400' : 'text-slate-400'}`}>Kitchen Load</h3>
                <div className={`p-2 rounded-full ${analytics.kitchenLoad === 'High' ? 'bg-red-200' : analytics.kitchenLoad === 'Medium' ? 'bg-orange-200' : 'bg-slate-50'}`}>
                  <Zap className={`w-5 h-5 ${analytics.kitchenLoad === 'High' ? 'text-red-600' : analytics.kitchenLoad === 'Medium' ? 'text-orange-600' : 'text-slate-400'}`} />
                </div>
              </div>
              <p className={`text-3xl font-bold ${analytics.kitchenLoad === 'High' ? 'text-red-800' : analytics.kitchenLoad === 'Medium' ? 'text-orange-800' : 'text-slate-800'}`}>{analytics.kitchenLoad}</p>
              <p className={`text-xs mt-1 font-bold ${analytics.kitchenLoad === 'High' ? 'text-red-600' : analytics.kitchenLoad === 'Medium' ? 'text-orange-600' : 'text-slate-500'}`}>
                 {analytics.activeOrders} Active Orders
              </p>
            </div>

            <div className="bg-white border border-slate-100 p-6 rounded-3xl shadow-sm">
               <div className="flex items-center justify-between mb-4">
                <h3 className="text-slate-400 text-xs font-bold uppercase tracking-wider">Peak Time</h3>
                <div className="p-2 bg-purple-50 rounded-full">
                  <Clock className="text-purple-600 w-5 h-5" />
                </div>
              </div>
              <p className="text-3xl font-bold text-slate-800">{analytics.peakTime}</p>
              <p className="text-xs text-slate-500 mt-1 font-medium">Busiest hour</p>
            </div>
          </div>

          {/* Rating Insights Row */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
               <div className="bg-white border border-slate-100 p-6 rounded-3xl shadow-sm">
                  <div className="flex items-center justify-between mb-6">
                      <h3 className="text-slate-800 font-bold flex items-center">
                          <ThumbsDown className="w-5 h-5 mr-2 text-red-400" /> Lowest Rated Items
                      </h3>
                      <span className="text-xs text-slate-400 font-bold uppercase">Needs Improvement</span>
                  </div>
                  <div className="space-y-4">
                      {analytics.lowestRated.map((item, idx) => (
                          <div key={idx} className="flex items-center justify-between p-3 bg-red-50/50 rounded-xl border border-red-50">
                              <div className="flex items-center">
                                  <div className="w-8 h-8 rounded-lg bg-white border border-red-100 flex items-center justify-center font-bold text-red-500 text-xs mr-3">
                                      {item.averageRating?.toFixed(1)}
                                  </div>
                                  <span className="font-medium text-slate-700">{item.name}</span>
                              </div>
                              <span className="text-xs text-slate-400">{item.totalReviews || 0} reviews</span>
                          </div>
                      ))}
                      {analytics.lowestRated.length === 0 && <p className="text-center text-slate-400 text-sm">No rating data available.</p>}
                  </div>
               </div>

               <div className="bg-white border border-slate-100 p-6 rounded-3xl shadow-sm">
                   <div className="flex items-center justify-between mb-6">
                      <h3 className="text-slate-800 font-bold flex items-center">
                          <MessageCircle className="w-5 h-5 mr-2 text-blue-400" /> Most Reviewed
                      </h3>
                      <span className="text-xs text-slate-400 font-bold uppercase">Community Buzz</span>
                  </div>
                  <div className="space-y-4">
                      {analytics.mostReviewed.map((item, idx) => (
                          <div key={idx} className="flex items-center justify-between p-3 bg-blue-50/50 rounded-xl border border-blue-50">
                              <div className="flex items-center">
                                  <div className="w-8 h-8 rounded-lg bg-white border border-blue-100 flex items-center justify-center font-bold text-blue-500 text-xs mr-3">
                                      {item.totalReviews}
                                  </div>
                                  <span className="font-medium text-slate-700">{item.name}</span>
                              </div>
                              <div className="flex items-center text-xs text-slate-400">
                                  <Star className="w-3 h-3 text-yellow-400 fill-current mr-1" />
                                  {item.averageRating?.toFixed(1)}
                              </div>
                          </div>
                      ))}
                      {analytics.mostReviewed.length === 0 && <p className="text-center text-slate-400 text-sm">No review data available.</p>}
                  </div>
               </div>
          </div>

          {/* Charts Row */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
             <div className="lg:col-span-2 bg-white border border-slate-100 p-6 rounded-3xl shadow-sm">
                <h3 className="text-slate-800 font-bold mb-6">Revenue Trend (Last 7 Days)</h3>
                <div className="h-64 w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={analytics.revenueData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                      <defs>
                        <linearGradient id="colorRev" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="5%" stopColor="#f97316" stopOpacity={0.2}/>
                          <stop offset="95%" stopColor="#f97316" stopOpacity={0}/>
                        </linearGradient>
                      </defs>
                      <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 12, fill: '#94a3b8'}} />
                      <YAxis axisLine={false} tickLine={false} tick={{fontSize: 12, fill: '#94a3b8'}} tickFormatter={(value) => `₹${value}`} />
                      <CartesianGrid vertical={false} stroke="#f1f5f9" />
                      <Tooltip 
                        contentStyle={{ backgroundColor: '#1e293b', border: 'none', borderRadius: '8px', color: '#fff' }}
                        itemStyle={{ color: '#fff' }}
                        formatter={(value: any) => [`₹${value}`, 'Revenue'] as [string, string]}
                      />
                      <Area type="monotone" dataKey="revenue" stroke="#f97316" strokeWidth={3} fillOpacity={1} fill="url(#colorRev)" />
                    </AreaChart>
                  </ResponsiveContainer>
                </div>
             </div>

             <div className="bg-white border border-slate-100 p-6 rounded-3xl shadow-sm">
                <h3 className="text-slate-800 font-bold mb-6">Orders by Category</h3>
                <div className="h-64 w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={analytics.categoryData}
                        innerRadius={60}
                        outerRadius={80}
                        paddingAngle={5}
                        dataKey="value"
                      >
                        {analytics.categoryData.map((entry: any, index: any) => (
                          <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                        ))}
                      </Pie>
                      <Tooltip contentStyle={{ borderRadius: '8px' }} />
                      <Legend verticalAlign="bottom" height={36} iconType="circle" />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
             </div>
          </div>
        </div>
      )}

      {/* ... Orders Tab ... */}
      {activeTab === 'orders' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in">
          {['Confirmed', 'Preparing', 'Ready for Pickup'].map(status => (
            <div key={status} className="bg-slate-50 border border-slate-200 rounded-2xl p-4 flex flex-col h-full">
              <h3 className="font-bold text-slate-700 mb-4 pb-2 border-b border-slate-200 flex justify-between items-center">
                {status}
                <span className="bg-white text-slate-800 text-xs font-bold py-1 px-2.5 rounded-full border border-slate-200 shadow-sm">{orders.filter(o => o.status === status).length}</span>
              </h3>
              <div className="space-y-3 overflow-y-auto max-h-[600px] pr-2 custom-scrollbar">
                {orders.filter(o => o.status === status).map(order => (
                  <div key={order.id} className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm hover:shadow-md transition-shadow">
                    <div className="flex justify-between items-start mb-3">
                        <span className="text-xs font-bold text-slate-400">#{order.id}</span>
                        <div className="flex items-center space-x-2">
                             {order.status === OrderStatus.PREPARING && getTimerDisplay(order)}
                             <span className="text-xs font-bold text-slate-600 bg-slate-100 px-2 py-1 rounded">{order.pickupTime}</span>
                        </div>
                    </div>
                    <div className="space-y-2 mb-4">
                        {order.items.map((i, idx) => (
                            <div key={idx} className="text-sm text-slate-700 flex justify-between font-medium">
                                <span><span className="text-orange-500 mr-1">{i.quantity}x</span> {i.name}</span>
                            </div>
                        ))}
                    </div>
                    <div className="flex justify-between items-center mt-3 pt-3 border-t border-slate-50">
                        {status === 'Confirmed' && (
                            <button 
                                onClick={() => updateStatus(order.id, OrderStatus.PREPARING)}
                                className="w-full bg-blue-50 hover:bg-blue-100 text-blue-600 font-bold text-xs py-2.5 rounded-lg transition-colors border border-blue-100"
                            >
                                Start Cooking
                            </button>
                        )}
                        {status === 'Preparing' && (
                            <button 
                                onClick={() => updateStatus(order.id, OrderStatus.READY)}
                                className="w-full bg-orange-50 hover:bg-orange-100 text-orange-600 font-bold text-xs py-2.5 rounded-lg transition-colors border border-orange-100"
                            >
                                Mark Ready
                            </button>
                        )}
                        {status === 'Ready for Pickup' && (
                            <button 
                                onClick={() => updateStatus(order.id, OrderStatus.COMPLETED)}
                                className="w-full bg-green-50 hover:bg-green-100 text-green-600 font-bold text-xs py-2.5 rounded-lg transition-colors border border-green-100"
                            >
                                Complete Order
                            </button>
                        )}
                    </div>
                  </div>
                ))}
                {orders.filter(o => o.status === status).length === 0 && (
                    <div className="text-center text-slate-400 text-sm py-12 flex flex-col items-center">
                        <Utensils className="w-8 h-8 mb-2 opacity-20" />
                        No orders
                    </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* ... History Tab ... */}
      {activeTab === 'history' && (
          <div className="bg-white border border-slate-200 rounded-3xl overflow-hidden shadow-sm animate-in fade-in">
             <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                <h3 className="font-bold text-slate-800 flex items-center">
                    <CheckCircle className="w-5 h-5 text-green-500 mr-2" />
                    Completed Orders
                </h3>
                <span className="bg-slate-200 text-slate-600 text-xs font-bold py-1 px-3 rounded-full">
                    {orders.filter(o => o.status === OrderStatus.COMPLETED).length} Total
                </span>
            </div>
            <table className="w-full text-left text-sm text-slate-600">
                <thead className="bg-slate-50 text-slate-400 uppercase text-xs font-bold tracking-wider">
                    <tr>
                        <th className="p-5">Order ID</th>
                        <th className="p-5">Items</th>
                        <th className="p-5">Total</th>
                        <th className="p-5">Status</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {orders.filter(o => o.status === OrderStatus.COMPLETED).map(order => (
                        <tr key={order.id} className="hover:bg-slate-50/80 transition-colors">
                            <td className="p-5 font-mono text-slate-500 font-bold">#{order.id}</td>
                            <td className="p-5">
                                <div className="space-y-1">
                                    {order.items.map((i, idx) => (
                                        <div key={idx} className="flex items-center text-xs">
                                            <span className="font-bold text-slate-700 mr-1">{i.quantity}x</span> {i.name}
                                        </div>
                                    ))}
                                </div>
                            </td>
                            <td className="p-5 font-bold text-slate-800">
                              ₹{order.totalAmount}
                              {order.discountAmount && order.discountAmount > 0 && (
                                <span className="text-[10px] text-green-600 block">Saved ₹{order.discountAmount}</span>
                              )}
                            </td>
                            <td className="p-5">
                                <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-green-100 text-green-800">
                                    Completed
                                </span>
                            </td>
                        </tr>
                    ))}
                    {orders.filter(o => o.status === OrderStatus.COMPLETED).length === 0 && (
                        <tr>
                            <td colSpan={4} className="p-12 text-center text-slate-400">No completed orders yet.</td>
                        </tr>
                    )}
                </tbody>
            </table>
          </div>
      )}

      {/* ... Menu Tab ... */}
      {activeTab === 'menu' && (
        <div className="bg-white border border-slate-200 rounded-3xl overflow-hidden shadow-sm animate-in fade-in">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                <h3 className="font-bold text-slate-800">Menu Items</h3>
                <button onClick={() => handleOpenMenuModal()} className="bg-slate-900 hover:bg-black text-white text-sm font-bold px-4 py-2 rounded-lg flex items-center shadow-lg shadow-slate-900/10">
                    <Plus className="w-4 h-4 mr-2" /> Add Item
                </button>
            </div>
            <table className="w-full text-left text-sm text-slate-600">
                <thead className="bg-slate-50 text-slate-400 uppercase text-xs font-bold tracking-wider">
                    <tr>
                        <th className="p-5">Name</th>
                        <th className="p-5">Category</th>
                        <th className="p-5">Rating</th>
                        <th className="p-5">Price</th>
                        <th className="p-5 text-right">Actions</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {menu.map(item => (
                        <tr key={item.id} className="hover:bg-slate-50/80 transition-colors">
                            <td className="p-5 font-bold text-slate-800 flex items-center">
                                <img src={item.image} className="w-10 h-10 rounded-lg object-cover mr-3 shadow-sm bg-slate-100" alt="" />
                                <div>
                                    <div className="flex items-center">
