                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {coupons.map(coupon => (
                        <tr key={coupon.id} className="hover:bg-slate-50/80 transition-colors">
                            <td className="p-5 font-bold text-slate-800">
                                <span className="bg-orange-100 text-orange-700 px-3 py-1 rounded-lg border border-orange-200 border-dashed tracking-wide font-mono">
                                  {coupon.code}
                                </span>
                            </td>
                            <td className="p-5">
                                <span className="text-xs font-bold text-slate-500">{coupon.type}</span>
                            </td>
                            <td className="p-5 font-bold text-slate-700">
                              {coupon.type === DiscountType.PERCENTAGE ? `${coupon.value}%` : `₹${coupon.value}`}
                            </td>
                            <td className="p-5">
                                <span className="px-2 py-1 rounded-md bg-slate-100 text-xs font-bold text-slate-600">
                                    {coupon.category}
                                </span>
                            </td>
                            <td className="p-5 text-slate-500 text-xs font-medium">{coupon.expiryDate}</td>
                            <td className="p-5 text-right">
                                <button 
                                    onClick={() => deleteCoupon(coupon.id)}
                                    className="text-red-400 hover:text-red-600 p-2 hover:bg-red-50 rounded-lg transition-colors"
                                >
                                    <Trash className="w-4 h-4" />
                                </button>
                            </td>
                        </tr>
                    ))}
                    {coupons.length === 0 && (
                        <tr>
                            <td colSpan={6} className="p-12 text-center text-slate-400">No active coupons.</td>
                        </tr>
                    )}
                </tbody>
            </table>
         </div>
      )}

      {/* ... Users Tab ... */}
      {activeTab === 'users' && (
          <div className="bg-white border border-slate-200 rounded-3xl p-12 text-center animate-in fade-in shadow-sm">
              <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4">
                 <Users className="w-8 h-8 text-slate-400" />
              </div>
              <h3 className="text-xl font-bold text-slate-800">User Management</h3>
              <p className="text-slate-500 mb-8">Manage customer and staff accounts.</p>
              <button className="bg-white text-slate-700 px-6 py-3 rounded-xl border border-slate-200 hover:bg-slate-50 font-bold shadow-sm">
                  View All Users (Simulated)
              </button>
          </div>
      )}

      {/* Menu Edit/Add Modal */}
      {isMenuModalOpen && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in">
              <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95">
                  <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                      <h3 className="font-bold text-lg text-slate-800">
                          {editingItem ? 'Edit Item' : 'Add New Item'}
                      </h3>
                      <button onClick={() => setIsMenuModalOpen(false)} className="text-slate-400 hover:text-slate-600 p-1 bg-slate-200/50 rounded-full">
                          <X className="w-5 h-5" />
                      </button>
                  </div>
                  <form onSubmit={handleMenuSubmit} className="p-6 space-y-4">
                      <div>
                          <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Item Name</label>
                          <input 
                            type="text" 
                            required
                            className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-medium focus:ring-2 focus:ring-blue-100 focus:border-blue-400 outline-none"
                            placeholder="e.g. Grilled Cheese"
                            value={menuForm.name}
                            onChange={e => setMenuForm({...menuForm, name: e.target.value})}
                          />
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Price (₹)</label>
                              <input 
                                type="number" 
                                required
                                min="0"
                                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-medium focus:ring-2 focus:ring-blue-100 focus:border-blue-400 outline-none"
                                placeholder="0"
                                value={menuForm.price}
