        <div>
           <h1 className="text-2xl font-bold text-slate-800">
               {new Date().getHours() < 12 ? 'Good Morning' : 'Good Afternoon'}, Admin! 👋
           </h1>
           <p className="text-slate-500 text-sm">Here is what's happening in your canteen today.</p>
        </div>

        {/* Large Scan Button for quick access */}
        <button 
            onClick={handleScanQR}
            className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-3 rounded-xl font-bold shadow-lg shadow-orange-500/20 flex items-center transition-all active:scale-95"
        >
            <Scan className="w-5 h-5 mr-2" />
            Scan Pickup QR
        </button>
      </div>

      {/* 2. Navigation Tabs */}
      <div className="flex flex-wrap gap-3 p-1">
        <NavTab id="overview" label="Overview" icon={LayoutDashboard} />
        <NavTab id="kitchen" label="Live Kitchen" icon={ChefHat} />
        <NavTab id="menu" label="Food Menu" icon={UtensilsCrossed} />
        <NavTab id="history" label="Past Orders" icon={History} />
        <NavTab id="coupons" label="Coupons" icon={Ticket} />
      </div>

      {/* 3. OVERVIEW TAB (Home) */}
      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in fade-in slide-in-from-bottom-4">

          {/* Main Status Cards */}
          <div className="lg:col-span-2 space-y-6">
             <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {/* Active Orders */}
                <div onClick={() => setActiveTab('kitchen')} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm cursor-pointer hover:border-orange-200 hover:shadow-md transition-all group">
                    <div className="flex justify-between items-start mb-4">
                        <div className="p-3 bg-orange-50 rounded-2xl group-hover:bg-orange-100 transition-colors">
                            <ChefHat className="w-6 h-6 text-orange-600" />
                        </div>
                        <span className="bg-green-100 text-green-700 text-xs font-bold px-2 py-1 rounded-full">Live</span>
                    </div>
                    <div className="text-4xl font-bold text-slate-800 mb-1">{analytics.activeOrders}</div>
                    <div className="text-slate-500 text-sm font-medium">Orders to Prepare</div>
                </div>

                {/* Sales */}
                <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
                    <div className="flex justify-between items-start mb-4">
                        <div className="p-3 bg-blue-50 rounded-2xl">
                            <DollarSign className="w-6 h-6 text-blue-600" />
                        </div>
                        <span className="flex items-center text-green-500 text-xs font-bold">
                            <TrendingUp className="w-3 h-3 mr-1" />
                            Good
