                                className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                title="Delete"
                              >
                                  <Trash2 className="w-5 h-5" />
                              </button>
                          </div>
                      </div>
                  ))}
              </div>
          </div>
      )}

      {/* 6. HISTORY TAB */}
      {activeTab === 'history' && (
          <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in">
              <div className="p-6 border-b border-slate-100">
                  <h3 className="font-bold text-slate-800 text-lg">Order History</h3>
                  <p className="text-slate-500 text-sm">List of all completed orders.</p>
              </div>
              <table className="w-full text-left text-sm">
                  <thead className="bg-slate-50 text-slate-500 font-bold uppercase text-xs">
                      <tr>
                          <th className="p-4">ID</th>
                          <th className="p-4">Items</th>
                          <th className="p-4">Total</th>
                          <th className="p-4">Date</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                      {orders.filter(o => o.status === OrderStatus.COMPLETED).map(order => (
                          <tr key={order.id} className="hover:bg-slate-50">
                              <td className="p-4 font-mono text-slate-600">#{order.id}</td>
                              <td className="p-4 text-slate-800 font-medium">
                                  {order.items.map(i => `${i.quantity}x ${i.name}`).join(', ')}
                              </td>
                              <td className="p-4 font-bold">₹{order.totalAmount}</td>
                              <td className="p-4 text-slate-500 text-xs">
                                  {new Date(order.createdAt).toLocaleDateString()}
                              </td>
                          </tr>
                      ))}
                      {orders.filter(o => o.status === OrderStatus.COMPLETED).length === 0 && (
                          <tr><td colSpan={4} className="p-8 text-center text-slate-400">No history available</td></tr>
                      )}
                  </tbody>
              </table>
          </div>
      )}

      {/* 7. COUPONS TAB */}
      {activeTab === 'coupons' && (
          <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in">
               <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                  <div>
                      <h3 className="font-bold text-slate-800 text-lg">Coupons</h3>
                      <p className="text-slate-500 text-sm">Active discounts for students.</p>
                  </div>
                  <button 
                    onClick={handleAddCoupon} 
                    className="bg-slate-900 hover:bg-black text-white px-4 py-2 rounded-xl font-bold text-sm flex items-center shadow-lg shadow-slate-900/10"
                  >
                      <Plus className="w-4 h-4 mr-2" /> New Coupon
                  </button>
              </div>
              <div className="p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {coupons.map(coupon => (
                      <div key={coupon.id} className="bg-orange-50 border border-orange-100 rounded-2xl p-5 relative overflow-hidden group">
                          <div className="absolute top-0 right-0 p-2 opacity-10 group-hover:opacity-20 transition-opacity">
                              <Ticket className="w-16 h-16 text-orange-500" />
                          </div>
                          <div className="relative z-10">
                              <p className="text-xs font-bold text-orange-400 uppercase tracking-wider mb-1">Coupon Code</p>
                              <p className="text-2xl font-mono font-bold text-slate-800 mb-4">{coupon.code}</p>
                              <div className="flex justify-between items-end">
                                  <div>
                                      <p className="text-sm font-bold text-slate-600">{coupon.value}% OFF</p>
                                      <p className="text-xs text-slate-400">Expires: {coupon.expiryDate}</p>
                                  </div>
                                  <button onClick={() => deleteCoupon(coupon.id)} className="text-red-400 hover:text-red-600 p-2 bg-white rounded-lg shadow-sm">
                                      <Trash2 className="w-4 h-4" />
                                  </button>
                              </div>
                          </div>
                      </div>
                  ))}
                  {coupons.length === 0 && (
                      <div className="col-span-full text-center py-10 text-slate-400">No active coupons.</div>
                  )}
              </div>
          </div>
      )}

      {/* MODAL: Menu Add/Edit (Simplified) */}
      {isMenuModalOpen && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in">
              <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95">
                  <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                      <h3 className="font-bold text-lg text-slate-800">
                          {editingItem ? 'Edit Dish' : 'Add New Dish'}
                      </h3>
                      <button onClick={() => setIsMenuModalOpen(false)} className="text-slate-400 hover:text-slate-600 p-1 bg-slate-200/50 rounded-full">
                          <X className="w-5 h-5" />
                      </button>
                  </div>
                  <form onSubmit={handleMenuSubmit} className="p-6 space-y-5">
                      <div>
                          <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Dish Name</label>
                          <input 
                            type="text" 
                            required
                            className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-medium focus:ring-2 focus:ring-blue-100 focus:border-blue-400 outline-none"
                            placeholder="e.g. Cheese Burger"
                            value={menuForm.name}
                            onChange={e => setMenuForm({...menuForm, name: e.target.value})}
                          />
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                          <div>
                              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Price (₹)</label>
                              <input 
                                type="number" 
                                required
                                min="0"
                                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-medium focus:ring-2 focus:ring-blue-100 focus:border-blue-400 outline-none"
                                placeholder="0"
                                value={menuForm.price}
                                onChange={e => setMenuForm({...menuForm, price: Number(e.target.value)})}
                              />
                          </div>
                          <div>
                              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Category</label>
                              <select 
                                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-medium focus:ring-2 focus:ring-blue-100 focus:border-blue-400 outline-none"
                                value={menuForm.category}
                                onChange={e => setMenuForm({...menuForm, category: e.target.value as any})}
                              >
                                  {Object.values(FoodCategory).map(c => (
                                      <option key={c} value={c}>{c}</option>
                                  ))}
                              </select>
                          </div>
                      </div>

                      <div>
                          <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Description (Optional)</label>
                          <textarea 
                            rows={2}
                            className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-medium focus:ring-2 focus:ring-blue-100 focus:border-blue-400 outline-none"
                            placeholder="Tasty and fresh..."
                            value={menuForm.description}
                            onChange={e => setMenuForm({...menuForm, description: e.target.value})}
                          />
                      </div>

                      <div>
                          <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Image Link (Optional)</label>
                          <div className="flex">
                             <span className="inline-flex items-center px-3 rounded-l-xl border border-r-0 border-slate-200 bg-slate-100 text-slate-500">
                                 <ImageIcon className="w-4 h-4" />
                             </span>
                             <input 
                                type="url" 
                                className="w-full bg-slate-50 border border-slate-200 rounded-r-xl px-4 py-3 text-sm font-medium focus:ring-2 focus:ring-blue-100 focus:border-blue-400 outline-none"
                                placeholder="https://..."
                                value={menuForm.image}
                                onChange={e => setMenuForm({...menuForm, image: e.target.value})}
                             />
                          </div>
                      </div>

                      <div className="flex items-center space-x-3 pt-2">
                          <button 
                            type="button"
                            onClick={() => setMenuForm({...menuForm, isVeg: !menuForm.isVeg})}
                            className={`relative inline-flex h-6 w-11 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none ${menuForm.isVeg ? 'bg-green-500' : 'bg-slate-200'}`}
                          >
                              <span className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out ${menuForm.isVeg ? 'translate-x-5' : 'translate-x-0'}`} />
                          </button>
                          <span className="text-sm font-bold text-slate-700">Vegetarian?</span>
                      </div>

                      <div className="pt-4 flex space-x-3">
                          <button 
                            type="button"
                            onClick={() => setIsMenuModalOpen(false)}
                            className="flex-1 py-3 rounded-xl font-bold text-slate-500 hover:bg-slate-100 transition-colors"
                          >
                              Cancel
                          </button>
                          <button 
                            type="submit"
                            className="flex-1 bg-slate-900 text-white py-3 rounded-xl font-bold shadow-lg shadow-slate-900/20 hover:bg-black transition-all flex items-center justify-center"
                          >
                              <Save className="w-4 h-4 mr-2" />
                              Save Item
                          </button>
                      </div>
                  </form>
              </div>
          </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useEffect, useState } from 'react';
import { db } from '../../services/supabaseService';
import { MenuItem, Order, OrderStatus, User, UserRole, FoodCategory, Coupon, DiscountType } from '../../types';
import { AreaChart, Area, PieChart, Pie, Cell, Legend, ResponsiveContainer, XAxis, YAxis, CartesianGrid, Tooltip } from 'recharts';
import { 
  LayoutDashboard, 
  UtensilsCrossed, 
  ChefHat, 
  History, 
  Ticket, 
  Plus, 
  Scan, 
  DollarSign, 
  TrendingUp, 
  Zap, 
  ThumbsDown, 
  Edit, 
  Trash2, 
  Clock, 
  CheckCircle, 
  X, 
  Image as ImageIcon, 
  Save,
  Search,
  Filter,
  ArrowRight,
  Star
} from 'lucide-react';

interface AdminDashboardProps {
  user: User;
}

const COLORS = ['#f97316', '#ef4444', '#3b82f6', '#10b981'];

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'kitchen' | 'menu' | 'history' | 'coupons'>('overview');

  // Analytics State
  const [analytics, setAnalytics] = useState({
      todayRevenue: 0, yesterdayRevenue: 0, todayOrders: 0, yesterdayOrders: 0,
      revenueData: [] as any[], categoryData: [] as any[], popularItem: { name: 'Loading', count: 0 }, peakTime: '--',
      kitchenLoad: 'Low', activeOrders: 0,
      lowestRated: [] as MenuItem[], mostReviewed: [] as MenuItem[]
  });

  const [orders, setOrders] = useState<Order[]>([]);
  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [coupons, setCoupons] = useState<Coupon[]>([]);
  const [now, setNow] = useState(Date.now());

  // Menu Modal State
  const [isMenuModalOpen, setIsMenuModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [menuForm, setMenuForm] = useState<Partial<MenuItem>>({
      name: '', price: 0, category: FoodCategory.LUNCH, description: '', image: '', isVeg: true
  });

  useEffect(() => {
    const updateData = async () => {
      const stats = await db.getAnalytics();
      setAnalytics(stats);

      const menuData = await db.getMenu();
      setMenu(menuData);

      setCoupons(db.getCoupons()); 

      let allOrders = await db.getOrders();
      if (user.role === UserRole.SPECIALIZED_ADMIN && user.specialty) {
        allOrders = allOrders.filter(o => o.items.some(i => i.category === user.specialty));
      }
      setOrders(allOrders);
    };

    updateData();
    db.addEventListener('change', updateData);

    // Timer for live updates
    const interval = setInterval(() => setNow(Date.now()), 1000);

    return () => {
      db.removeEventListener('change', updateData);
      clearInterval(interval);
    };
  }, [user]);

  const updateStatus = async (id: string, status: OrderStatus) => {
    await db.updateOrderStatus(id, status);
  };

  const deleteMenuItem = async (id: string) => {
    if (confirm('Are you sure you want to remove this item from the menu?')) {
        await db.deleteMenuItem(id);
    }
  };

  const deleteCoupon = (id: string) => {
    if (confirm('Stop this coupon?')) {
        db.deleteCoupon(id);
    }
  };

  const handleOpenMenuModal = (item?: MenuItem) => {
      if (item) {
          setEditingItem(item);
          setMenuForm({ ...item });
      } else {
          setEditingItem(null);
          setMenuForm({
            name: '', 
            price: 100, 
            category: FoodCategory.LUNCH, 
            description: '', 
            image: 'https://picsum.photos/400/300', 
            isVeg: true
          });
      }
      setIsMenuModalOpen(true);
  };

  const handleMenuSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!menuForm.name || !menuForm.price) return;

      try {
          if (editingItem) {
              await db.updateMenuItem(editingItem.id, menuForm);
          } else {
              await db.addMenuItem(menuForm as any);
          }
          setIsMenuModalOpen(false);
      } catch (err) {
          alert('Failed to save item');
      }
  };

  const handleAddCoupon = () => {
    const code = prompt("Enter Code (e.g. SAVE20):");
    if(!code) return;
    const value = Number(prompt("Discount Percentage (e.g. 20):"));
    if(isNaN(value)) return;

    db.addCoupon({ 
        code: code.toUpperCase(), 
        type: DiscountType.PERCENTAGE, 
        value, 
        category: 'ALL', 
        expiryDate: '2025-12-31' 
    });
  };

  const handleScanQR = () => {
      const orderId = prompt("📷 SIMULATED QR SCANNER\n\nEnter Order ID from Customer's phone:");
      if (!orderId) return;
      const order = orders.find(o => o.id === orderId.trim());

      if (!order) { alert("❌ Order not found."); return; }
      if (order.status === OrderStatus.COMPLETED) { alert("⚠️ Order already picked up."); return; }
      if (order.status !== OrderStatus.READY) { alert(`⚠️ Order is not ready yet (${order.status}).`); return; }

      if (confirm(`✅ CONFIRMED!\n\nOrder #${order.id}\nItems: ${order.items.length}\n\nHand over food?`)) {
          updateStatus(order.id, OrderStatus.COMPLETED);
      }
  };

  const getTimerDisplay = (order: Order) => {
    if (order.status !== OrderStatus.PREPARING || !order.targetTime) return null;
    const remainingMs = order.targetTime - now;
    if (remainingMs <= 0) return <span className="text-red-500 font-bold text-xs">Overdue</span>;

    const minutes = Math.floor(remainingMs / 60000);
    const seconds = Math.floor((remainingMs % 60000) / 1000);
    return (
        <span className={`text-xs font-mono font-bold px-2 py-1 rounded ${remainingMs < 60000 ? 'bg-red-100 text-red-600 animate-pulse' : 'bg-slate-100 text-slate-700'}`}>
            {minutes}:{seconds.toString().padStart(2, '0')}
        </span>
    );
  };

  // --- Simplified Navigation Component ---
  const NavTab = ({ id, label, icon: Icon }: any) => (
    <button
      onClick={() => setActiveTab(id)}
      className={`flex items-center space-x-2 px-5 py-3 rounded-xl transition-all font-bold text-sm ${
        activeTab === id 
        ? 'bg-slate-900 text-white shadow-lg shadow-slate-900/10 scale-105' 
        : 'bg-white text-slate-500 hover:bg-slate-50 border border-transparent hover:border-slate-200'
      }`}
    >
      <Icon className={`w-4 h-4 ${activeTab === id ? 'text-orange-400' : ''}`} />
      <span>{label}</span>
    </button>
  );

  return (
    <div className="space-y-8 max-w-7xl mx-auto pb-20">
      {/* 1. Header Area */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
           <h1 className="text-2xl font-bold text-slate-800">
               {new Date().getHours() < 12 ? 'Good Morning' : 'Good Afternoon'}, Admin! 👋
           </h1>
           <p className="text-slate-500 text-sm">Here is what's happening in your canteen today.</p>
        </div>

        {/* Large Scan Button for quick access */}
        <button 
            onClick={handleScanQR}
            className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-3 rounded-xl font-bold shadow-lg shadow-orange-500/20 flex items-center transition-all active:scale-95"
        >
            <Scan className="w-5 h-5 mr-2" />
            Scan Pickup QR
        </button>
      </div>

      {/* 2. Navigation Tabs */}
      <div className="flex flex-wrap gap-3 p-1">
        <NavTab id="overview" label="Overview" icon={LayoutDashboard} />
        <NavTab id="kitchen" label="Live Kitchen" icon={ChefHat} />
        <NavTab id="menu" label="Food Menu" icon={UtensilsCrossed} />
        <NavTab id="history" label="Past Orders" icon={History} />
        <NavTab id="coupons" label="Coupons" icon={Ticket} />
      </div>

      {/* 3. OVERVIEW TAB (Home) */}
      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in fade-in slide-in-from-bottom-4">

          {/* Main Status Cards */}
          <div className="lg:col-span-2 space-y-6">
             <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {/* Active Orders */}
                <div onClick={() => setActiveTab('kitchen')} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm cursor-pointer hover:border-orange-200 hover:shadow-md transition-all group">
                    <div className="flex justify-between items-start mb-4">
                        <div className="p-3 bg-orange-50 rounded-2xl group-hover:bg-orange-100 transition-colors">
                            <ChefHat className="w-6 h-6 text-orange-600" />
                        </div>
                        <span className="bg-green-100 text-green-700 text-xs font-bold px-2 py-1 rounded-full">Live</span>
                    </div>
                    <div className="text-4xl font-bold text-slate-800 mb-1">{analytics.activeOrders}</div>
                    <div className="text-slate-500 text-sm font-medium">Orders to Prepare</div>
                </div>

                {/* Sales */}
                <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
                    <div className="flex justify-between items-start mb-4">
                        <div className="p-3 bg-blue-50 rounded-2xl">
                            <DollarSign className="w-6 h-6 text-blue-600" />
                        </div>
                        <span className="flex items-center text-green-500 text-xs font-bold">
                            <TrendingUp className="w-3 h-3 mr-1" />
                            Good
                        </span>
                    </div>
                    <div className="text-4xl font-bold text-slate-800 mb-1">₹{analytics.todayRevenue}</div>
                    <div className="text-slate-500 text-sm font-medium">Total Sales Today</div>
                </div>

                {/* Kitchen Load */}
                <div className={`p-6 rounded-3xl border shadow-sm transition-colors ${analytics.kitchenLoad === 'High' ? 'bg-red-50 border-red-100' : 'bg-white border-slate-100'}`}>
                    <div className="flex justify-between items-start mb-4">
                        <div className={`p-3 rounded-2xl ${analytics.kitchenLoad === 'High' ? 'bg-red-200' : 'bg-slate-100'}`}>
                            <Zap className={`w-6 h-6 ${analytics.kitchenLoad === 'High' ? 'text-red-700' : 'text-slate-500'}`} />
                        </div>
                    </div>
                    <div className={`text-4xl font-bold mb-1 ${analytics.kitchenLoad === 'High' ? 'text-red-800' : 'text-slate-800'}`}>{analytics.kitchenLoad}</div>
                    <div className={`text-sm font-medium ${analytics.kitchenLoad === 'High' ? 'text-red-600' : 'text-slate-500'}`}>Kitchen Pressure</div>
                </div>
             </div>

             {/* Quick Actions Panel */}
             <div className="bg-gradient-to-r from-slate-900 to-slate-800 rounded-3xl p-8 text-white relative overflow-hidden shadow-xl">
                 <div className="relative z-10">
                     <h2 className="text-2xl font-bold mb-2">Quick Actions</h2>
                     <p className="text-slate-400 mb-6 text-sm">Common tasks you can do right now.</p>

                     <div className="flex flex-wrap gap-4">
                         <button 
                            onClick={() => handleOpenMenuModal()}
                            className="bg-white text-slate-900 px-5 py-3 rounded-xl font-bold text-sm hover:bg-slate-100 transition-colors flex items-center"
                         >
                             <Plus className="w-4 h-4 mr-2" /> Add New Dish
                         </button>
                         <button 
                            onClick={handleAddCoupon}
                            className="bg-white/10 text-white border border-white/20 px-5 py-3 rounded-xl font-bold text-sm hover:bg-white/20 transition-colors flex items-center"
                         >
                             <Ticket className="w-4 h-4 mr-2" /> Create Coupon
                         </button>
                     </div>
                 </div>
                 {/* Decorative background element */}
                 <ChefHat className="absolute -bottom-6 -right-6 w-48 h-48 text-white/5 rotate-12" />
             </div>

             {/* Alerts / Insights */}
             {analytics.lowestRated.length > 0 && (
                 <div className="bg-red-50 border border-red-100 rounded-3xl p-6">
                     <div className="flex items-center space-x-2 mb-4">
                         <ThumbsDown className="w-5 h-5 text-red-500" />
                         <h3 className="font-bold text-red-800">Attention Needed</h3>
                     </div>
                     <p className="text-sm text-red-700 mb-3">These items have low ratings recently:</p>
                     <div className="space-y-2">
                         {analytics.lowestRated.map(item => (
                             <div key={item.id} className="bg-white p-3 rounded-xl border border-red-100 flex justify-between items-center">
                                 <span className="text-sm font-bold text-slate-700">{item.name}</span>
                                 <span className="text-xs font-bold text-red-500 bg-red-50 px-2 py-1 rounded">{item.averageRating?.toFixed(1)} ★</span>
                             </div>
                         ))}
                     </div>
                 </div>
             )}
          </div>

          {/* Side Panel: Recent Revenue Graph */}
          <div className="bg-white border border-slate-100 rounded-3xl p-6 shadow-sm flex flex-col">
              <h3 className="font-bold text-slate-800 mb-6">Weekly Revenue</h3>
              <div className="flex-1 min-h-[200px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={analytics.revenueData}>
                      <defs>
                        <linearGradient id="colorRev" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="5%" stopColor="#f97316" stopOpacity={0.2}/>
                          <stop offset="95%" stopColor="#f97316" stopOpacity={0}/>
                        </linearGradient>
                      </defs>
                      <CartesianGrid vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                      <Tooltip 
                         contentStyle={{ backgroundColor: '#1e293b', border: 'none', borderRadius: '8px', color: '#fff', fontSize: '12px' }}
                         itemStyle={{ color: '#fff' }}
                         formatter={(value: any) => [`₹${value}`, ''] as [string, string]}
                      />
                      <Area type="monotone" dataKey="revenue" stroke="#f97316" strokeWidth={3} fillOpacity={1} fill="url(#colorRev)" />
                    </AreaChart>
                  </ResponsiveContainer>
              </div>
