}

const COLORS = ['#f97316', '#ef4444', '#3b82f6', '#10b981', '#94a3b8'];

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'kitchen' | 'menu' | 'history' | 'coupons'>('overview');

  // Analytics State
  const [analytics, setAnalytics] = useState({
      todayRevenue: 0, yesterdayRevenue: 0, todayOrders: 0, yesterdayOrders: 0,
      revenueData: [] as any[], categoryData: [] as any[], popularItem: { name: 'N/A', count: 0 }, peakTime: '--',
      kitchenLoad: 'Low', activeOrders: 0,
      lowestRated: [] as MenuItem[], mostReviewed: [] as MenuItem[]
  });

  const [orders, setOrders] = useState<Order[]>([]);
  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [coupons, setCoupons] = useState<Coupon[]>([]);
  const [now, setNow] = useState(Date.now());

  // Menu Modal State
  const [isMenuModalOpen, setIsMenuModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [menuForm, setMenuForm] = useState<Partial<MenuItem>>({
      name: '', price: 0, category: FoodCategory.LUNCH, description: '', image: '', isVeg: true
  });

  useEffect(() => {
    const updateData = async () => {
      const stats = await db.getAnalytics();
      setAnalytics(stats);

      const menuData = await db.getMenu();
      setMenu(menuData);

      setCoupons(db.getCoupons()); 

      let allOrders = await db.getOrders();
      if (user.role === UserRole.SPECIALIZED_ADMIN && user.specialty) {
        allOrders = allOrders.filter(o => o.items.some(i => i.category === user.specialty));
      }
      setOrders(allOrders);
    };

    updateData();
    db.addEventListener('change', updateData);

    // Timer for live updates
    const interval = setInterval(() => setNow(Date.now()), 1000);

    return () => {
      db.removeEventListener('change', updateData);
      clearInterval(interval);
    };
  }, [user]);

  const updateStatus = async (id: string, status: OrderStatus) => {
    await db.updateOrderStatus(id, status);
  };

  const deleteMenuItem = async (id: string) => {
    if (confirm('Are you sure you want to remove this item from the menu?')) {
        await db.deleteMenuItem(id);
    }
  };

  const deleteCoupon = (id: string) => {
    if (confirm('Stop this coupon?')) {
        db.deleteCoupon(id);
    }
  };

  const handleOpenMenuModal = (item?: MenuItem) => {
      if (item) {
          setEditingItem(item);
          setMenuForm({ ...item });
      } else {
          setEditingItem(null);
          setMenuForm({
            name: '', 
            price: 100, 
            category: FoodCategory.LUNCH, 
            description: '', 
            image: 'https://picsum.photos/400/300', 
            isVeg: true
          });
      }
      setIsMenuModalOpen(true);
  };

  const handleMenuSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!menuForm.name || !menuForm.price) return;

      try {
          if (editingItem) {
              await db.updateMenuItem(editingItem.id, menuForm);
          } else {
              await db.addMenuItem(menuForm as any);
          }
          setIsMenuModalOpen(false);
      } catch (err) {
          alert('Failed to save item');
      }
