import React, { useState } from 'react';
import { db } from '../services/supabaseService';
import { User, UserRole } from '../types';
import { Heart, ArrowRight, AlertTriangle, UserPlus, LogIn, Lock, Mail, User as UserIcon, Zap } from 'lucide-react';

interface AuthPageProps {
  onLogin: (user: User) => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // Form State
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (!email || !password || (!isLogin && !name)) {
        setError('Please fill in all fields.');
        setLoading(false);
        return;
    }

    try {
      let user;
      if (isLogin) {
          user = await db.login(email, password);
      } else {
          // FORCE ROLE TO CUSTOMER
          user = await db.register({ name, email, password, role: UserRole.CUSTOMER });
      }
      onLogin(user);
    } catch (err: any) {
      setError(err.message || 'Authentication failed');
    } finally {
      setLoading(false);
    }
  };

  const toggleMode = () => {
      setIsLogin(!isLogin);
      setError('');
      setPassword('');
      if (!isLogin) {
          setName('');
      }
  };

  const handleQuickLogin = async (role: 'admin' | 'student') => {
      setLoading(true);
      setError('');
      try {
          let user;
          if (role === 'admin') {
              user = await db.login('admin@quickbite.com', 'admin');
          } else {
              user = await db.login('student@demo.com', 'student');
          }
          onLogin(user);
      } catch (err: any) {
          setError('Demo account not found. Please refresh to re-seed data.');
      } finally {
          setLoading(false);
      }
  };

  return (
    <div className="min-h-[80vh] flex flex-col items-center justify-center p-4">
      <div className="w-full max-w-md bg-white p-8 md:p-10 rounded-3xl shadow-2xl shadow-pink-100 relative overflow-hidden border border-slate-100 transition-all duration-300">

        {/* Header */}
        <div className="relative z-10 text-center mb-8">
          <div className="mx-auto bg-gradient-to-tr from-pink-500 to-orange-500 w-16 h-16 rounded-full flex items-center justify-center mb-4 shadow-lg shadow-orange-500/20 animate-in zoom-in duration-300">
            <Heart className="w-8 h-8 text-white fill-current" />
          </div>
          <h1 className="text-3xl font-bold text-slate-900 mb-2 tracking-tight">
              {isLogin ? 'Welcome Back' : 'Create Account'}
          </h1>
          <p className="text-slate-400 text-sm">
              {isLogin ? 'Sign in to access your canteen' : 'Join Quick Bite today'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4 relative z-10">

            {/* Name Field (Signup Only) */}
            {!isLogin && (
                <div className="relative animate-in slide-in-from-left-5 fade-in duration-300">
                    <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                    <input 
                        type="text" 
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-12 pr-4 py-3.5 text-slate-800 focus:ring-2 focus:ring-orange-200 focus:border-orange-400 outline-none transition-all font-medium text-sm"
                        placeholder="Full Name"
                    />
                </div>
            )}

            {/* Email Field */}
            <div className="relative">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                <input 
                    type="email" 
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-12 pr-4 py-3.5 text-slate-800 focus:ring-2 focus:ring-orange-200 focus:border-orange-400 outline-none transition-all font-medium text-sm"
                    placeholder="Email Address"
                />
            </div>

            {/* Password Field */}
            <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                <input 
                    type="password" 
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-12 pr-4 py-3.5 text-slate-800 focus:ring-2 focus:ring-orange-200 focus:border-orange-400 outline-none transition-all font-medium text-sm"
                    placeholder="Password"
                />
            </div>

            {/* Error Message */}
            {error && (
                <div className="flex items-center text-red-500 text-xs font-bold bg-red-50 p-3 rounded-xl animate-in shake">
                    <AlertTriangle className="w-4 h-4 mr-2 flex-shrink-0" />
                    {error}
                </div>
            )}

            {/* Submit Button */}
            <button 
                type="submit" 
                disabled={loading}
                className="w-full bg-slate-900 text-white py-4 rounded-xl font-bold shadow-xl shadow-slate-900/20 hover:bg-black hover:scale-[1.02] active:scale-[0.98] transition-all flex items-center justify-center mt-4"
            >
                {loading ? (
                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                ) : (
                    <>
                        {isLogin ? 'Sign In' : 'Create Account'}
                        <ArrowRight className="w-4 h-4 ml-2" />
                    </>
                )}
            </button>
        </form>

        {/* Toggle Mode */}
        <div className="relative z-10 text-center mt-6">
            <button 
                onClick={toggleMode}
                className="text-slate-500 hover:text-orange-500 text-sm font-medium transition-colors"
            >
                {isLogin ? (
                    <>New here? <span className="text-orange-600 font-bold underline decoration-orange-200 underline-offset-2">Create an account</span></>
                ) : (
                    <>Already have an account? <span className="text-orange-600 font-bold underline decoration-orange-200 underline-offset-2">Sign in</span></>
                )}
            </button>
        </div>

        {/* Quick Demo Access */}
        <div className="mt-8 border-t border-slate-100 pt-6 relative z-10">
          <p className="text-[10px] text-center text-slate-400 mb-3 font-bold uppercase tracking-wider flex items-center justify-center">
            <Zap className="w-3 h-3 mr-1 text-orange-400" /> Quick Demo Login
          </p>
          <div className="grid grid-cols-2 gap-3">
            <button 
                onClick={() => handleQuickLogin('student')}
                disabled={loading}
                className="bg-orange-50 hover:bg-orange-100 text-orange-700 py-2.5 rounded-xl text-xs font-bold transition-colors border border-orange-100"
            >
                Student Demo
            </button>
            <button 
                onClick={() => handleQuickLogin('admin')}
                disabled={loading}
                className="bg-slate-100 hover:bg-slate-200 text-slate-700 py-2.5 rounded-xl text-xs font-bold transition-colors border border-slate-200"
            >
                Admin Demo
            </button>
          </div>
        </div>

        {/* Decorative Blobs */}
        <div className="absolute -top-20 -right-20 w-64 h-64 bg-orange-100 rounded-full blur-3xl opacity-50 pointer-events-none"></div>
        <div className="absolute -bottom-20 -left-20 w-64 h-64 bg-pink-100 rounded-full blur-3xl opacity-50 pointer-events-none"></div>
      </div>

      <div className="mt-8 text-center">
          <p className="text-slate-400 text-xs">© 2025 Quick Bite. Smart Canteen System.</p>
      </div>
    </div>
  );
};

export default AuthPage;

import React, { useState, useEffect } from 'react';
import { db } from '../../services/supabaseService';
import { MenuItem, FoodCategory, CartItem } from '../../types';
import { Plus, Star, Clock, X, Heart, Sparkles, Smile, Frown, Coffee, Flame } from 'lucide-react';
import { getMealSuggestion } from '../../services/geminiService';

const MoodEmoji = ({ mood, icon, onClick, active }: any) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center p-4 rounded-2xl transition-all duration-300 transform hover:scale-105 ${
      active ? 'bg-orange-100 scale-110 shadow-inner' : 'hover:bg-slate-50'
    }`}
  >
    <div className={`text-4xl mb-2 transition-transform ${active ? 'scale-125' : ''}`}>{icon}</div>
    <span className={`text-xs font-medium ${active ? 'text-orange-600' : 'text-slate-500'}`}>{mood}</span>
  </button>
);

const MenuPage: React.FC = () => {
  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCategory, setSelectedCategory] = useState<FoodCategory | 'All'>('All');
  const [showMoodModal, setShowMoodModal] = useState(true);
  const [selectedMood, setSelectedMood] = useState<string | null>(null);
  const [suggestion, setSuggestion] = useState<{name: string, reason: string} | null>(null);
  const [aiLoading, setAiLoading] = useState(false);

  useEffect(() => {
    const fetchMenu = async () => {
        const data = await db.getMenu();
        setMenu(data);
        setLoading(false);
    };
    fetchMenu();
    // Re-fetch when ratings change
    db.addEventListener('change', fetchMenu);
    return () => db.removeEventListener('change', fetchMenu);
  }, []);

  const addToCart = (item: MenuItem) => {
    const cart: CartItem[] = JSON.parse(localStorage.getItem('qb_cart') || '[]');
    const existing = cart.find(i => i.id === item.id);
    if (existing) {
      existing.quantity += 1;
    } else {
      cart.push({ ...item, quantity: 1 });
    }
    localStorage.setItem('qb_cart', JSON.stringify(cart));
    window.dispatchEvent(new Event('cart-updated'));

    const toast = document.createElement('div');
    toast.className = 'fixed bottom-24 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-6 py-3 rounded-full shadow-2xl text-sm font-medium z-50 flex items-center space-x-2 animate-in fade-in slide-in-from-bottom-5';
    toast.innerHTML = `<svg class="w-4 h-4 text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"></path></svg><span>Added ${item.name}</span>`;
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 2000);
  };

  const handleMoodSubmit = async () => {
    if (!selectedMood) return;
    setAiLoading(true);

    try {
      const user = db.getCurrentUser();
      const pastOrders = user ? await db.getOrdersForUser(user.id) : [];

      const prompt = `I am feeling ${selectedMood}. Suggest a comfort food from the menu that matches this mood perfectly.`;
      const result = await getMealSuggestion(prompt, menu, pastOrders);

      if (result.suggestedItemName) {
        setSuggestion({
          name: result.suggestedItemName,
          reason: result.reason
        });
      }
    } catch (e) {
      console.error(e);
    } finally {
      setAiLoading(false);
    }
  };

  const filteredMenu = selectedCategory === 'All' 
    ? menu 
    : menu.filter(m => m.category === selectedCategory);

  if (loading) return <div className="p-8 text-center text-slate-400">Loading Menu...</div>;

  return (
    <div className="pb-20">
      {/* Mood Modal */}
      {showMoodModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-3xl shadow-2xl overflow-hidden relative animate-in zoom-in-95 duration-300">
            <button 
              onClick={() => setShowMoodModal(false)}
              className="absolute top-4 right-4 text-slate-400 hover:text-slate-600 p-1 bg-slate-100 rounded-full"
            >
              <X className="w-5 h-5" />
            </button>

            {!suggestion ? (
              <div className="p-8 text-center">
                <div className="mb-6">
                  <h2 className="text-2xl font-bold text-slate-800 mb-2">How are you feeling?</h2>
                  <p className="text-slate-500 text-sm">Pick one. Chef Byte will handle the rest! ✨</p>
                </div>

                <div className="grid grid-cols-2 gap-4 mb-8">
                  <MoodEmoji mood="Happy" icon="😄" active={selectedMood === 'Happy'} onClick={() => setSelectedMood('Happy')} />
                  <MoodEmoji mood="Cozy" icon="🧸" active={selectedMood === 'Cozy'} onClick={() => setSelectedMood('Cozy')} />
                  <MoodEmoji mood="Stressed" icon="😫" active={selectedMood === 'Stressed'} onClick={() => setSelectedMood('Stressed')} />
                  <MoodEmoji mood="Hungry" icon="🤤" active={selectedMood === 'Hungry'} onClick={() => setSelectedMood('Hungry')} />
                </div>

                <button
                  onClick={handleMoodSubmit}
                  disabled={!selectedMood || aiLoading}
                  className="w-full bg-orange-500 hover:bg-orange-600 disabled:opacity-50 text-white font-bold py-4 rounded-xl shadow-lg shadow-orange-500/30 transition-all flex items-center justify-center"
                >
                  {aiLoading ? (
                    <span className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
                  ) : (
                    'Secure Mood'
                  )}
                </button>
                <button 
                  onClick={() => setShowMoodModal(false)}
                  className="mt-4 text-sm text-slate-400 font-medium hover:text-slate-600"
                >
                  Maybe Later
                </button>
              </div>
            ) : (
              <div className="p-8 text-center bg-orange-50/50">
                 <div className="w-20 h-20 bg-white rounded-full mx-auto flex items-center justify-center shadow-md mb-4 text-4xl border-2 border-orange-100 animate-bounce">
                    👨‍🍳
                 </div>
                 <h3 className="text-lg font-bold text-slate-800 mb-2">Chef Byte Suggests:</h3>
                 <div className="bg-white p-5 rounded-2xl shadow-sm border border-orange-100 mb-6">
                    <h4 className="font-bold text-orange-600 text-xl mb-2">{suggestion.name}</h4>
                    <p className="text-slate-600 text-sm italic leading-relaxed">"{suggestion.reason}"</p>
                 </div>
                 <button
                    onClick={() => {
                        const item = menu.find(m => m.name === suggestion!.name);
                        if (item) addToCart(item);
                        setShowMoodModal(false);
                    }}
                    className="w-full bg-slate-900 text-white font-bold py-3 rounded-xl shadow-lg hover:bg-black transition-colors"
                 >
                    Order Now
                 </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Hero Banner */}
      <div className="mb-10 relative overflow-hidden rounded-3xl bg-gradient-to-r from-pink-500 via-red-400 to-orange-500 shadow-xl shadow-pink-500/20 text-white p-8 md:p-12">
        <div className="relative z-10 max-w-xl">
          <span className="inline-block px-3 py-1 bg-white/20 backdrop-blur-md rounded-full text-xs font-bold uppercase tracking-wider mb-4 border border-white/30">
            Welcome to Quick Bite
          </span>
          <h1 className="text-3xl md:text-5xl font-bold mb-4 leading-tight">
            Let's find your <br/><span className="text-yellow-200">comfort food!</span>
          </h1>
          <button 
            onClick={() => {
              setSuggestion(null);
              setSelectedMood(null);
              setShowMoodModal(true);
            }}
            className="bg-white text-pink-600 px-6 py-3 rounded-full font-bold shadow-lg hover:bg-slate-50 transition-colors flex items-center space-x-2"
          >
            <Sparkles className="w-4 h-4" />
            <span>Try AI Mood Picker</span>
          </button>
        </div>

        {/* Decorative Food Plate */}
        <div className="absolute top-1/2 right-0 transform -translate-y-1/2 hidden md:block w-96 h-96 translate-x-16 pointer-events-none">
             <div className="relative w-full h-full">
                {/* Glow Effect */}
                <div className="absolute inset-4 bg-orange-400 rounded-full blur-3xl opacity-40 animate-pulse"></div>
                {/* Plate Image */}
                <img 
                    src="https://images.unsplash.com/photo-1565299624946-b28f40a0ae38?auto=format&fit=crop&w=600&q=80" 
                    alt="Delicious Food"
                    className="w-full h-full object-cover rounded-full border-8 border-white/10 shadow-2xl rotate-12"
                />
                {/* Badge */}
                <div className="absolute top-10 left-0 bg-white text-orange-600 px-4 py-2 rounded-full shadow-xl text-xs font-bold animate-bounce border border-orange-100 flex items-center gap-1">
                    <Flame className="w-3 h-3 text-red-500 fill-current" />
                    Hot & Fresh
                </div>
             </div>
        </div>
      </div>

      {/* Categories */}
      <div className="mb-10">
        <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-bold text-slate-800">Comfort Zone</h2>
            {selectedCategory !== 'All' && (
                <button 
                    onClick={() => setSelectedCategory('All')} 
                    className="text-sm text-orange-500 font-medium hover:text-orange-600"
                >
                    View All
                </button>
            )}
        </div>

        <div className="flex space-x-6 overflow-x-auto pb-6 no-scrollbar snap-x">
          <button
            onClick={() => setSelectedCategory('All')}
            className={`flex flex-col items-center space-y-2 min-w-[80px] snap-start group ${selectedCategory === 'All' ? 'opacity-100' : 'opacity-60 hover:opacity-100'}`}
          >
             <div className={`w-16 h-16 rounded-full flex items-center justify-center text-2xl shadow-sm transition-all ${selectedCategory === 'All' ? 'bg-orange-500 text-white ring-4 ring-orange-100' : 'bg-white text-slate-700 group-hover:bg-slate-50'}`}>
                🍽️
             </div>
             <span className="text-xs font-semibold text-slate-600">All</span>
          </button>

          {Object.values(FoodCategory).map(cat => {
            let icon = '';
            switch(cat) {
                case FoodCategory.BREAKFAST: icon = '🥞'; break;
                case FoodCategory.LUNCH: icon = '🍛'; break;
                case FoodCategory.SNACKS: icon = '🍟'; break;
                case FoodCategory.DRINKS: icon = '🥤'; break;
