                    className={`flex flex-col items-center space-y-2 min-w-[80px] snap-start group ${selectedCategory === cat ? 'opacity-100' : 'opacity-70 hover:opacity-100'}`}
                >
                    <div className={`w-16 h-16 rounded-full flex items-center justify-center text-2xl shadow-sm transition-all ${
                        selectedCategory === cat ? 'bg-orange-500 text-white ring-4 ring-orange-100' : 'bg-white group-hover:bg-slate-50'
                    }`}>
                        {icon}
                    </div>
                    <span className="text-xs font-semibold text-slate-600">{cat}</span>
                </button>
            );
          })}
        </div>
      </div>

      {/* Recommended Items */}
      <div>
        <h2 className="text-xl font-bold text-slate-800 mb-6">Recommended for you</h2>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredMenu.map(item => (
