import { useNotificationSystem, ToastContainer, NotificationBell } from './components/NotificationSystem';
import { ShoppingBag, LogOut, Coffee, Heart } from 'lucide-react';

const Navbar: React.FC<{ 
    user: User | null; 
    onLogout: () => void;
    notifications: AppNotification[];
    onMarkRead: () => void;
}> = ({ user, onLogout, notifications, onMarkRead }) => {
  const location = useLocation();
  const isCustomer = user?.role === UserRole.CUSTOMER;
  const isAdmin = user?.role === UserRole.ADMIN || user?.role === UserRole.SPECIALIZED_ADMIN;
  const [cartCount, setCartCount] = useState(0);

  useEffect(() => {
    const updateCount = () => {
      const cart = JSON.parse(localStorage.getItem('qb_cart') || '[]');
      setCartCount(cart.reduce((acc: number, item: any) => acc + item.quantity, 0));
    };
    updateCount();
    window.addEventListener('storage', updateCount);
    // Custom event listener for immediate updates
    window.addEventListener('cart-updated', updateCount);
    return () => {
      window.removeEventListener('storage', updateCount);
      window.removeEventListener('cart-updated', updateCount);
    };
  }, []);

  if (!user) return null;

  return (
    <nav className="sticky top-0 z-50 bg-slate-900/80 backdrop-blur-md border-b border-slate-800 shadow-sm">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          <div className="flex items-center">
            <div className="relative">
              <h1 className="text-2xl font-bold bg-gradient-to-r from-pink-500 to-orange-500 bg-clip-text text-transparent tracking-tight">
                Quick<span className="font-script text-slate-200">Bite</span>
              </h1>
              <Heart className="w-3 h-3 text-pink-500 absolute -top-1 -right-2 fill-current animate-pulse" />
            </div>
          </div>

          <div className="flex items-center space-x-4 md:space-x-6">
            {isCustomer && (
              <>
                <div className="hidden md:flex space-x-6">
                  <NavLink to="/menu" active={location.pathname === '/menu'}>Comfort Zone</NavLink>
                  <NavLink to="/orders" active={location.pathname === '/orders'}>My Orders</NavLink>
                </div>
                <div className="relative">
                  <NavLink to="/cart" active={location.pathname === '/cart'}>
                    <ShoppingBag className={`w-6 h-6 ${location.pathname === '/cart' ? 'text-orange-500' : 'text-slate-400'}`} />
                  </NavLink>
                  {cartCount > 0 && (
                    <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] font-bold w-4 h-4 flex items-center justify-center rounded-full shadow-sm">
                      {cartCount}
                    </span>
                  )}
                </div>
              </>
            )}
            {isAdmin && (
              <NavLink to="/admin" active={location.pathname.startsWith('/admin')}>Dashboard</NavLink>
            )}

            {/* Notification Bell */}
            <div className="pl-2 border-l border-slate-700">
               <NotificationBell notifications={notifications} onMarkRead={onMarkRead} />
            </div>

            <div className="flex items-center space-x-2">
              <button 
                onClick={onLogout}
                className="p-2 rounded-full hover:bg-slate-800 text-slate-400 hover:text-red-400 transition-colors"
                title="Sign Out"
              >
                <LogOut className="w-5 h-5" />
              </button>
            </div>
          </div>
        </div>
      </div>
    </nav>
  );
};

const NavLink: React.FC<{ to: string; active: boolean; children: React.ReactNode }> = ({ to, active, children }) => (
  <Link 
    to={to} 
    className={`text-sm font-semibold transition-colors ${
      active ? 'text-orange-400' : 'text-slate-400 hover:text-slate-100'
    }`}
  >
    {children}
  </Link>
);

function App() {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  // Notification Hooks
  const { notifications, toasts, markAllRead, clearToasts } = useNotificationSystem();

  useEffect(() => {
    const checkUser = () => {
        const currentUser = db.getCurrentUser();
        setUser(currentUser);
        setLoading(false);
    };

    checkUser();

    // Listen for auth changes from the service instead of relying on reloading
    db.addEventListener('session-updated', checkUser);

    return () => {
        db.removeEventListener('session-updated', checkUser);
    };
  }, []);

  const handleLogout = () => {
    db.logout();
  };

  if (loading) return <div className="min-h-screen bg-slate-950 flex items-center justify-center text-orange-500">Loading Quick Bite...</div>;

  return (
    <HashRouter>
      <div className="min-h-screen bg-slate-950 text-slate-200 font-sans">
        <Navbar 
            user={user} 
            onLogout={handleLogout} 
            notifications={notifications}
            onMarkRead={markAllRead}
        />

        <ToastContainer toasts={toasts} onDismiss={clearToasts} />

        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <Routes>
            <Route path="/auth" element={!user ? <AuthPage onLogin={setUser} /> : <Navigate to={user.role === UserRole.CUSTOMER ? "/menu" : "/admin"} />} />

            {/* Customer Routes */}
            <Route path="/menu" element={user?.role === UserRole.CUSTOMER ? <CustomerMenu /> : <Navigate to="/auth" />} />
            <Route path="/cart" element={user?.role === UserRole.CUSTOMER ? <CustomerCart /> : <Navigate to="/auth" />} />
            <Route path="/orders" element={user?.role === UserRole.CUSTOMER ? <CustomerOrders /> : <Navigate to="/auth" />} />

            {/* Admin Routes */}
            <Route path="/admin" element={
              (user?.role === UserRole.ADMIN || user?.role === UserRole.SPECIALIZED_ADMIN) 
              ? <AdminDashboard user={user} /> 
              : <Navigate to="/auth" />
            } />

            <Route path="*" element={<Navigate to={user ? (user.role === UserRole.CUSTOMER ? "/menu" : "/admin") : "/auth"} />} />
          </Routes>
        </main>

        {user?.role === UserRole.CUSTOMER && <Chatbot />}
      </div>
    </HashRouter>
  );
}

export default App;

import React, { useState } from 'react';
import { db } from '../services/supabaseService';
import { User, UserRole } from '../types';
import { Heart, ArrowRight, AlertTriangle, UserPlus, LogIn, Lock, Mail, User as UserIcon, Zap } from 'lucide-react';

interface AuthPageProps {
  onLogin: (user: User) => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // Form State
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (!email || !password || (!isLogin && !name)) {
        setError('Please fill in all fields.');
        setLoading(false);
        return;
    }

    try {
      let user;
      if (isLogin) {
          user = await db.login(email, password);
      } else {
          // FORCE ROLE TO CUSTOMER
          user = await db.register({ name, email, password, role: UserRole.CUSTOMER });
      }
      onLogin(user);
    } catch (err: any) {
      setError(err.message || 'Authentication failed');
    } finally {
      setLoading(false);
    }
  };

  const toggleMode = () => {
      setIsLogin(!isLogin);
      setError('');
      setPassword('');
      if (!isLogin) {
          setName('');
      }
  };

  const handleQuickLogin = async (role: 'admin' | 'student') => {
      setLoading(true);
      setError('');
      try {
          let user;
          if (role === 'admin') {
              user = await db.login('admin@quickbite.com', 'admin');
          } else {
              user = await db.login('student@demo.com', 'student');
          }
          onLogin(user);
      } catch (err: any) {
          setError('Demo account not found. Please refresh to re-seed data.');
      } finally {
          setLoading(false);
      }
  };

  return (
    <div className="min-h-[80vh] flex flex-col items-center justify-center p-4">
      <div className="w-full max-w-md bg-slate-900 p-8 md:p-10 rounded-3xl shadow-2xl shadow-slate-900/50 relative overflow-hidden border border-slate-800 transition-all duration-300">

        {/* Header */}
        <div className="relative z-10 text-center mb-8">
          <div className="mx-auto bg-gradient-to-tr from-pink-500 to-orange-500 w-16 h-16 rounded-full flex items-center justify-center mb-4 shadow-lg shadow-orange-500/20 animate-in zoom-in duration-300">
            <Heart className="w-8 h-8 text-white fill-current" />
          </div>
          <h1 className="text-3xl font-bold text-white mb-2 tracking-tight">
              {isLogin ? 'Welcome Back' : 'Create Account'}
          </h1>
          <p className="text-slate-400 text-sm">
              {isLogin ? 'Sign in to access your canteen' : 'Join Quick Bite today'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4 relative z-10">

            {/* Name Field (Signup Only) */}
            {!isLogin && (
                <div className="relative animate-in slide-in-from-left-5 fade-in duration-300">
                    <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                    <input 
                        type="text" 
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        className="w-full bg-slate-800 border border-slate-700 rounded-xl pl-12 pr-4 py-3.5 text-white focus:ring-2 focus:ring-orange-900/50 focus:border-orange-500 outline-none transition-all font-medium text-sm placeholder-slate-500"
                        placeholder="Full Name"
                    />
                </div>
            )}

            {/* Email Field */}
            <div className="relative">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                <input 
                    type="email" 
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    className="w-full bg-slate-800 border border-slate-700 rounded-xl pl-12 pr-4 py-3.5 text-white focus:ring-2 focus:ring-orange-900/50 focus:border-orange-500 outline-none transition-all font-medium text-sm placeholder-slate-500"
                    placeholder="Email Address"
                />
            </div>

            {/* Password Field */}
            <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                <input 
                    type="password" 
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="w-full bg-slate-800 border border-slate-700 rounded-xl pl-12 pr-4 py-3.5 text-white focus:ring-2 focus:ring-orange-900/50 focus:border-orange-500 outline-none transition-all font-medium text-sm placeholder-slate-500"
                    placeholder="Password"
                />
            </div>

            {/* Error Message */}
            {error && (
                <div className="flex items-center text-red-400 text-xs font-bold bg-red-900/20 p-3 rounded-xl animate-in shake border border-red-900/30">
                    <AlertTriangle className="w-4 h-4 mr-2 flex-shrink-0" />
                    {error}
                </div>
            )}

            {/* Submit Button */}
            <button 
                type="submit" 
                disabled={loading}
                className="w-full bg-orange-600 hover:bg-orange-500 text-white py-4 rounded-xl font-bold shadow-xl shadow-orange-900/20 transition-all flex items-center justify-center mt-4"
            >
                {loading ? (
                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                ) : (
                    <>
                        {isLogin ? 'Sign In' : 'Create Account'}
                        <ArrowRight className="w-4 h-4 ml-2" />
                    </>
                )}
            </button>
        </form>

        {/* Toggle Mode */}
        <div className="relative z-10 text-center mt-6">
            <button 
                onClick={toggleMode}
                className="text-slate-400 hover:text-orange-400 text-sm font-medium transition-colors"
            >
                {isLogin ? (
                    <>New here? <span className="text-orange-500 font-bold underline decoration-orange-500/30 underline-offset-2">Create an account</span></>
                ) : (
                    <>Already have an account? <span className="text-orange-500 font-bold underline decoration-orange-500/30 underline-offset-2">Sign in</span></>
                )}
            </button>
        </div>

        {/* Quick Demo Access */}
        <div className="mt-8 border-t border-slate-800 pt-6 relative z-10">
          <p className="text-[10px] text-center text-slate-500 mb-3 font-bold uppercase tracking-wider flex items-center justify-center">
            <Zap className="w-3 h-3 mr-1 text-orange-400" /> Quick Demo Login
          </p>
          <div className="grid grid-cols-2 gap-3">
            <button 
                onClick={() => handleQuickLogin('student')}
                disabled={loading}
                className="bg-orange-900/20 hover:bg-orange-900/30 text-orange-400 py-2.5 rounded-xl text-xs font-bold transition-colors border border-orange-900/30"
            >
                Student Demo
            </button>
            <button 
                onClick={() => handleQuickLogin('admin')}
                disabled={loading}
                className="bg-slate-800 hover:bg-slate-700 text-slate-300 py-2.5 rounded-xl text-xs font-bold transition-colors border border-slate-700"
            >
                Admin Demo
            </button>
          </div>
        </div>

        {/* Decorative Blobs */}
        <div className="absolute -top-20 -right-20 w-64 h-64 bg-orange-600 rounded-full blur-3xl opacity-10 pointer-events-none"></div>
        <div className="absolute -bottom-20 -left-20 w-64 h-64 bg-pink-600 rounded-full blur-3xl opacity-10 pointer-events-none"></div>
      </div>

      <div className="mt-8 text-center">
          <p className="text-slate-500 text-xs">© 2025 Quick Bite. Smart Canteen System.</p>
      </div>
    </div>
  );
};

