import { Plus, Star, Clock, X, Heart, Sparkles, Smile, Frown, Coffee, Flame } from 'lucide-react';
import { getMealSuggestion } from '../../services/geminiService';

const MoodEmoji = ({ mood, icon, onClick, active }: any) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center p-4 rounded-2xl transition-all duration-300 transform hover:scale-105 ${
      active ? 'bg-orange-500/20 scale-110 border border-orange-500/30' : 'hover:bg-slate-800'
