    <div className={`text-4xl mb-2 transition-transform ${active ? 'scale-125' : ''}`}>{icon}</div>
    <span className={`text-xs font-medium ${active ? 'text-orange-400' : 'text-slate-500'}`}>{mood}</span>
  </button>
);

const MenuPage: React.FC = () => {
  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCategory, setSelectedCategory] = useState<FoodCategory | 'All'>('All');
  const [showMoodModal, setShowMoodModal] = useState(true);
  const [selectedMood, setSelectedMood] = useState<string | null>(null);
  const [suggestion, setSuggestion] = useState<{name: string, reason: string} | null>(null);
  const [aiLoading, setAiLoading] = useState(false);

  useEffect(() => {
    const fetchMenu = async () => {
        const data = await db.getMenu();
        setMenu(data);
        setLoading(false);
    };
    fetchMenu();
    // Re-fetch when ratings change
    db.addEventListener('change', fetchMenu);
    return () => db.removeEventListener('change', fetchMenu);
  }, []);

  const addToCart = (item: MenuItem) => {
    const cart: CartItem[] = JSON.parse(localStorage.getItem('qb_cart') || '[]');
    const existing = cart.find(i => i.id === item.id);
    if (existing) {
      existing.quantity += 1;
    } else {
      cart.push({ ...item, quantity: 1 });
    }
    localStorage.setItem('qb_cart', JSON.stringify(cart));
    window.dispatchEvent(new Event('cart-updated'));

    const toast = document.createElement('div');
    toast.className = 'fixed bottom-24 left-1/2 -translate-x-1/2 bg-slate-800 border border-slate-700 text-white px-6 py-3 rounded-full shadow-2xl text-sm font-medium z-50 flex items-center space-x-2 animate-in fade-in slide-in-from-bottom-5';
    toast.innerHTML = `<svg class="w-4 h-4 text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7"></path></svg><span>Added ${item.name}</span>`;
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 2000);
  };

  const handleMoodSubmit = async () => {
    if (!selectedMood) return;
    setAiLoading(true);

    try {
      const user = db.getCurrentUser();
      const pastOrders = user ? await db.getOrdersForUser(user.id) : [];

      const prompt = `I am feeling ${selectedMood}. Suggest a comfort food from the menu that matches this mood perfectly.`;
      const result = await getMealSuggestion(prompt, menu, pastOrders);

      if (result.suggestedItemName) {
        setSuggestion({
          name: result.suggestedItemName,
          reason: result.reason
        });
      }
    } catch (e) {
      console.error(e);
    } finally {
      setAiLoading(false);
    }
  };

  const filteredMenu = selectedCategory === 'All' 
    ? menu 
    : menu.filter(m => m.category === selectedCategory);

  if (loading) return <div className="p-8 text-center text-slate-400">Loading Menu...</div>;

  return (
    <div className="pb-20">
      {/* Mood Modal */}
      {showMoodModal && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-slate-900 w-full max-w-sm rounded-3xl shadow-2xl shadow-black/50 overflow-hidden relative animate-in zoom-in-95 duration-300 border border-slate-800">
            <button 
              onClick={() => setShowMoodModal(false)}
              className="absolute top-4 right-4 text-slate-400 hover:text-white p-1 bg-slate-800 rounded-full hover:bg-slate-700"
            >
              <X className="w-5 h-5" />
            </button>

            {!suggestion ? (
              <div className="p-8 text-center">
                <div className="mb-6">
                  <h2 className="text-2xl font-bold text-white mb-2">How are you feeling?</h2>
                  <p className="text-slate-400 text-sm">Pick one. Chef Byte will handle the rest! ✨</p>
                </div>

                <div className="grid grid-cols-2 gap-4 mb-8">
                  <MoodEmoji mood="Happy" icon="😄" active={selectedMood === 'Happy'} onClick={() => setSelectedMood('Happy')} />
                  <MoodEmoji mood="Cozy" icon="🧸" active={selectedMood === 'Cozy'} onClick={() => setSelectedMood('Cozy')} />
                  <MoodEmoji mood="Stressed" icon="😫" active={selectedMood === 'Stressed'} onClick={() => setSelectedMood('Stressed')} />
                  <MoodEmoji mood="Hungry" icon="🤤" active={selectedMood === 'Hungry'} onClick={() => setSelectedMood('Hungry')} />
                </div>

                <button
                  onClick={handleMoodSubmit}
                  disabled={!selectedMood || aiLoading}
                  className="w-full bg-orange-600 hover:bg-orange-500 disabled:opacity-50 text-white font-bold py-4 rounded-xl shadow-lg shadow-orange-900/20 transition-all flex items-center justify-center"
                >
                  {aiLoading ? (
                    <span className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
                  ) : (
                    'Secure Mood'
                  )}
                </button>
                <button 
                  onClick={() => setShowMoodModal(false)}
                  className="mt-4 text-sm text-slate-500 font-medium hover:text-slate-300"
                >
                  Maybe Later
                </button>
              </div>
            ) : (
              <div className="p-8 text-center bg-orange-900/10">
                 <div className="w-20 h-20 bg-slate-800 rounded-full mx-auto flex items-center justify-center shadow-md mb-4 text-4xl border-2 border-orange-900/30 animate-bounce">
                    👨‍🍳
                 </div>
                 <h3 className="text-lg font-bold text-white mb-2">Chef Byte Suggests:</h3>
                 <div className="bg-slate-900 p-5 rounded-2xl shadow-sm border border-slate-800 mb-6">
