                        </div>
                        <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-slate-950/90 to-transparent p-4">
                             <span className={`inline-block px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wide text-white ${item.isVeg ? 'bg-green-600' : 'bg-red-600'}`}>
                                {item.isVeg ? 'VEG' : 'NON-VEG'}
                            </span>
                        </div>
                    </div>

                    <div className="p-5">
                        <div className="flex justify-between items-start mb-2">
                            <h3 className="font-bold text-slate-100 text-lg leading-tight">{item.name}</h3>
                            <div className="flex items-center bg-yellow-900/20 px-1.5 py-0.5 rounded-md border border-yellow-900/30">
                                <Star className="w-3 h-3 text-yellow-500 fill-current mr-1" />
                                <span className="text-xs font-bold text-yellow-500">{item.averageRating || '4.5'}</span>
                                <span className="text-[10px] text-slate-500 ml-1">({item.totalReviews || 0})</span>
                            </div>
                        </div>

                        <p className="text-slate-400 text-xs mb-4 line-clamp-2">{item.description}</p>

                        <div className="flex items-center justify-between pt-4 border-t border-slate-800">
                            <div>
                                <span className="text-slate-500 text-xs line-through mr-2">₹{Math.round(item.price * 1.2)}</span>
                                <span className="text-lg font-bold text-slate-200">₹{item.price}</span>
                            </div>
                            <button 
                                onClick={() => addToCart(item)}
                                className="bg-orange-500/10 text-orange-400 hover:bg-orange-600 hover:text-white px-4 py-2 rounded-xl font-bold text-sm transition-all flex items-center border border-orange-500/20 hover:border-orange-600"
                            >
                                <Plus className="w-4 h-4 mr-1" /> ADD
                            </button>
                        </div>
                    </div>
                </div>
            ))}
        </div>
      </div>
    </div>
  );
};

export default MenuPage;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { db } from '../../services/supabaseService';
import { CartItem, PickupSlot } from '../../types';
import { Trash2, Plus, Minus, CreditCard, Clock, ChevronRight, ShoppingBag, Tag, X, AlertTriangle, Flame, Info } from 'lucide-react';

const CartPage: React.FC = () => {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [slots, setSlots] = useState<PickupSlot[]>([]);
  const [selectedSlot, setSelectedSlot] = useState<string | null>(null);
  const [paying, setPaying] = useState(false);
  const [error, setError] = useState('');
  const [kitchenLoad, setKitchenLoad] = useState({ level: 'Low', extraDelay: 0 });

  // Coupon State
  const [couponCode, setCouponCode] = useState('');
  const [discount, setDiscount] = useState(0);
  const [couponMsg, setCouponMsg] = useState({ text: '', isError: false });
  const [appliedCode, setAppliedCode] = useState<string | null>(null);

  const navigate = useNavigate();

  const loadCart = async () => {
    try {
      const stored = localStorage.getItem('qb_cart');
      if (stored) {
        setCart(JSON.parse(stored));
      } else {
        setCart([]);
      }
      const fetchedSlots = await db.getSlots();
      setSlots(fetchedSlots);

      const stats = await db.getKitchenStats();
      setKitchenLoad({ level: stats.loadLevel, extraDelay: stats.extraDelay });

    } catch (e) {
      console.error("Failed to load cart", e);
      setCart([]);
    }
  };

  useEffect(() => {
    loadCart();

    // Listen for storage events (cross-tab)
    window.addEventListener('storage', loadCart);
    // Listen for internal app events (same-tab)
    window.addEventListener('cart-updated', loadCart);

    return () => {
      window.removeEventListener('storage', loadCart);
      window.removeEventListener('cart-updated', loadCart);
    };
  }, []);

  const updateQty = (id: string, delta: number) => {
    const newCart = cart.map(item => {
      if (item.id === id) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    });
    setCart(newCart);
    localStorage.setItem('qb_cart', JSON.stringify(newCart));
    window.dispatchEvent(new Event('cart-updated'));

    // Reset coupon if cart changes
    if (appliedCode) {
      setAppliedCode(null);
      setDiscount(0);
      setCouponMsg({ text: 'Cart modified, please re-apply coupon.', isError: true });
    }
  };

  const remove = (id: string) => {
    const newCart = cart.filter(item => item.id !== id);
    setCart(newCart);
    localStorage.setItem('qb_cart', JSON.stringify(newCart));
    window.dispatchEvent(new Event('cart-updated'));

    // Reset coupon
    if (appliedCode) {
      setAppliedCode(null);
      setDiscount(0);
      setCouponMsg({ text: '', isError: false });
    }
  };

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const tax = Math.round(subtotal * 0.02); // Updated to 2%
  // Ensure total doesn't drop below 0
  const finalTotal = Math.max(0, subtotal + tax - discount);

  const applyCoupon = () => {
    if (!couponCode.trim()) return;

    const result = db.validateCoupon(couponCode, cart);

    if (result.valid) {
      setDiscount(result.discount);
      setAppliedCode(couponCode);
      setCouponMsg({ text: result.message, isError: false });
    } else {
      setDiscount(0);
      setAppliedCode(null);
      setCouponMsg({ text: result.message, isError: true });
    }
  };

  const removeCoupon = () => {
    setCouponCode('');
    setDiscount(0);
    setAppliedCode(null);
    setCouponMsg({ text: '', isError: false });
  };

  const handlePayment = async () => {
    if (!selectedSlot) {
        setError('Please select a pickup time slot.');
        return;
    }

    setPaying(true);
    setError('');

    try {
      // Refresh user session just in case
      const user = db.getCurrentUser();
      if (!user) {
          throw new Error("Session expired. Please login again.");
      }

      // Simulate network delay
      await new Promise(resolve => setTimeout(resolve, 1500));

      // Create order (Async)
      await db.createOrder(cart, finalTotal, selectedSlot, discount, appliedCode || undefined);

      // Clear cart
      localStorage.removeItem('qb_cart');
      setCart([]);
      window.dispatchEvent(new Event('cart-updated'));

      navigate('/orders');
    } catch (err: any) {
      setError(err.message || 'Payment processing failed');
    } finally {
      setPaying(false);
    }
  };

  if (cart.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] text-center animate-in fade-in zoom-in duration-300">
        <div className="bg-slate-900 p-8 rounded-full shadow-lg mb-6 border border-slate-800">
          <ShoppingBag className="w-16 h-16 text-slate-700" />
        </div>
        <h2 className="text-3xl font-bold text-slate-200 mb-3">Your cart is empty</h2>
        <p className="text-slate-500 mb-8 max-w-md">Looks like you haven't added anything yet. Our kitchen is ready to whip up something delicious!</p>
        <button 
            onClick={() => navigate('/menu')} 
            className="bg-orange-600 text-white px-8 py-4 rounded-xl font-bold shadow-xl shadow-orange-900/20 hover:bg-orange-500 hover:scale-105 transition-all flex items-center"
        >
          Browse Menu <ChevronRight className="w-4 h-4 ml-2" />
        </button>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 pb-20">
      <div className="lg:col-span-2 space-y-6">

        {/* Kitchen Status Alert */}
        {kitchenLoad.level !== 'Low' && (
          <div className={`rounded-2xl p-4 flex items-start space-x-3 border shadow-sm animate-in fade-in slide-in-from-top-2 ${
            kitchenLoad.level === 'High' 
              ? 'bg-red-900/20 border-red-900/30 text-red-300' 
              : 'bg-orange-900/20 border-orange-900/30 text-orange-300'
          }`}>
             <div className={`p-2 rounded-full ${kitchenLoad.level === 'High' ? 'bg-red-900/40' : 'bg-orange-900/40'}`}>
                {kitchenLoad.level === 'High' ? <Flame className="w-5 h-5 animate-pulse" /> : <Clock className="w-5 h-5" />}
             </div>
             <div>
               <h3 className="font-bold text-sm">Kitchen is Busy</h3>
               <p className="text-xs opacity-90 mt-0.5">
                 High order volume right now. Slight delay expected (~{kitchenLoad.extraDelay} mins extra).
               </p>
             </div>
          </div>
        )}

        <h1 className="text-2xl font-bold text-white mb-6 flex items-center">
            Your Order 
            <span className="ml-3 bg-orange-900/30 border border-orange-900/50 text-orange-400 text-sm font-bold px-3 py-1 rounded-full">{cart.length} items</span>
        </h1>

        <div className="space-y-4">
          {cart.map(item => (
            <div key={item.id} className="bg-slate-900 border border-slate-800 p-4 rounded-2xl flex flex-col sm:flex-row items-center justify-between shadow-sm hover:border-slate-700 transition-all gap-4">
              <div className="flex items-center space-x-4 w-full sm:w-auto">
                <img src={item.image} alt={item.name} className="w-20 h-20 rounded-xl object-cover shadow-sm opacity-90" />
                <div>
                  <h3 className="font-bold text-slate-200 text-lg">{item.name}</h3>
                  <p className="text-sm text-slate-500 font-medium">₹{item.price}</p>
                </div>
              </div>

              <div className="flex items-center justify-between w-full sm:w-auto sm:space-x-6">
                <div className="flex items-center bg-slate-800 rounded-xl p-1 border border-slate-700">
                  <button onClick={() => updateQty(item.id, -1)} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400 hover:text-white transition-all">
                    <Minus className="w-4 h-4" />
                  </button>
                  <span className="w-10 text-center text-sm font-bold text-slate-200">{item.quantity}</span>
                  <button onClick={() => updateQty(item.id, 1)} className="p-2 hover:bg-slate-700 rounded-lg text-slate-400 hover:text-white transition-all">
                    <Plus className="w-4 h-4" />
                  </button>
                </div>
                <div className="flex items-center sm:block">
                     <span className="font-bold text-slate-300 mr-4 sm:hidden">₹{item.price * item.quantity}</span>
                    <button onClick={() => remove(item.id)} className="text-slate-500 hover:text-red-400 transition-colors p-2 bg-slate-800 rounded-lg hover:bg-red-900/20">
                    <Trash2 className="w-5 h-5" />
                    </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="lg:col-span-1">
        <div className="bg-slate-900 border border-slate-800 rounded-3xl p-6 sticky top-24 shadow-xl shadow-black/20">
          <h2 className="text-xl font-bold text-white mb-6">Payment Details</h2>

          <div className="mb-6">
            <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wide mb-3 flex items-center">
              <Clock className="w-4 h-4 mr-2" /> Select Pickup Time
            </h3>
            <div className="grid grid-cols-2 gap-2 max-h-48 overflow-y-auto pr-1 custom-scrollbar">
              {slots.filter(s => s.available).map(slot => (
                <button
                  key={slot.id}
                  onClick={() => {
                      setSelectedSlot(slot.id);
                      setError('');
                  }}
                  className={`p-3 rounded-xl text-xs font-bold border transition-all ${
                    selectedSlot === slot.id 
                      ? 'bg-orange-600 text-white border-orange-500 shadow-md shadow-orange-900/30' 
                      : 'bg-slate-800 border-transparent text-slate-400 hover:bg-slate-700 hover:border-slate-600'
                  }`}
                >
                  {slot.time}
                </button>
              ))}
              {slots.filter(s => s.available).length === 0 && (
                  <div className="col-span-2 text-center text-xs text-red-400 font-bold p-2 bg-red-900/20 rounded-lg border border-red-900/30">
                      No slots available.
                  </div>
              )}
            </div>
          </div>

          {/* Coupon Code Section */}
          <div className="mb-6">
            <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wide mb-3 flex items-center">
              <Tag className="w-4 h-4 mr-2" /> Apply Coupon
            </h3>
            {!appliedCode ? (
              <div className="flex space-x-2">
                <input 
                  type="text" 
                  value={couponCode}
                  onChange={(e) => setCouponCode(e.target.value.toUpperCase())}
                  placeholder="CODE"
                  className="flex-1 bg-slate-800 border border-slate-700 rounded-xl px-4 py-2 text-sm font-bold uppercase placeholder-slate-500 focus:outline-none focus:border-orange-500 text-white"
                />
                <button 
                  onClick={applyCoupon}
                  className="bg-slate-700 hover:bg-slate-600 text-white px-4 py-2 rounded-xl text-sm font-bold transition-colors"
                >
                  Apply
                </button>
              </div>
            ) : (
              <div className="flex justify-between items-center bg-green-900/20 border border-green-900/30 rounded-xl px-4 py-3">
                <div className="flex items-center">
                  <Tag className="w-4 h-4 text-green-500 mr-2" />
                  <span className="font-bold text-green-400 text-sm tracking-wide">{appliedCode}</span>
                </div>
                <button onClick={removeCoupon} className="text-green-600 hover:text-green-400">
                  <X className="w-4 h-4" />
                </button>
              </div>
            )}
            {couponMsg.text && (
               <p className={`text-xs font-bold mt-2 ${couponMsg.isError ? 'text-red-400' : 'text-green-400'}`}>
                 {couponMsg.text}
               </p>
            )}
          </div>

          <div className="space-y-3 mb-6 pt-6 border-t border-slate-800">
            <div className="flex justify-between text-slate-400 text-sm">
              <span>Subtotal</span>
              <span>₹{subtotal}</span>
            </div>
            <div className="flex justify-between text-slate-400 text-sm">
              <span>Tax (2%)</span>
              <span>₹{tax}</span>
            </div>
            {discount > 0 && (
              <div className="flex justify-between text-green-400 text-sm font-bold">
                <span>Discount</span>
                <span>-₹{discount}</span>
              </div>
            )}
            <div className="flex justify-between text-white text-xl font-bold pt-2">
              <span>Total</span>
              <span>₹{finalTotal}</span>
            </div>
          </div>

          {error && (
            <div className="mb-4 p-3 bg-red-900/20 border border-red-900/30 rounded-xl flex items-center text-red-400 text-sm font-bold">
              <AlertTriangle className="w-4 h-4 mr-2" />
              {error}
            </div>
          )}

          <button
            onClick={handlePayment}
            disabled={paying}
            className="w-full bg-orange-600 hover:bg-orange-500 text-white py-4 rounded-xl font-bold shadow-lg shadow-orange-900/20 flex items-center justify-center transition-all disabled:opacity-70 disabled:cursor-not-allowed active:scale-[0.98]"
          >
            {paying ? (
              <span className="flex items-center">
                <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin mr-2"></span>
                Processing...
              </span>
            ) : (
              <span className="flex items-center">
                Pay Securely <ChevronRight className="w-4 h-4 ml-1" />
              </span>
            )}
          </button>

          <div className="mt-4 flex items-center justify-center text-slate-500 text-[10px] font-semibold bg-slate-800 py-2 rounded-lg border border-slate-700">
             <CreditCard className="w-3 h-3 mr-2" />
             <span>SECURE ENCRYPTED PAYMENT (SIMULATED)</span>
          </div>
        </div>
      </div>
    </div>
  );
};

