import React, { useEffect, useState } from 'react';
import { db } from '../../services/supabaseService';
import { Order, OrderStatus } from '../../types';
import { CheckCircle, Clock, Package, Loader2, Hourglass, Utensils, Flame, Star, MessageSquare } from 'lucide-react';

const OrdersPage: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [now, setNow] = useState(Date.now());
  const [loading, setLoading] = useState(true);

  // Rating Modal State
  const [ratingOrder, setRatingOrder] = useState<Order | null>(null);
  const [ratings, setRatings] = useState<{[key: string]: number}>({}); // itemId -> rating
  const [comments, setComments] = useState<{[key: string]: string}>({}); // itemId -> comment
  const [submittingReview, setSubmittingReview] = useState(false);

  const fetchOrders = async () => {
    const user = db.getCurrentUser();
    if (user) {
      const data = await db.getOrdersForUser(user.id);
      setOrders(data);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchOrders();
    // Re-bind change listener
    const handleDbChange = () => fetchOrders();
    db.addEventListener('change', handleDbChange);

    const timerInterval = setInterval(() => {
        setNow(Date.now());
    }, 1000);

    return () => {
        db.removeEventListener('change', handleDbChange);
        clearInterval(timerInterval);
    };
  }, []);

  const getStatusColor = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.CONFIRMED: return 'text-blue-400 bg-blue-900/20 border-blue-900/30';
      case OrderStatus.PREPARING: return 'text-orange-400 bg-orange-900/20 border-orange-900/30';
      case OrderStatus.READY: return 'text-green-400 bg-green-900/20 border-green-900/30';
      case OrderStatus.COMPLETED: return 'text-slate-400 bg-slate-800 border-slate-700';
    }
  };

  const getStatusIcon = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.CONFIRMED: return <CheckCircle className="w-4 h-4 mr-1.5" />;
      case OrderStatus.PREPARING: return <Utensils className="w-4 h-4 mr-1.5 animate-pulse" />;
      case OrderStatus.READY: return <Package className="w-4 h-4 mr-1.5" />;
      case OrderStatus.COMPLETED: return <CheckCircle className="w-4 h-4 mr-1.5" />;
      default: return <Clock className="w-4 h-4 mr-1.5" />;
    }
  };

  const calculateProgress = (order: Order) => {
      if (order.status === OrderStatus.READY || order.status === OrderStatus.COMPLETED) return 100;
      if (order.status === OrderStatus.CONFIRMED) return 5; 
      if (!order.targetTime || !order.prepStartTime) return 0;

      const totalDuration = order.targetTime - order.prepStartTime;
      const elapsed = now - order.prepStartTime;
      const percent = Math.min(100, Math.max(0, (elapsed / totalDuration) * 100));
      return percent;
  };

  const getCountdown = (order: Order) => {
      if (order.status === OrderStatus.READY || order.status === OrderStatus.COMPLETED) return "00:00";
      if (!order.targetTime) return "--:--";
      const remainingMs = Math.max(0, order.targetTime - now);
      const minutes = Math.floor(remainingMs / 60000);
      const seconds = Math.floor((remainingMs % 60000) / 1000);
      return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
  };

  const isAlmostReady = (order: Order) => {
    if (!order.targetTime || order.status !== OrderStatus.PREPARING) return false;
    const remainingMs = order.targetTime - now;
    return remainingMs > 0 && remainingMs < 2 * 60 * 1000; 
  };

  const handleOpenRating = (order: Order) => {
      setRatingOrder(order);
      // Initialize ratings to 5 stars
      const initialRatings: any = {};
      order.items.forEach(i => initialRatings[i.id] = 5);
      setRatings(initialRatings);
      setComments({});
  };

  const handleSubmitRating = async () => {
      if (!ratingOrder) return;
      setSubmittingReview(true);

      const user = db.getCurrentUser();

      // Submit review for each item
      for (const item of ratingOrder.items) {
          const rating = ratings[item.id] || 5;
          const comment = comments[item.id] || '';

          await db.addReview({
              menuItemId: item.id,
              orderId: ratingOrder.id,
              userId: user?.id || 'anon',
              rating,
              comment
          });
      }

      setSubmittingReview(false);
      setRatingOrder(null);
      // Refresh list handled by db event listener
  };

  if (loading) return <div className="text-center p-8 text-slate-400">Loading Orders...</div>;

  return (
    <div className="max-w-3xl mx-auto space-y-6">
      <h1 className="text-2xl font-bold text-white mb-8">My Orders</h1>

      {orders.length === 0 && (
        <div className="text-center py-16 bg-slate-900 rounded-3xl border border-dashed border-slate-800">
          <p className="text-slate-500 font-medium">No past orders found.</p>
        </div>
      )}

      {orders.map(order => {
        const isActive = order.status === OrderStatus.CONFIRMED || order.status === OrderStatus.PREPARING;
        const progress = calculateProgress(order);

        return (
            <div key={order.id} className="bg-slate-900 border border-slate-800 rounded-3xl overflow-hidden shadow-xl shadow-black/20 hover:border-slate-700 transition-all duration-300">
            <div className="p-6 border-b border-slate-800 flex flex-col sm:flex-row justify-between sm:items-center gap-4 bg-slate-800/30">
                <div>
                <p className="text-xs font-bold text-slate-500 uppercase tracking-wide mb-1">Order #{order.id}</p>
                <div className="flex items-center text-sm font-bold text-slate-300">
                    <Clock className="w-4 h-4 mr-2 text-slate-500" />
                    Pickup at {order.pickupTime}
                </div>
                </div>

                <div className={`px-4 py-2 rounded-full border flex items-center text-sm font-bold ${getStatusColor(order.status)}`}>
                {getStatusIcon(order.status)}
                {order.status}
                </div>
            </div>

            {/* Live Progress Bar Section */}
            {isActive && (
                <div className="bg-slate-900 px-6 py-6 border-b border-slate-800 relative overflow-hidden">
                    {isAlmostReady(order) && (
                         <div className="absolute inset-0 bg-orange-900/10 animate-pulse pointer-events-none"></div>
                    )}

                    <div className="relative z-10">
                        <div className="flex justify-between items-end mb-3">
                            <span className="text-xs font-bold text-orange-500 uppercase tracking-wider flex items-center">
                                {order.status === OrderStatus.CONFIRMED ? (
                                    <>Order Confirmed</>
                                ) : (
                                    <>
                                        <Hourglass className="w-3 h-3 mr-1 animate-spin-slow" /> 
                                        {isAlmostReady(order) ? 'Almost Ready!' : 'Estimated Time'}
                                    </>
                                )}
                            </span>
                            <span className="text-2xl font-bold text-white font-mono tracking-tight">
                                {order.status === OrderStatus.CONFIRMED ? 'Waiting...' : getCountdown(order)}
                            </span>
                        </div>

                        <div className="h-4 w-full bg-slate-800 rounded-full overflow-hidden shadow-inner relative">
                            <div 
                                className={`h-full rounded-full transition-all duration-1000 ease-linear shadow-lg ${
                                    isAlmostReady(order) 
                                    ? 'bg-gradient-to-r from-red-500 to-orange-500 animate-pulse' 
                                    : 'bg-gradient-to-r from-orange-500 to-pink-500'
                                }`}
                                style={{ width: `${progress}%` }}
                            />
                        </div>

                        <div className="flex justify-between items-center mt-3">
                             <p className="text-xs text-slate-500 font-medium">
                                {order.status === OrderStatus.CONFIRMED 
                                 ? 'Kitchen is reviewing your order...' 
                                 : isAlmostReady(order) 
                                   ? 'Putting final touches...' 
                                   : 'Chef is preparing your meal...'}
                             </p>
                             {isAlmostReady(order) && (
                                 <span className="flex items-center text-xs font-bold text-red-500 animate-bounce">
                                     <Flame className="w-3 h-3 mr-1" /> Hot & Fresh
                                 </span>
                             )}
                        </div>
                    </div>
                </div>
            )}

            <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-8">
                <div className="md:col-span-2 space-y-4">
                <ul className="space-y-4">
                    {order.items.map((item, idx) => (
                    <li key={idx} className="flex justify-between items-center">
                        <div className="flex items-center">
                           <span className="w-6 h-6 rounded bg-orange-900/20 text-orange-400 text-xs font-bold flex items-center justify-center mr-3 border border-orange-900/30">
                              {item.quantity}x
                           </span>
                           <span className="text-slate-300 font-medium">{item.name}</span>
                        </div>
                        <span className="text-slate-500 text-sm font-medium">₹{item.price * item.quantity}</span>
                    </li>
                    ))}
                </ul>
                <div className="pt-4 border-t border-slate-800 flex justify-between items-center">
                    <div className="font-bold text-slate-200 text-lg">
                        <span>Total Paid </span>
                        <span>₹{Math.round(order.totalAmount * 1.05)}</span>
                    </div>

                    {/* Rate Button */}
                    {order.status === OrderStatus.COMPLETED && !order.isRated && (
                        <button 
                            onClick={() => handleOpenRating(order)}
                            className="bg-slate-800 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center hover:bg-slate-700 transition-all border border-slate-700"
                        >
                            <Star className="w-4 h-4 mr-2 text-yellow-500 fill-current" />
                            Rate Food
                        </button>
                    )}
                    {order.isRated && (
                        <span className="text-green-500 text-xs font-bold flex items-center bg-green-900/20 px-3 py-1 rounded-full border border-green-900/30">
                            <CheckCircle className="w-3 h-3 mr-1" /> Rated
                        </span>
                    )}
                </div>
                </div>

                <div className="flex flex-col items-center justify-center p-4 bg-slate-800/50 rounded-2xl border border-slate-800">
                <div className={`transition-all duration-500 bg-white p-2 rounded-xl ${order.status === OrderStatus.READY || order.status === OrderStatus.COMPLETED ? 'opacity-100 blur-0' : 'opacity-30 blur-sm'}`}>
                    <img 
                        src={`https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${order.id}`}
                        alt="Order QR Code"
                        className="w-28 h-28 mix-blend-multiply"
                    />
                </div>
                <p className="mt-3 text-[10px] text-slate-500 font-bold uppercase tracking-widest text-center">
                    {order.status === OrderStatus.READY || order.status === OrderStatus.COMPLETED 
                     ? 'Scan at counter' 
                     : 'Preparing QR...'
                    }
                </p>
                </div>
            </div>

            {order.status === OrderStatus.READY && (
                <div className="bg-green-600 text-white p-3 text-center text-sm font-bold animate-pulse">
                   Your order is ready! Pickup now!
                </div>
            )}
            </div>
        );
      })}

      {/* Review Modal */}
      {ratingOrder && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm">
              <div className="bg-slate-900 rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95 border border-slate-800">
                  <div className="p-6 bg-slate-900 border-b border-slate-800">
                      <h2 className="text-xl font-bold text-white">Rate your meal</h2>
                      <p className="text-slate-400 text-sm">How was the food from Order #{ratingOrder.id}?</p>
                  </div>

                  <div className="p-6 max-h-[60vh] overflow-y-auto space-y-6 custom-scrollbar">
                      {ratingOrder.items.map(item => (
                          <div key={item.id} className="pb-6 border-b border-slate-800 last:border-0 last:pb-0">
                              <div className="flex items-center mb-3">
                                  <img src={item.image} className="w-12 h-12 rounded-lg object-cover mr-3 shadow-sm" alt="" />
                                  <h3 className="font-bold text-slate-200">{item.name}</h3>
                              </div>

                              <div className="flex space-x-1 mb-3">
                                  {[1, 2, 3, 4, 5].map(star => (
                                      <button
                                        key={star}
                                        onClick={() => setRatings(prev => ({ ...prev, [item.id]: star }))}
                                        className="p-1 focus:outline-none transition-transform hover:scale-110"
                                      >
                                          <Star 
                                            className={`w-8 h-8 ${
                                                (ratings[item.id] || 0) >= star 
                                                ? 'text-yellow-500 fill-current' 
                                                : 'text-slate-700'
                                            }`} 
                                          />
                                      </button>
                                  ))}
                              </div>

                              <textarea 
                                placeholder="Write a short review... (optional)"
                                value={comments[item.id] || ''}
                                onChange={(e) => setComments(prev => ({ ...prev, [item.id]: e.target.value }))}
                                className="w-full bg-slate-800 border border-slate-700 rounded-xl p-3 text-sm focus:ring-2 focus:ring-orange-900/50 focus:border-orange-500 outline-none transition-all text-white placeholder-slate-500"
                                rows={2}
                              />
                          </div>
                      ))}
                  </div>

                  <div className="p-6 bg-slate-900 border-t border-slate-800 flex space-x-3">
                      <button 
                        onClick={() => setRatingOrder(null)}
                        className="flex-1 py-3 rounded-xl font-bold text-slate-400 hover:bg-slate-800 transition-colors"
                      >
                          Cancel
                      </button>
                      <button 
                        onClick={handleSubmitRating}
                        disabled={submittingReview}
                        className="flex-1 py-3 rounded-xl font-bold text-white bg-orange-600 hover:bg-orange-500 shadow-lg shadow-orange-900/20 transition-colors disabled:opacity-50"
                      >
                          {submittingReview ? 'Submitting...' : 'Submit Review'}
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default OrdersPage;

import React, { useEffect, useState } from 'react';
import { db } from '../../services/supabaseService';
import { MenuItem, Order, OrderStatus, User, UserRole, FoodCategory, Coupon, DiscountType } from '../../types';
import { AreaChart, Area, PieChart, Pie, Cell, Legend, ResponsiveContainer, XAxis, YAxis, CartesianGrid, Tooltip } from 'recharts';
import { 
  LayoutDashboard, 
  UtensilsCrossed, 
  ChefHat, 
  History, 
  Ticket, 
  Plus, 
  Scan, 
  DollarSign, 
  TrendingUp, 
  Zap, 
  ThumbsDown, 
  Edit, 
  Trash2, 
  Clock, 
  CheckCircle, 
  X, 
  Image as ImageIcon, 
  Save,
  Search,
  Filter,
  ArrowRight,
  Star
} from 'lucide-react';

interface AdminDashboardProps {
  user: User;
}

const COLORS = ['#f97316', '#ef4444', '#3b82f6', '#10b981', '#94a3b8'];

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'kitchen' | 'menu' | 'history' | 'coupons'>('overview');

  // Analytics State
  const [analytics, setAnalytics] = useState({
      todayRevenue: 0, yesterdayRevenue: 0, todayOrders: 0, yesterdayOrders: 0,
      revenueData: [] as any[], categoryData: [] as any[], popularItem: { name: 'N/A', count: 0 }, peakTime: '--',
      kitchenLoad: 'Low', activeOrders: 0,
      lowestRated: [] as MenuItem[], mostReviewed: [] as MenuItem[]
  });

  const [orders, setOrders] = useState<Order[]>([]);
  const [menu, setMenu] = useState<MenuItem[]>([]);
  const [coupons, setCoupons] = useState<Coupon[]>([]);
  const [now, setNow] = useState(Date.now());

  // Menu Modal State
  const [isMenuModalOpen, setIsMenuModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [menuForm, setMenuForm] = useState<Partial<MenuItem>>({
      name: '', price: 0, category: FoodCategory.LUNCH, description: '', image: '', isVeg: true
  });

  useEffect(() => {
    const updateData = async () => {
      const stats = await db.getAnalytics();
      setAnalytics(stats);

      const menuData = await db.getMenu();
      setMenu(menuData);

      setCoupons(db.getCoupons()); 

      let allOrders = await db.getOrders();
      if (user.role === UserRole.SPECIALIZED_ADMIN && user.specialty) {
        allOrders = allOrders.filter(o => o.items.some(i => i.category === user.specialty));
      }
      setOrders(allOrders);
    };

    updateData();
    db.addEventListener('change', updateData);

    // Timer for live updates
    const interval = setInterval(() => setNow(Date.now()), 1000);

    return () => {
      db.removeEventListener('change', updateData);
      clearInterval(interval);
    };
  }, [user]);

  const updateStatus = async (id: string, status: OrderStatus) => {
    await db.updateOrderStatus(id, status);
  };

  const deleteMenuItem = async (id: string) => {
    if (confirm('Are you sure you want to remove this item from the menu?')) {
        await db.deleteMenuItem(id);
    }
  };

  const deleteCoupon = (id: string) => {
    if (confirm('Stop this coupon?')) {
        db.deleteCoupon(id);
    }
  };

  const handleOpenMenuModal = (item?: MenuItem) => {
      if (item) {
          setEditingItem(item);
          setMenuForm({ ...item });
      } else {
          setEditingItem(null);
          setMenuForm({
            name: '', 
            price: 100, 
            category: FoodCategory.LUNCH, 
            description: '', 
            image: 'https://picsum.photos/400/300', 
            isVeg: true
          });
      }
      setIsMenuModalOpen(true);
  };

  const handleMenuSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!menuForm.name || !menuForm.price) return;

      try {
          if (editingItem) {
              await db.updateMenuItem(editingItem.id, menuForm);
          } else {
              await db.addMenuItem(menuForm as any);
          }
          setIsMenuModalOpen(false);
      } catch (err) {
          alert('Failed to save item');
      }
  };

  const handleAddCoupon = () => {
    const code = prompt("Enter Code (e.g. SAVE20):");
    if(!code) return;
    const value = Number(prompt("Discount Percentage (e.g. 20):"));
    if(isNaN(value)) return;

    db.addCoupon({ 
        id: '', // Generated in service
        code: code.toUpperCase(), 
        type: DiscountType.PERCENTAGE, 
        value, 
        category: 'ALL', 
        expiryDate: '2025-12-31' 
    });
  };

  const handleScanQR = () => {
      const orderId = prompt("📷 SIMULATED QR SCANNER\n\nEnter Order ID from Customer's phone:");
      if (!orderId) return;
      const order = orders.find(o => o.id === orderId.trim());

      if (!order) { alert("❌ Order not found."); return; }
      if (order.status === OrderStatus.COMPLETED) { alert("⚠️ Order already picked up."); return; }
      if (order.status !== OrderStatus.READY) { alert(`⚠️ Order is not ready yet (${order.status}).`); return; }

      if (confirm(`✅ CONFIRMED!\n\nOrder #${order.id}\nItems: ${order.items.length}\n\nHand over food?`)) {
          updateStatus(order.id, OrderStatus.COMPLETED);
      }
  };

  const getTimerDisplay = (order: Order) => {
    if (order.status !== OrderStatus.PREPARING || !order.targetTime) return null;
    const remainingMs = order.targetTime - now;
    if (remainingMs <= 0) return <span className="text-red-500 font-bold text-xs">Overdue</span>;

    const minutes = Math.floor(remainingMs / 60000);
    const seconds = Math.floor((remainingMs % 60000) / 1000);
    return (
        <span className={`text-xs font-mono font-bold px-2 py-1 rounded ${remainingMs < 60000 ? 'bg-red-900/30 text-red-500 animate-pulse' : 'bg-slate-800 text-slate-300'}`}>
            {minutes}:{seconds.toString().padStart(2, '0')}
        </span>
    );
  };

  // --- Simplified Navigation Component ---
  const NavTab = ({ id, label, icon: Icon }: any) => (
    <button
      onClick={() => setActiveTab(id)}
      className={`flex items-center space-x-2 px-5 py-3 rounded-xl transition-all font-bold text-sm ${
        activeTab === id 
        ? 'bg-slate-800 text-white shadow-lg shadow-black/20 scale-105 border border-slate-700' 
        : 'bg-transparent text-slate-400 hover:bg-slate-800 border border-transparent hover:border-slate-800'
      }`}
    >
      <Icon className={`w-4 h-4 ${activeTab === id ? 'text-orange-500' : ''}`} />
      <span>{label}</span>
    </button>
  );

  return (
    <div className="space-y-8 max-w-7xl mx-auto pb-20">
      {/* 1. Header Area */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
           <h1 className="text-2xl font-bold text-white">
               {new Date().getHours() < 12 ? 'Good Morning' : 'Good Afternoon'}, Admin! 👋
           </h1>
           <p className="text-slate-400 text-sm">Here is what's happening in your canteen today.</p>
        </div>

        {/* Large Scan Button for quick access */}
        <button 
            onClick={handleScanQR}
            className="bg-orange-600 hover:bg-orange-500 text-white px-6 py-3 rounded-xl font-bold shadow-lg shadow-orange-900/20 flex items-center transition-all active:scale-95"
        >
            <Scan className="w-5 h-5 mr-2" />
            Scan Pickup QR
        </button>
      </div>

      {/* 2. Navigation Tabs */}
      <div className="flex flex-wrap gap-3 p-1 bg-slate-900/50 rounded-2xl border border-slate-800/50 backdrop-blur-sm">
        <NavTab id="overview" label="Overview" icon={LayoutDashboard} />
        <NavTab id="kitchen" label="Live Kitchen" icon={ChefHat} />
        <NavTab id="menu" label="Food Menu" icon={UtensilsCrossed} />
        <NavTab id="history" label="Past Orders" icon={History} />
        <NavTab id="coupons" label="Coupons" icon={Ticket} />
      </div>

      {/* 3. OVERVIEW TAB (Home) */}
      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in fade-in slide-in-from-bottom-4">

          {/* Main Status Cards */}
          <div className="lg:col-span-2 space-y-6">
             <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {/* Active Orders */}
                <div onClick={() => setActiveTab('kitchen')} className="bg-slate-900 p-6 rounded-3xl border border-slate-800 shadow-sm cursor-pointer hover:border-orange-500/30 hover:shadow-md transition-all group">
                    <div className="flex justify-between items-start mb-4">
                        <div className="p-3 bg-orange-900/20 rounded-2xl group-hover:bg-orange-900/40 transition-colors">
                            <ChefHat className="w-6 h-6 text-orange-500" />
                        </div>
                        <span className="bg-green-900/20 text-green-400 text-xs font-bold px-2 py-1 rounded-full border border-green-900/30">Live</span>
                    </div>
                    <div className="text-4xl font-bold text-white mb-1">{analytics.activeOrders}</div>
                    <div className="text-slate-400 text-sm font-medium">Orders to Prepare</div>
                </div>

                {/* Sales */}
                <div className="bg-slate-900 p-6 rounded-3xl border border-slate-800 shadow-sm">
                    <div className="flex justify-between items-start mb-4">
                        <div className="p-3 bg-blue-900/20 rounded-2xl">
                            <DollarSign className="w-6 h-6 text-blue-500" />
                        </div>
                        <span className="flex items-center text-green-500 text-xs font-bold">
                            <TrendingUp className="w-3 h-3 mr-1" />
                            Live
                        </span>
                    </div>
                    <div className="text-4xl font-bold text-white mb-1">₹{analytics.todayRevenue}</div>
                    <div className="text-slate-400 text-sm font-medium">Total Sales Today</div>
                </div>

                {/* Kitchen Load */}
                <div className={`p-6 rounded-3xl border shadow-sm transition-colors ${analytics.kitchenLoad === 'High' ? 'bg-red-900/20 border-red-900/50' : 'bg-slate-900 border-slate-800'}`}>
                    <div className="flex justify-between items-start mb-4">
                        <div className={`p-3 rounded-2xl ${analytics.kitchenLoad === 'High' ? 'bg-red-900/40' : 'bg-slate-800'}`}>
                            <Zap className={`w-6 h-6 ${analytics.kitchenLoad === 'High' ? 'text-red-400' : 'text-slate-400'}`} />
                        </div>
                    </div>
                    <div className={`text-4xl font-bold mb-1 ${analytics.kitchenLoad === 'High' ? 'text-red-400' : 'text-white'}`}>{analytics.kitchenLoad}</div>
                    <div className={`text-sm font-medium ${analytics.kitchenLoad === 'High' ? 'text-red-300' : 'text-slate-400'}`}>Kitchen Pressure</div>
                </div>
             </div>

             {/* Quick Actions Panel */}
             <div className="bg-gradient-to-r from-slate-900 to-slate-800 border border-slate-700 rounded-3xl p-8 text-white relative overflow-hidden shadow-xl">
                 <div className="relative z-10">
                     <h2 className="text-2xl font-bold mb-2">Quick Actions</h2>
                     <p className="text-slate-400 mb-6 text-sm">Common tasks you can do right now.</p>

                     <div className="flex flex-wrap gap-4">
                         <button 
                            onClick={() => handleOpenMenuModal()}
                            className="bg-white text-slate-900 px-5 py-3 rounded-xl font-bold text-sm hover:bg-slate-200 transition-colors flex items-center"
                         >
                             <Plus className="w-4 h-4 mr-2" /> Add New Dish
                         </button>
                         <button 
                            onClick={handleAddCoupon}
                            className="bg-slate-700 text-white border border-slate-600 px-5 py-3 rounded-xl font-bold text-sm hover:bg-slate-600 transition-colors flex items-center"
                         >
                             <Ticket className="w-4 h-4 mr-2" /> Create Coupon
                         </button>
                     </div>
                 </div>
                 {/* Decorative background element */}
                 <ChefHat className="absolute -bottom-6 -right-6 w-48 h-48 text-white/5 rotate-12" />
             </div>

             {/* Alerts / Insights (Only Show if Data Exists) */}
             {analytics.lowestRated.length > 0 && (
                 <div className="bg-red-900/10 border border-red-900/30 rounded-3xl p-6">
                     <div className="flex items-center space-x-2 mb-4">
                         <ThumbsDown className="w-5 h-5 text-red-500" />
                         <h3 className="font-bold text-red-400">Attention Needed</h3>
                     </div>
                     <p className="text-sm text-red-300 mb-3">These items have low ratings recently:</p>
                     <div className="space-y-2">
                         {analytics.lowestRated.map(item => (
                             <div key={item.id} className="bg-slate-900 p-3 rounded-xl border border-red-900/30 flex justify-between items-center">
                                 <span className="text-sm font-bold text-slate-300">{item.name}</span>
                                 <span className="text-xs font-bold text-red-400 bg-red-900/20 px-2 py-1 rounded">{item.averageRating?.toFixed(1)} ★</span>
                             </div>
                         ))}
                     </div>
                 </div>
             )}
          </div>

          {/* Side Panel: Recent Revenue Graph */}
          <div className="bg-slate-900 border border-slate-800 rounded-3xl p-6 shadow-sm flex flex-col">
              <h3 className="font-bold text-white mb-6">Weekly Revenue</h3>
              <div className="h-[300px] w-full">
                  {analytics.revenueData.every(d => d.revenue === 0) ? (
                      <div className="h-full flex items-center justify-center text-slate-500 text-sm">
                          No revenue data yet.
                      </div>
                  ) : (
                      <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={analytics.revenueData}>
                          <defs>
                            <linearGradient id="colorRev" x1="0" y1="0" x2="0" y2="1">
                              <stop offset="5%" stopColor="#f97316" stopOpacity={0.2}/>
                              <stop offset="95%" stopColor="#f97316" stopOpacity={0}/>
                            </linearGradient>
                          </defs>
                          <CartesianGrid vertical={false} stroke="#334155" />
                          <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                          <Tooltip 
                            contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #334155', borderRadius: '8px', color: '#fff', fontSize: '12px' }}
                            itemStyle={{ color: '#fff' }}
                            formatter={(value: any) => [`₹${value}`, ''] as [string, string]}
                          />
                          <Area type="monotone" dataKey="revenue" stroke="#f97316" strokeWidth={3} fillOpacity={1} fill="url(#colorRev)" />
                        </AreaChart>
                      </ResponsiveContainer>
                  )}
              </div>
              <div className="mt-4 pt-4 border-t border-slate-800 text-center">
                  <p className="text-xs text-slate-400">Total revenue for the week</p>
                  <p className="text-xl font-bold text-white mt-1">₹{analytics.revenueData.reduce((acc, curr) => acc + curr.revenue, 0)}</p>
              </div>
          </div>
        </div>
      )}

      {/* 4. KITCHEN TAB (Orders) */}
      {activeTab === 'kitchen' && (
        <div className="animate-in fade-in">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {/* Step 1: Confirmed */}
            <div className="bg-blue-900/10 rounded-3xl border border-blue-900/30 p-4 h-full">
                <div className="flex items-center justify-between mb-4 px-2">
                    <div className="flex items-center space-x-2">
                        <div className="bg-blue-900/40 text-blue-400 font-bold w-6 h-6 rounded-full flex items-center justify-center text-xs">1</div>
                        <h3 className="font-bold text-blue-300">New Orders</h3>
                    </div>
                    <span className="bg-slate-900 text-blue-400 px-2 py-1 rounded-lg text-xs font-bold border border-blue-900/30">
                        {orders.filter(o => o.status === OrderStatus.CONFIRMED).length}
                    </span>
                </div>

                <div className="space-y-3">
                    {orders.filter(o => o.status === OrderStatus.CONFIRMED).map(order => (
                        <div key={order.id} className="bg-slate-900 p-4 rounded-2xl shadow-sm border border-blue-900/30 hover:shadow-md transition-shadow">
                            <div className="flex justify-between items-start mb-3">
                                <span className="text-xs font-bold text-slate-500">#{order.id}</span>
                                <span className="text-xs font-bold bg-slate-800 text-slate-300 px-2 py-1 rounded">{order.pickupTime}</span>
                            </div>
                            <div className="space-y-1 mb-4">
                                {order.items.map((i, idx) => (
                                    <div key={idx} className="flex justify-between text-sm font-medium text-slate-300">
                                        <span>{i.name}</span>
                                        <span className="text-orange-500 font-bold">x{i.quantity}</span>
                                    </div>
                                ))}
                            </div>
                            <button 
