                                Start Cooking <ArrowRight className="w-4 h-4 ml-2" />
                            </button>
                        </div>
                    ))}
                    {orders.filter(o => o.status === OrderStatus.CONFIRMED).length === 0 && (
                        <div className="text-center py-10 text-slate-500 text-sm">No new orders</div>
                    )}
                </div>
            </div>

            {/* Step 2: Preparing */}
            <div className="bg-orange-900/10 rounded-3xl border border-orange-900/30 p-4 h-full">
                <div className="flex items-center justify-between mb-4 px-2">
                    <div className="flex items-center space-x-2">
                        <div className="bg-orange-900/40 text-orange-400 font-bold w-6 h-6 rounded-full flex items-center justify-center text-xs">2</div>
                        <h3 className="font-bold text-orange-300">Cooking</h3>
                    </div>
                    <span className="bg-slate-900 text-orange-400 px-2 py-1 rounded-lg text-xs font-bold border border-orange-900/30">
                        {orders.filter(o => o.status === OrderStatus.PREPARING).length}
                    </span>
                </div>

                <div className="space-y-3">
