import React, { useState, useRef, useEffect } from 'react';
import { MessageCircle, X, Send, Bot, Sparkles } from 'lucide-react';
import { chatWithSupport } from '../services/geminiService';

interface Message {
  id: string;
  sender: 'user' | 'bot';
  text: string;
}

const Chatbot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', sender: 'bot', text: 'Hi! I can help with orders, pickup slots, or payment issues. How can I assist you today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg: Message = { id: Date.now().toString(), sender: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    const botResponse = await chatWithSupport(input, []);

    setIsTyping(false);
    setMessages(prev => [...prev, { id: (Date.now() + 1).toString(), sender: 'bot', text: botResponse || "Sorry, I'm offline." }]);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[60] flex flex-col items-end">
      {isOpen && (
        <div className="mb-4 w-80 sm:w-96 h-[500px] bg-slate-900 border border-slate-800 rounded-3xl shadow-2xl flex flex-col overflow-hidden animate-in fade-in slide-in-from-bottom-10 duration-300">
          {/* Header */}
          <div className="p-4 bg-slate-950 flex items-center justify-between border-b border-slate-800">
            <div className="flex items-center space-x-3">
              <div className="bg-gradient-to-tr from-pink-500 to-orange-500 p-2 rounded-full shadow-lg">
                <Bot className="w-5 h-5 text-white" />
              </div>
              <div>
                <h3 className="text-white font-bold text-sm">Support AI</h3>
                <div className="flex items-center space-x-1">
                   <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></div>
                   <p className="text-slate-400 text-xs">Online</p>
                </div>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="text-slate-400 hover:text-white transition-colors bg-white/5 p-1.5 rounded-full">
              <X className="w-4 h-4" />
            </button>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-900 custom-scrollbar">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] px-4 py-3 rounded-2xl text-sm leading-relaxed shadow-sm ${
                  msg.sender === 'user' 
                    ? 'bg-orange-600 text-white rounded-tr-sm' 
                    : 'bg-slate-800 text-slate-200 rounded-tl-sm border border-slate-700'
                }`}>
                  {msg.text}
                </div>
              </div>
            ))}
            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-slate-800 px-4 py-3 rounded-2xl rounded-tl-sm border border-slate-700 flex space-x-1 shadow-sm">
                  <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                  <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                  <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                </div>
              </div>
            )}
          </div>

          {/* Input */}
          <div className="p-3 bg-slate-900 border-t border-slate-800">
            <div className="flex items-center space-x-2 bg-slate-800 rounded-full px-4 py-2 border border-slate-700 focus-within:border-orange-500/50 focus-within:ring-2 focus-within:ring-orange-900/20 transition-all">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Ask anything..." 
                className="flex-1 bg-transparent border-none focus:ring-0 text-sm text-white placeholder-slate-500"
              />
              <button 
                onClick={handleSend}
                disabled={!input.trim()}
                className="text-orange-500 hover:text-orange-400 disabled:opacity-50 p-1.5 bg-slate-700 rounded-full shadow-sm hover:shadow-md transition-all"
              >
                <Send className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      )}

      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`p-4 rounded-full shadow-xl shadow-orange-900/30 transition-all duration-300 transform hover:scale-105 ${
          isOpen ? 'bg-slate-700 text-white rotate-90' : 'bg-gradient-to-r from-orange-500 to-pink-500 text-white'
        }`}
      >
        {isOpen ? <X className="w-6 h-6" /> : <MessageCircle className="w-6 h-6" />}
      </button>
    </div>
  );
};

export default Chatbot;

import React, { useEffect, useState } from 'react';
import { AppNotification, User, UserRole, OrderStatus } from '../types';
import { db } from '../services/supabaseService';
import { Bell, X, CheckCircle, AlertTriangle, Info, ChefHat, Flame, Package } from 'lucide-react';

export const useNotificationSystem = () => {
    const [notifications, setNotifications] = useState<AppNotification[]>([]);
    const [toasts, setToasts] = useState<AppNotification[]>([]);

    useEffect(() => {
        // Load history from local storage
        const stored = localStorage.getItem('qb_notifications');
        if (stored) {
            setNotifications(JSON.parse(stored));
        }

        const handleEvent = (e: CustomEvent) => {
            const user = db.getCurrentUser();
            if (!user) return;

            const { type, payload } = e.detail;
            let newNotif: AppNotification | null = null;

            // 1. ADMIN LOGIC
            if (user.role === UserRole.ADMIN || user.role === UserRole.SPECIALIZED_ADMIN) {
                if (type === 'ORDER_CREATED') {
                    newNotif = {
                        id: Date.now().toString(),
                        title: 'New Order Received',
                        message: `Order #${payload.id} placed. ₹${payload.totalAmount}`,
                        type: 'info',
                        timestamp: Date.now(),
                        read: false,
                        targetRole: UserRole.ADMIN
                    };
                } else if (type === 'KITCHEN_HIGH_LOAD') {
                    newNotif = {
                        id: Date.now().toString(),
                        title: 'Kitchen Overload Warning',
                        message: `High volume! ${payload.activeCount} orders active.`,
                        type: 'warning',
                        timestamp: Date.now(),
                        read: false,
                        targetRole: UserRole.ADMIN
                    };
                }
            }

            // 2. CUSTOMER LOGIC
            if (user.role === UserRole.CUSTOMER) {
                if (type === 'ORDER_UPDATED' && payload.id) {
                    // In a real app, verify user.id === order.userId. 
                    // For simulation, we assume if the customer is logged in, they want updates on their orders.

                    let title = 'Order Update';
                    let message = `Order #${payload.id} is now ${payload.status}`;
                    let notifType: 'info' | 'success' | 'warning' = 'info';

                    if (payload.status === OrderStatus.PREPARING) {
                        title = 'Chef is Cooking! 🍳';
                        message = `Your order #${payload.id} is being prepared.`;
                        notifType = 'info';
                    } else if (payload.status === OrderStatus.READY) {
                        title = 'Order Ready! 🥡';
                        message = `Order #${payload.id} is ready for pickup!`;
                        notifType = 'success';
                    } else if (payload.status === OrderStatus.COMPLETED) {
                        title = 'Enjoy your meal! 😋';
                        message = `Order #${payload.id} completed.`;
                        notifType = 'success';
                    }

                    newNotif = {
                        id: Date.now().toString(),
                        title,
                        message,
                        type: notifType,
                        timestamp: Date.now(),
                        read: false,
                        targetRole: UserRole.CUSTOMER
                    };
                }
            }

            if (newNotif) {
                addNotification(newNotif);
            }
        };

        window.addEventListener('qb-notification' as any, handleEvent);
        return () => window.removeEventListener('qb-notification' as any, handleEvent);
    }, []);

    const addNotification = (n: AppNotification) => {
        playNotificationSound(n.type);
        setNotifications(prev => {
            const updated = [n, ...prev].slice(0, 50); // Keep last 50
            localStorage.setItem('qb_notifications', JSON.stringify(updated));
            return updated;
        });
        setToasts(prev => [...prev, n]);

        // Auto dismiss toast after 5s
        setTimeout(() => {
            setToasts(prev => prev.filter(t => t.id !== n.id));
        }, 5000);
    };

    const markAllRead = () => {
        const updated = notifications.map(n => ({ ...n, read: true }));
        setNotifications(updated);
        localStorage.setItem('qb_notifications', JSON.stringify(updated));
    };

    const clearToasts = (id: string) => {
        setToasts(prev => prev.filter(t => t.id !== id));
    };

    return { notifications, toasts, markAllRead, clearToasts };
};

// --- SOUND UTILITY ---
const playNotificationSound = (type: string) => {
    try {
        const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
        if (!AudioContext) return;

        const ctx = new AudioContext();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();

        osc.connect(gain);
        gain.connect(ctx.destination);

        const now = ctx.currentTime;

        if (type === 'success') {
            // Happy "Ding"
            osc.type = 'sine';
            osc.frequency.setValueAtTime(523.25, now); // C5
            osc.frequency.exponentialRampToValueAtTime(1046.5, now + 0.1); // C6
            gain.gain.setValueAtTime(0.1, now);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.5);
            osc.start(now);
            osc.stop(now + 0.5);
        } else if (type === 'warning') {
            // Low "Bloop"
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(200, now);
            gain.gain.setValueAtTime(0.1, now);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.4);
            osc.start(now);
            osc.stop(now + 0.4);
        } else {
            // Standard "Pop"
            osc.type = 'sine';
            osc.frequency.setValueAtTime(440, now);
            gain.gain.setValueAtTime(0.05, now);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
            osc.start(now);
            osc.stop(now + 0.3);
        }
    } catch (e) {
        console.warn("Audio play failed", e);
    }
};

